  ('cpiuris2025::894f9b4b4166c388b92a2a2ec2cb19a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas e reconhecimento de pessoas e coisas', '## Testemunhas e reconhecimento de pessoas e coisas

Descreve as diferentes categorias de testemunhas (direta, indireta, remota) e o reconhecimento de pessoas e coisas no processo penal.

### Conceitos
- **Testemunha direta**: Depõe sobre fatos que presenciou ou visualizou
- **Testemunha indireta**: Declara ao magistrado sobre o que não presenciou, mas soube ou ouviu dizer
- **Testemunha remota**: Presta seu depoimento por videoconferência
- **Reconhecimento de pessoas e coisas**: Procedimento que visa identificar pessoas e coisas no processo penal

### Referências legais
- Art. 209, caput, CPP
- Art. 226 a 228, CPP

### Dicas de prova
- Distinção entre testemunhas diretas e indiretas
- Conhecimento do termo ''testemunha remota''
- Entendimento do artigo 209 do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 209, caput, CPP", "Art. 226 a 228, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:39:09.953160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=347", "doc_key": "894f9b4b4166c388b92a2a2ec2cb19a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0702a21cadb485f734d75012efc401bdb04546e6e9bc7e44b8d638e516f3a94a'),
  ('cpiuris2025::fe1021588eb79a73a6826bbec697fdc9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de Pessoas e Coisas', '## Reconhecimento de Pessoas e Coisas

O reconhecimento de pessoas e coisas é meio de prova que pode ser realizado durante a investigação policial ou na instrução processual penal. É diferente do retrato falado, que é um meio de investigação.

### Conceitos
- **Reconhecimento de Pessoas**: Ato formal para identificar pessoa ou coisa
- **Meio de Prova**: Sistema utilizado para provar a existência de um fato
- **Reconhecimento de Coisas**: Ato formal para identificar objeto ou coisa
- **Retratado Falado**: Informações prestadas ao perito por pessoa que viu o autor do delito, não considerado meio de prova

### Referências legais
- Art. 226, caput, do CPP

### Dicas de prova
- Entenda a diferença entre reconhecimento de pessoas e retratado falado
- Conheça as fases do procedimento do reconhecimento de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.348 (1)", "page_number": 348, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:41:18.672015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=348", "doc_key": "fe1021588eb79a73a6826bbec697fdc9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '08dca4da9858f6271c4f9557906170198b8a1c43f24ef61d36b333592a8d2f78'),
  ('cpiuris2025::fbfbea30abc796271e8a47442642e06d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de Pessoas e Coisas', '## Reconhecimento de Pessoas e Coisas

O procedimento de reconhecimento de pessoas e coisas é individualizado, com cada pessoa fazendo a prova em separado, evitando-se comunicação entre elas. O descumprimento do rito formal não enseja nulidade do ato.

### Conceitos
- **Reconhecimento de Pessoas e Coisas**: Procedimento individualizado para identificação de pessoas e coisas
- **Individualidade**: Característica que evita comunicação entre as pessoas realizando a prova
- **Rito Formal**: Requisito legal para o reconhecimento de pessoas e coisas
- **Nulidade do Ato**: Consequência do descumprimento do rito formal, não ensejada pela jurisprudência

### Referências legais
- Art. 228 do CPP
- Art. 226, caput, do CPP

### Jurisprudência
- HC 7.802/RJ
- Súmula 387/STF

### Dicas de prova
- Pegar a individualidade como característica que evita comunicação entre as pessoas
- Distinção entre rito formal e nulidade do ato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.348 (2)", "page_number": 348, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 228 do CPP", "Art. 226, caput, do CPP"], "jurisprudence": ["HC 7.802/RJ", "Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:41:28.026570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=348", "doc_key": "fbfbea30abc796271e8a47442642e06d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a43c5b6c14f4ac9be305cf483d247f72e31a7b550776b98c55e5b2b93fcca711'),
  ('cpiuris2025::cf713fa3e56fccccd044728bbb704f3b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de Pessoas em Provas', '## Reconhecimento de Pessoas em Provas

A regra jurisprudencial atual prevalece na observância do art. 226 do Código de Processo Penal para o reconhecimento de pessoas, garantindo a segurança do reconhecedor e a livre produção da prova.

### Conceitos
- **Reconhecimento de Pessoas**: Prova que consiste na identificação de uma pessoa por um reconhecedor
- **Art. 226 do Código de Processo Penal**: Regula o procedimento para o reconhecimento de pessoas, garantindo a segurança do reconhecedor e a livre produção da prova
- **Vínculo entre Reconhecedor e Pessoas a Serem Reconhecidas**: Situação em que não é necessário seguir o rito procedimental do art. 226 do CPP, como no caso de parentesco ou conhecimento mútuo
- **Proteção ao Reconhecedor**: Medidas para garantir a segurança do reconhecedor, evitando intimidação ou influência que possa afetar a verdadeira identificação da pessoa

### Referências legais
- Art. 226 do Código de Processo Penal

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça, que assentou a regra jurisprudencial atual sobre o reconhecimento de pessoas''}
- {''term'': ''Info. 1045'', ''definition'': ''Informativo do STF que bateu sobre a nulidade do ato em caso de descumprimento das formalidades exigidas para o reconhecimento de pessoas''}

### Dicas de prova
- {''term'': ''Distinção entre procedimento em juízo e proteção ao reconhecedor'', ''definition'': ''Importância de entender a diferença entre as medidas que garantem a segurança do reconhecedor e o procedimento para o reconhecimento de pessoas''}
- {''term'': ''Consequências da não observância das formalidades do art. 226 do CPP'', ''definition'': ''Riscos de nulidade do ato e absolvição do réu em caso de descumprimento das formalidades exigidas para o reconhecimento de pessoas''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.349 (1)", "page_number": 349, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226 do Código de Processo Penal"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça, que assentou a regra jurisprudencial atual sobre o reconhecimento de pessoas''}", "{''term'': ''Info. 1045'', ''definition'': ''Informativo do STF que bateu sobre a nulidade do ato em caso de descumprimento das formalidades exigidas para o reconhecimento de pessoas''}"], "confidence": 0.8, "extracted_at": "2026-05-29T03:43:07.817912+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=349", "doc_key": "cf713fa3e56fccccd044728bbb704f3b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8574b97da5f7ac35da0fca1067088a5fe17ea23877d82d56c326ce47c85416c6'),
  ('cpiuris2025::960df19b0a250ded484afbcfc9f6b55e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento e identidade do reconhecedor', '## Reconhecimento e identidade do reconhecedor

A proteção ao reconhecedor somente é válida na fase de investigação criminal, mas atualmente a jurisprudência não aplica esse direito em plenário do Júri.

### Conceitos
- **Reconhecimento fotográfico**: Uso de técnicas fotográficas para identificar o reconhecedor
- **Princípio da busca da verdade real**: O direito de buscar a verdade real em todas as etapas do processo
- **Princípio da liberdade na produção das provas**: O direito do acusado de escolher os meios de produção de suas provas

### Referências legais
- Art. 226, parágrafo único, do CPP

### Jurisprudência
- AVENA (2017), p. 410; STJ, 6ª Turma, HC 598.886-SC, Rel. Min. Rogerio Schietti Cruz, julgado em 27/10/2020

### Dicas de prova
- Entenda a diferença entre reconhecimento e identidade do reconhecedor
- Conheça os princípios da busca da verdade real e liberdade na produção das provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.349 (2)", "page_number": 349, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226, parágrafo único, do CPP"], "jurisprudence": ["AVENA (2017), p. 410; STJ, 6ª Turma, HC 598.886-SC, Rel. Min. Rogerio Schietti Cruz, julgado em 27/10/2020"], "confidence": 0.8, "extracted_at": "2026-05-29T03:43:29.378487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=349", "doc_key": "960df19b0a250ded484afbcfc9f6b55e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '337cabe4f2f6561469848fd1ab798cd97781fdbebba60818120b94f00e985fc7'),
  ('cpiuris2025::5bf43328d77923f905b09879505d8447', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento fotográfico e fonográfico no processo penal', '## Reconhecimento fotográfico e fonográfico no processo penal

O reconhecimento fotográfico e fonográfico são meios de prova admitidos, mas com restrições. O reconhecimento fotográfico deve respeitar o rigor procedimental do artigo 226 do CPP e não pode ser usado para lastrear juízo de certeza da autoria do crime. Já o reconhecimento fonográfico não é suficiente para decreto condenatório, mas pode ser utilizado como etapa antecedente a eventual reconhecimento pessoal.

### Conceitos
- **Reconhecimento fotográfico**: Meio de prova que utiliza uma imagem para identificar uma pessoa
- **Reconhecimento fonográfico**: Meio de prova que utiliza a voz de uma pessoa para identificá-la
- **Procedimento do artigo 226 do CPP**: Rigor procedimental que deve ser respeitado no reconhecimento fotográfico
- **Exame pericial de verificação de locutor**: Exame feito por perito oficial para verificar a autenticidade de uma voz gravada

### Referências legais
- Art. 226 do CPP
- STJ: HC 817.270/RJ, Rel. Min. Antonio Saldanha Palheiro, julgado em 06/08/2024

### Jurisprudência
- RE 123456
- Info. 730
- Info. 684

### Dicas de prova
- Pergunte sobre as restrições para o uso do reconhecimento fotográfico no processo penal
- Entenda a diferença entre exame pericial de verificação de locutor e reconhecimento fonográfico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.350 (1)", "page_number": 350, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226 do CPP", "STJ: HC 817.270/RJ, Rel. Min. Antonio Saldanha Palheiro, julgado em 06/08/2024"], "jurisprudence": ["RE 123456", "Info. 730", "Info. 684"], "confidence": 0.8, "extracted_at": "2026-05-29T03:44:26.141896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=350", "doc_key": "5bf43328d77923f905b09879505d8447"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3279f4309a2f3a724ccc768e9337355bf22d9c71cad9069dfac0aeba80ebe137'),
  ('cpiuris2025::3ae46221f667430305cc8a3e99daf367', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento por videoconferência', '## Reconhecimento por videoconferência

O reconhecimento por videoconferência é permitido para o reconhecedor ou a pessoa que deve ser reconhecida presa, desde que se cumpram os demais requisitos, nos termos do art. 185, §8º, do Código de Processo Penal.

### Conceitos
- **videoconferência**: reconhecimento por meio de conexão de vídeo
- **art. 185, §8º, Código de Processo Penal**: disposição que permite o reconhecimento por videoconferência

### Referências legais
- Art. 185, §8º, Código de Processo Penal

### Dicas de prova
- Distinção entre reconhecimento presencial e reconhecimento por videoconferência
- Requisitos para o reconhecimento por videoconferência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.350 (2)", "page_number": 350, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 185, §8º, Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:44:57.245351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=350", "doc_key": "3ae46221f667430305cc8a3e99daf367"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0017e7d27fb08932c23ec4cf9feada4a3d9a2d481ca0cb90d6051bc763f7fde8'),
  ('cpiuris2025::6560f515f04f59345e871efb06c3c551', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acareação', '## Acareação

A acareação é o ato processual em que pessoas que já foram ouvidas sobre um fato são reperguntadas sobre divergências existentes entre suas versões.

### Conceitos
- **acareação**: ato processual em que pessoas são colocadas frente a frente e reperguntadas sobre divergências
- **divergência**: contradição ou versão discrepante sobre fatos relevantes ao deslinde do processo
- **testemunha ausente**: testemunha que não comparece a um procedimento

### Referências legais
- Art. 229, caput, do CPP; Art. 230 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de acareação e seus pressupostos.
- Conheça as possibilidades de acareação previstas no Código de Processo Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.351", "page_number": 351, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 229, caput, do CPP; Art. 230 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:45:28.229098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=351", "doc_key": "6560f515f04f59345e871efb06c3c551"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc02beb12c173cb3360dc43aaab82b549d184103a11b826caee8bcfec4f7c3c1'),
  ('cpiuris2025::9e3e513eabf4bfbb9e341cd03045c935', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova Documental', '## Prova Documental

A prova documental pode ser apresentada em qualquer fase do processo, desde que submetida ao contraditório. A reprodução de documentos autenticados tem o mesmo valor do original.

### Conceitos
- **Contraditório**: O direito de as partes opor-se à admissão de provas
- **Prova documental**: A apresentação de documentos como prova no processo
- **Autenticação**: O ato de verificar a autenticidade de um documento
- **Fotocópia**: Uma cópia de um documento feita por meio de fotografia
- **Documentos privados e públicos**: Os documentos que podem ser apresentados como prova no processo

### Referências legais
- Art. 232, parágrafo único, do CPP
- Art. 231 do CPP

### Jurisprudência
- RE 123456
- Info. 711 do STJ

### Dicas de prova
- Entenda a diferença entre prova documental e documento privado/público
- Conheça o conceito de autenticação e sua importância no processo
- Aprenda a distinguir entre fotocópia e cópia original', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.353", "page_number": 353, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 232, parágrafo único, do CPP", "Art. 231 do CPP"], "jurisprudence": ["RE 123456", "Info. 711 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T03:47:09.300895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=353", "doc_key": "9e3e513eabf4bfbb9e341cd03045c935"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '819411d74be9280168a3e7c92154dea1ceaca2e18c5d518c0d7adfd35b1b58ed'),
  ('cpiuris2025::8bde87e7957f5b62359fe5630f6452a1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Documentos e Instrumentos em Provas', '## Documentos e Instrumentos em Provas

Os documentos são considerados escritos, instrumentos ou papéis públicos ou particulares. A doutrina distingue entre documento lato sensu (capaz de retratar uma situação fática) e documento stricto sensu (escrito não elaborado com o propósito direcionado de ser utilizado como prova).

### Conceitos
- **documento**: escrito, instrumento ou papel público ou particular
- **instrumento**: documento confeccionado com o objetivo específico de servir de prova do ato nele materializado
- **documento lato sensu**: capaz de retratar uma situação fática, seja por meio de áudio ou vídeo
- **documento stricto sensu**: escrito não elaborado com o propósito direcionado de ser utilizado como prova
- **instrumento público**: aquele constituído perante a autoridade pública, com capacidade para lhe atribuir a presunção de verdade
- **instrumento particular**: aquele para cuja constituição não houve a contribuição de qualquer agente público no exercício de função pública
- **documento público**: todo escrito que não foi elaborado com o propósito direcionado de ser utilizado como prova, embora eventualmente possa vir a ter essa finalidade
- **documento particular**: escrito não elaborado com o propósito direcionado de ser utilizado como prova

### Referências legais
- Art. 232 do CPP

### Dicas de prova
- Entenda a distinção entre documento lato sensu e documento stricto sensu.
- Conheça as espécies de instrumentos (públicos e particulares).
- Aprenda a importância da presunção de verdade nos documentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.352", "page_number": 352, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 232 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:47:38.460125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=352", "doc_key": "8bde87e7957f5b62359fe5630f6452a1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '841fb6ff06aedcc1a8d78a3d895b25bd6ba23f1ad5e41d6d887b7297424da485'),
  ('cpiuris2025::499f503361685007af5939fe28e6cae5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo de juntada de documentos e ciência da parte contrária', '## Prazo de juntada de documentos e ciência da parte contrária

O prazo de 3 dias úteis para a juntada de documentos deve ser respeitado, não apenas para a juntada de documentos ou objetos, mas também para a ciência da parte contrária sobre sua utilização no Tribunal do Júri.

### Conceitos
- **Prazo de juntada**: Período de tempo durante o qual uma ação deve ser concluída
- **Ciência da parte contrária**: Informação dada à parte adversa sobre a utilização de um documento ou objeto no Tribunal do Júri
- **Tribunal do Júri**: Instituição que julga os casos criminais, composta por jurados eleitos pelo poder popular

### Referências legais
- Art. 479 do Código de Processo Penal
- Art. 233 do CPP
- Art. 234 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do prazo de juntada de documentos e sua relação com a ciência da parte contrária.
- Conheça as regras para a admissão ou não de cartas particulares em juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.354 (1)", "page_number": 354, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 479 do Código de Processo Penal", "Art. 233 do CPP", "Art. 234 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:47:51.774875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=354", "doc_key": "499f503361685007af5939fe28e6cae5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2e2d726e96bb2556aa4572a576ae192992b867894b56eb387084d7ee52aca48b'),
  ('cpiuris2025::b9ad311c31570f3bd26a7321a501052f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indício como meio de prova', '## Indício como meio de prova

O indício é considerado uma prova semiplena, com menor valor persuasivo, e seu uso requer cautela e exige lógica e proximidade com o fato a ser provado.

### Conceitos
- **Indício**: Meio de prova mais tênue, com menor valor persuasivo
- **Prova semiplena**: Elemento de prova com menor valor persuasivo

### Referências legais
- Art. 214 do Código de Processo Penal

### Jurisprudência
- STJ, HC 15.736/MG
- STF, HC 70.344/RJ

### Dicas de prova
- Entenda a diferença entre indício e prova semiplena
- Avalie o valor persuasivo do indício em relação ao fato a ser provado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 214 do Código de Processo Penal"], "jurisprudence": ["STJ, HC 15.736/MG", "STF, HC 70.344/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T03:49:18.128768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=355", "doc_key": "b9ad311c31570f3bd26a7321a501052f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ed0f1fb69c0d330a4d2c1f7e8845634cc5e30e2e924cf5832c7987e063361747'),
  ('cpiuris2025::31311ff41bde2376cd6dbeef9a67e0ae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Documentos em língua estrangeira no processo', '## Documentos em língua estrangeira no processo

O artigo 236 do CPP estabelece que os documentos em língua estrangeira devem ser traduzidos por tradutor público ou pessoa idônea, mas a juntada é imediata. A doutrina sustenta que a tradução é necessária mesmo se as partes conhecem a língua estrangeira, devido ao princípio da publicidade dos atos processuais.

### Conceitos
- **Acessibilidade**: O direito do público à visibilidade do conteúdo do documento
- **Documentos em língua estrangeira**: Materiais apresentados no processo que não são em português
- **Juntada imediata**: A inclusão de documentos em língua estrangeira nos autos do processo sem necessidade de tradução
- **Princípio da publicidade dos atos processuais**: O direito do público à visibilidade e transparência dos atos processuais
- **Tradução de documentos**: A conversão de documentos em língua estrangeira para português
- **Tradutor público**: Pessoa qualificada para realizar a tradução de documentos
- **Pessoa idônea**: Pessoa capacitada para realizar a tradução de documentos

### Referências legais
- Art. 236 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo da publicidade dos atos processuais

### Dicas de prova
- Entenda o princípio da publicidade dos atos processuais e sua importância na tradução de documentos em língua estrangeira
- Conheça as regras para a juntada e tradução de documentos em processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.354 (2)", "page_number": 354, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 236 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo da publicidade dos atos processuais"], "confidence": 0.8, "extracted_at": "2026-05-29T03:50:13.993342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=354", "doc_key": "31311ff41bde2376cd6dbeef9a67e0ae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2bda69957ec028799c3ffa2412627c83e79e5b63213bb2a6efe0f3b163858189'),
  ('cpiuris2025::40216fed22e4df7e468932c68f63b799', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Restituição de documentos e Indícios', '## Restituição de documentos e Indícios

O art. 238 do CPP permite a restituição de documentos originais ao autor, desde que não haja motivo relevante para sua conservação nos autos. Além disso, o vocábulo ''indício'' é usado em dois sentidos: como prova indireta e como prova semiplena.

### Conceitos
- **Restituição de documentos**: A devolução de documentos originais ao autor do processo, quando não houver motivo relevante para sua conservação nos autos.
- **Indício**: Circunstância conhecida e provada que autoriza a concluir-se a existência de outra ou outras circunstâncias
- **Prova indireta**: Prova que não é direta, mas que autoriza a concluir-se a existência de um fato
- **Prova semiplena**: Tipo de prova que é mais forte do que a prova indireta, mas menos forte do que a prova direta

### Referências legais
- Art. 238 do CPP
- Art. 239 do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre prova indireta e semiplena.
- Conheça o artigo 238 e 239 do CPP.
- Aprenda a aplicar os conceitos de restituição de documentos e indícios em práticas jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 238 do CPP", "Art. 239 do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:50:31.745405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=355", "doc_key": "40216fed22e4df7e468932c68f63b799"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3c2f1de03a1290fc4902ffbb69e1eedf577ddc0922bc00acccf7d7486c551093'),
  ('cpiuris2025::54ea10970728b41f4ad17984e81ebe12', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Indícios e Contraindícios em Provas', '## Indícios e Contraindícios em Provas

Resumo do texto sobre indícios, contraindícios e busca/apreensão no processo penal.

### Conceitos
- **Indício**: Cognição vertical não exauriente ou sumária
- **Contraindício**: Circunstâncias que invalidam os indícios em determinadas condições e circunstâncias
- **Busca**: Movimento desencadeado pelos agentes do Estado para investigação, descoberta e pesquisa de algo interessante para o processo penal
- **Apreensão**: Medida assecuratória que toma algo de alguém ou de algum lugar com a finalidade de produzir prova ou preservar direitos

### Referências legais
- Art. 126 do Código de Processo Penal
- Art. 312 do Código de Processo Penal
- Art. 413, caput do Código de Processo Penal
- Art. 242 do Código de Processo Penal

### Dicas de prova
- Diferenciar busca e apreensão
- Entender a cognição vertical e não exauriente
- Conhecer as condições e circunstâncias que invalidam os indícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.356", "page_number": 356, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 126 do Código de Processo Penal", "Art. 312 do Código de Processo Penal", "Art. 413, caput do Código de Processo Penal", "Art. 242 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:51:52.314395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=356", "doc_key": "54ea10970728b41f4ad17984e81ebe12"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '18841066c98a74d2e85b36666829b3592ccca2be6cb59edec9e3ce4e81af0d11'),
  ('cpiuris2025::069143d83b01e3080e875d540ded6014', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Busca e Apreensão', '## Mandado de Busca e Apreensão

O mandado de busca e apreensão deve indicar precisamente a casa ou pessoa que será submetida à medida, seja para busca domiciliar ou pessoal.

### Conceitos
- **Mandado de Busca e Apreensão**: Documento judicial que autoriza a realização de uma busca e apreensão
- **Busca Domiciliar**: Realização de uma busca em um local residencial
- **Busca Pessoal**: Realização de uma busca em uma pessoa

### Referências legais
- Art. 243 do CPP

### Dicas de prova
- Perguntas sobre a formalidade do mandado de busca e apreensão
- Distinção entre busca domiciliar e pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 243 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T03:52:00.261308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=357", "doc_key": "069143d83b01e3080e875d540ded6014"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9cec240578c4187177a158abf5695434afe9adaf3a0167f306c846c064b94fbd'),
  ('cpiuris2025::af365090852244128e2ea5ddfe2cf39a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Apreensão Domiciliar e Pessoal', '## Busca e Apreensão Domiciliar e Pessoal

A busca e apreensão domiciliar depende de determinação judicial, enquanto a busca pessoal de natureza processual penal também depende de mandado, que pode ser expedido por ordem do juiz ou autoridade policial.

### Conceitos
- **Busca e Apreensão Domiciliar**: busca e apreensão realizada em domicílio
- **Busca Pessoal de Natureza Processual Penal**: busca realizada com o objetivo de coletar provas para a persecução criminal
- **Mandado Judicial**: ordem judicial que autoriza a busca e apreensão
- **Mandado de Busca e Apreensão Pessoal**: mandado expedido por ordem do juiz ou autoridade policial para buscar e apreender pessoas
- **Iniciativa Probatória**: iniciativa do juiz para coletar provas para a persecução criminal

### Referências legais
- Art. 5º, inciso XI da CF/88
- Art. 244 do CPP
- Art. 6º, inciso II do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar busca e apreensão domiciliar de busca pessoal de natureza processual penal
- Entender a necessidade de mandado judicial para busca e apreensão domiciliar, mas não necessariamente para busca pessoal de natureza processual penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XI da CF/88", "Art. 244 do CPP", "Art. 6º, inciso II do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:52:15.112779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=357", "doc_key": "af365090852244128e2ea5ddfe2cf39a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '40371651b0165ceaf72c7c7ff0283d2eb7b2a2de3ba4b00f1a76be05018f9bb2'),
  ('cpiuris2025::fae90ba1dbbc2a012d1fdb6f3326b8c3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal em Provas', '## Busca Pessoal em Provas

A busca pessoal em provas pode ocorrer sem mandado em casos específicos, como prisão do sujeito ou fundada suspeita de estar carregando arma proibida ou objetos relacionados ao delito.

### Conceitos
- **Busca Pessoal**: Ação realizada por autoridade para buscar objetos ou informações em pessoa
- **Mandado de Busca**: Ordem judicial que autoriza a busca pessoal
- **Inviolabilidade Pessoal**: Direito do indivíduo à privacidade e segurança em sua vida pessoal

### Referências legais
- Art. 244 do CPP

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a distinção entre busca pessoal e mandado de busca
- Conheça as exceções à regra geral de necessidade de mandado para busca pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.359 (1)", "page_number": 359, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 244 do CPP"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T03:54:18.112889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=359", "doc_key": "fae90ba1dbbc2a012d1fdb6f3326b8c3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '76ff9c18c305bd06287f6c8036757d20729e560cce99a2d61c7b4044850a2c91'),
  ('cpiuris2025::3c750c258e230901f1368ac789047c08', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal', '## Busca Pessoal

A busca pessoal é realizada de maneira razoável e sem expor as pessoas a constrangimento ou à humilhação, tendo natureza contratual. A busca em revista pessoal feita por agentes de segurança particular é considerada ilícita.

### Conceitos
- **Busca Pessoal**: realização de buscas em pessoa
- **Execução da Busca Pessoal**: execução da medida com natureza contratual
- **Constrangimento**: exposição a situação humilhante ou desrespeitosa
- **Prova Obtida em Revista Pessoal**: prova obtida por meio de buscas em pessoa

### Referências legais
- Art. 240, §2º, do CPP

### Jurisprudência
- STJ: é ilícita a prova obtida em revista pessoal feita por agentes de segurança particular (Info 651)

### Dicas de prova
- Distinção entre busca pessoal processual penal e executiva
- Importância da razoabilidade na execução da busca pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240, §2º, do CPP"], "jurisprudence": ["STJ: é ilícita a prova obtida em revista pessoal feita por agentes de segurança particular (Info 651)"], "confidence": 0.8, "extracted_at": "2026-05-29T03:54:27.357479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=358", "doc_key": "3c750c258e230901f1368ac789047c08"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7b8aae09edc81c3d0a3d7f81e2855671f0e9c0683376985b47fa958f8ab60f88'),
  ('cpiuris2025::c677029ce3a333d0783690f7a168923a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandados de Busca e Apreensão', '## Mandados de Busca e Apreensão

Descreve as regras para a emissção e cumprimento de mandados de busca e apreensão, incluindo a necessidade de motivo e fins, assinatura do escrivão e autoridade, e restrições à busca domiciliar.

### Conceitos
- **Busca pessoal**: Diligência que recai sobre o corpo da pessoa, suas roupas ou objetos que tenha consigo
- **Busca domiciliar**: Diligência realizada em residência do acusado sem necessidade de mandado
- **Mandado de busca e apreensão genérico**: Mandado que autoriza a medida de busca e apreensão coletiva, genérica e indiscriminada
- **Ordem de prisão**: Ordem emitida pela autoridade judiciária para prendê-lo o acusado

### Referências legais
- Art. 243, inciso I, do CPP
- Art. 244, CPP
- §1º do artigo mencionado

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre busca pessoal e busca domiciliar
- Regras para a emissão de mandados de busca e apreensão genéricos
- Restrições à busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 243, inciso I, do CPP", "Art. 244, CPP", "§1º do artigo mencionado"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:55:04.648933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=358", "doc_key": "c677029ce3a333d0783690f7a168923a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bfdb6b0ae33598a0b18bd06d74e5427eea00ff54b01007c5610d08ea3a18e6bd'),
  ('cpiuris2025::818498e873a456d69bfb99cead8ab12a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal Policial', '## Busca Pessoal Policial

A busca pessoal policial pode ser realizada sem autorização judicial se o agente traz consigo algo de ilícito, mas está sujeita a restrições e exigências de razões concretas.

### Conceitos
- **Busca Pessoal Policial**: Realização da busca pessoal por agentes policiais
- **Autorização Judicial**: Não necessária em casos de busca com objeto ilícito
- **Justa Causa**: Exigência para a realização da busca pessoal
- **Conjecturas Policiais**: Não são suficientes para autorizar a busca

### Referências legais
- Art. 355, § 4º do CP
- ...

### Jurisprudência
- STJ - Info. 1132
- STJ - Info. 732
- STJ - Info. 735

### Dicas de prova
- Distinção entre busca pessoal com e sem autorização judicial
- Exigência de justa causa para a realização da busca pessoal
- Importância de elementos concretos na busca pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.359 (2)", "page_number": 359, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 355, § 4º do CP", "..."], "jurisprudence": ["STJ - Info. 1132", "STJ - Info. 732", "STJ - Info. 735"], "confidence": 0.8, "extracted_at": "2026-05-29T03:56:28.051070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=359", "doc_key": "818498e873a456d69bfb99cead8ab12a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'faa36a315d949d983ebc760b1437565e7669708c9583f56c9b10652224122ccc'),
  ('cpiuris2025::18bef9498b891c04b1ff60ef74c23b83', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Domiciliar e Pessoal', '## Busca Domiciliar e Pessoal

A busca domiciliar exige fundadas razões e finalidades específicas, como prender criminosos ou apreender coisas achadas. A busca pessoal em mulher deve ser feita por outra mulher, mas pode ser feita por um homem se importar retardamento ou prejuízo da diligência.

### Conceitos
- **Busca Domiciliar**: exigida fundadas razões e finalidades específicas
- **Inviolabilidade Domiciliar**: garantia constitucional protegida pela lei
- **Busca Pessoal em Mulher**: deve ser feita por outra mulher, exceto se importar retardamento ou prejuízo da diligência
- **Sequestro de Proventos**: sujeito a sequestro, não à busca e apreensão
- **Produto Direto da Infração**: objeto de busca e apreensão
- **Proveito da Infração**: objeto de sequestro

### Referências legais
- Art. 240, §1º, CPP; Art. 249, CPP; Art. 5º, XI, CF/88; Art. 126, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a finalidade da busca domiciliar e pessoal
- Conheça as regras específicas para a busca em mulher
- Diferencie entre produto direto e proveito da infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.360", "page_number": 360, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240, §1º, CPP; Art. 249, CPP; Art. 5º, XI, CF/88; Art. 126, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T03:57:09.725413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=360", "doc_key": "18bef9498b891c04b1ff60ef74c23b83"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e72a66d79b450e4c10593bfb50f2951d370e46dfc5a703f08a0617e175fe1a17'),
  ('cpiuris2025::1ae29ab63e74360596c36b385947cd4d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Domiciliar', '## Busca Domiciliar

A busca domiciliar pode ser realizada sem mandado judicial se o morador consentir, independentemente do horário. Caso não haja consentimento, a busca exigirá mandado judicial e será realizada durante o dia. Em caso de flagrante delito, a busca pode ser realizada independentemente do consentimento.

### Conceitos
- **Busca Domiciliar**: Ação realizada por autoridades para buscar um indivíduo em sua residência
- **Mandado Judicial**: Autorização judicial necessária para realizar a busca domiciliar quando não há consentimento do morador
- **Consentimento**: Ação do morador que autoriza a entrada na residência alheia
- **Flagrante Delito**: Situação em que a busca domiciliar pode ser realizada independentemente do consentimento do morador

### Referências legais
- Art. 5º, inciso XI, da CF/88
- Art. 245, caput, primeira parte, do CPP

### Jurisprudência
- STJ. 6ª Turma. HC 598.051/SP
- Info 760
- Info 687

### Dicas de prova
- Diferenciar entre busca domiciliar com e sem consentimento do morador
- Entender a necessidade de mandado judicial para busca domiciliar
- Conhecer as hipóteses em que a busca domiciliar pode ser realizada independentemente do consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.361 (1)", "page_number": 361, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XI, da CF/88", "Art. 245, caput, primeira parte, do CPP"], "jurisprudence": ["STJ. 6ª Turma. HC 598.051/SP", "Info 760", "Info 687"], "confidence": 0.8, "extracted_at": "2026-05-29T03:57:46.883472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=361", "doc_key": "1ae29ab63e74360596c36b385947cd4d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9cc657d71ea458350f2a9703e1429beeb0a2e0208e982bb2dc9e72de1849fcfa'),
  ('cpiuris2025::19171889dfd3bc139ec6f01054b0bf91', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Autorização de Morador para Ingresso de Policiais em Residência', '## Autorização de Morador para Ingresso de Policiais em Residência

A autorização de morador não é válida se induzido erro, contaminando toda a busca e apreensão. Os Tribunais Superiores exigem motivação para buscas pessoais, especialmente em busca domiciliar sem mandado judicial e consentimento do morador.

### Conceitos
- **Autorização de Morador**: Concessão de permissão para ingresso de policiais em residência
- **Busca Pessoal**: Ação realizada por um policial para identificar ou localizar uma pessoa
- **Mandado Judicial**: Decisão judicial que autoriza a realização de uma ação
- **Consentimento do Morador**: Aceitação da parte moradora à entrada de policiais em sua residência

### Referências legais
- Art. 355 do Código de Processo Penal
- Súmula 294 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Busca Pessoal e Autorização de Morador

### Dicas de prova
- Pergunta sobre autorização de morador
- Distinção entre busca pessoal com e sem motivação
- Importância do consentimento do morador em busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.361 (2)", "page_number": 361, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 355 do Código de Processo Penal", "Súmula 294 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Busca Pessoal e Autorização de Morador"], "confidence": 0.8, "extracted_at": "2026-05-29T03:58:44.401393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=361", "doc_key": "19171889dfd3bc139ec6f01054b0bf91"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a79a6ea3824906b3517d6016d49b8988b5acc333315adeffb706fde79ea1ff71'),
  ('cpiuris2025::71a18ccf23681e99a90e8889c95d66cd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas em Residência', '## Provas em Residência

A entrada em residência pode ser lícita se houver justa causa, mas não é necessária a expedição de mandado prévio para a busca policial. A busca em imóvel desabitado, como bunker, também é considerada lícita.

### Conceitos
- **Justa Causa**: Motivo legítimo e razoável para a entrada na residência
- **Busca Policial**: Ação realizada pela autoridade policial para coletar provas
- **Mandado de Busca e Apreensão**: Documento que autoriza a busca e apreensão de bens em residência ou imóvel
- **Busca em Imóvel Desabitado**: Acesso à residência sem morador, considerado lícito se houver justa causa

### Referências legais
- Art. 241 do CPP
- Info. 734
- Info. 738
- Info. 715
- Info. 826
- Art. 241, §1º do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo Info. 734/738/715

### Dicas de prova
- Distinção entre busca policial e busca judicial
- Importância da justa causa para a liceidade da entrada em residência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.362 (1)", "page_number": 362, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 241 do CPP", "Info. 734", "Info. 738", "Info. 715", "Info. 826", "Art. 241, §1º do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo Info. 734/738/715"], "confidence": 0.8, "extracted_at": "2026-05-29T03:59:45.079632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=362", "doc_key": "71a18ccf23681e99a90e8889c95d66cd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '127fbc1b01b26690a2d774fd9e2bb1af200b0b49d30b811d57307a2bfde48148'),
  ('cpiuris2025::5c5186a394f16b86ccd08aec0744d976', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução de Busca Domiciliar por Juíz', '## Execução de Busca Domiciliar por Juíz

A execução de busca domiciliar por juiz é objeto de debate, com algumas correntes argumentando que viola o sistema acusatório e a garantia da imparcialidade do magistrado.

### Conceitos
- **Juiz Inquisidor**: Figura histórica que autoriza o juiz a investigar e processar crimes sem a iniciativa da acusação.
- **Fase de Investigação**: Período do processo penal em que são realizadas as diligências para coletar provas.
- **Estrutura Acusatória**: Sistema processual que atribui a iniciativa da investigação e da procura de provas à acusação.
- **Busca Domiciliar**: Ação em que o juiz ordena a busca de um imóvel para coletar provas.
- **Imparcialidade do Magistrado**: Garantia constitucional que proíbe o magistrado de agir com vieses ou preconceitos.
- **Interpretação Conforme à Constituição**: Método jurídico que visa interpretar a lei de acordo com a Constituição.
- **Fase do Julgamento do Mérito**: Período em que são analisadas as provas coletadas durante a fase de investigação para decidir o caso.

### Referências legais
- Art. 129, I da CF
- Art. 3º-A do CPP
- Art. 156 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a fase de investigação e o julgamento do mérito.
- Interpretação sistemática do art. 3º-A do CPP com o art. 156 do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.362 (2)", "page_number": 362, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, I da CF", "Art. 3º-A do CPP", "Art. 156 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:00:50.543011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=362", "doc_key": "5c5186a394f16b86ccd08aec0744d976"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9a435dcd5a2d25b83781acc6bccd04406e5ac71248873be115722aae8d138b35'),
  ('cpiuris2025::a5a1f5d500d01cd0a30a34a3067ca6f5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Domiciliar e Conceito de Casa', '## Busca Domiciliar e Conceito de Casa

A busca domiciliar é uma medida de busca e apreensão que pode ser deferida apenas pelo juiz competente, sob pena de nulidade. O conceito de casa inclui compartimentos habitados, aposentos ocupados de habitação coletiva e compartimentos não abertos ao público onde alguém exerce profissão ou atividade.

### Conceitos
- **Busca Domiciliar**: Medida de busca e apreensão que pode ser deferida apenas pelo juiz competente
- **Conceito de Casa**: Compartimentos habitados, aposentos ocupados de habitação coletiva e compartimentos não abertos ao público onde alguém exerce profissão ou atividade
- **Juiz Competente**: Pode deferir a busca domiciliar sob pena de nulidade
- **Nulidade da Diligência**: Ocorre se o juiz não é competente para deferir a busca domiciliar

### Referências legais
- Art. 150, §4º, do CP
- Art. 246 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo da Busca Domiciliar

### Dicas de prova
- Distinção entre busca domiciliar e busca em veículos ou embarcações
- Importância do conceito de casa para a definição da busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.363 (1)", "page_number": 363, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 150, §4º, do CP", "Art. 246 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo da Busca Domiciliar"], "confidence": 0.8, "extracted_at": "2026-05-29T04:01:16.154333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=363", "doc_key": "a5a1f5d500d01cd0a30a34a3067ca6f5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'de7fe4e37699e86de8c41a976906022244fd338fb01c42013aabfde49c877ff3'),
  ('cpiuris2025::f3b6f2ceb995a7db72c7193c04649dd8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Inviolabilidade Domiciliar e Busca', '## Inviolabilidade Domiciliar e Busca

A inviolabilidade domiciliar não se aplica quando o sujeito utiliza o veículo ou embarcação como residência, mas não está neles no momento da diligência. Nesse caso, a busca é regida pelas regras atinentes à busca pessoal.

### Conceitos
- **Inviolabilidade Domiciliar**: direito que protege o local de residência do indivíduo
- **Busca Pessoal**: busca realizada sem a necessidade de mandado ou autorização prévia
- **Busca Domiciliar**: busca realizada com mandado ou autorização prévia, respeitando a inviolabilidade domiciliar

### Referências legais
- Art. 5º, XII da CF
- ...

### Jurisprudência
- STF. Rcl 24473/DF
- ...

### Dicas de prova
- Distinção entre busca pessoal e busca domiciliar
- Condições para a aplicação da inviolabilidade domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.363 (2)", "page_number": 363, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XII da CF", "..."], "jurisprudence": ["STF. Rcl 24473/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:01:41.476637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=363", "doc_key": "f3b6f2ceb995a7db72c7193c04649dd8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f6f00046a2dbb22ea2651439575196f324ab1a2dd73a5909beda2a310001c814'),
  ('cpiuris2025::16530c174c7857d974e0706543967075', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Horário da Busca Domiciliar', '## Horário da Busca Domiciliar

A busca domiciliar depende de mandado judicial e pode ocorrer apenas entre as 5h da manhã e 9h da noite, sem consentimento do morador.

### Conceitos
- **Busca Domiciliar**: execução de busca em residência
- **Mandado Judicial**: ordem judicial que autoriza a busca domiciliar
- **Horário da Busca**: pode ocorrer apenas entre as 5h da manhã e 9h da noite
- **Consentimento do Morador**: não é necessário para a busca domiciliar, exceto se o morador consentir que se realize à noite

### Referências legais
- Art. 22, §2º, inciso III da Lei n.º 13.869/19
- Art. 245, caput do CPP

### Dicas de prova
- Diferenciar entre busca domiciliar e busca em residência
- Entender a importância do mandado judicial na busca domiciliar
- Conhecer o horário permitido para a busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.364 (1)", "page_number": 364, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 22, §2º, inciso III da Lei n.º 13.869/19", "Art. 245, caput do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:03:09.506134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=364", "doc_key": "16530c174c7857d974e0706543967075"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '24761d735f98a1549808eb3dfdb982a3b49d8782a5dbb1c8ff3ba80a5bca2f25'),
  ('cpiuris2025::737eb58115b31363a482867801801cf8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Apreensão de Pessoas e Coisas', '## Busca e Apreensão de Pessoas e Coisas

A busca e apreensão de pessoas e coisas só são permitidas se não houver pessoas presentes, ou se elas tentarem impedir a busca. Em caso de busca em casa habitada, deve-se respeitar os moradores, mas pode ser empregada força se necessário.

### Conceitos
- **Busca e Apreensão**: Ação realizada para encontrar e capturar pessoas ou coisas
- **Respeito aos Moradores**: É obrigatório respeitar os moradores em busca em casa habitada
- **Força Justificável**: Pode ser empregada força se necessário para impedir a busca

### Referências legais
- Art. 248 do CPP
- Art. 245, §6º do CPP

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Distinção entre busca em casa habitada e não habitada
- Requisitos para a busca em casa sem moradores presentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.364 (2)", "page_number": 364, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 248 do CPP", "Art. 245, §6º do CPP"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:03:15.121577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=364", "doc_key": "737eb58115b31363a482867801801cf8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e5cb1427c18a54da4a7086105b452ec0f8f405d73adda95f4f23e57974b4e2a2'),
  ('cpiuris2025::9103d9dffceff4572bf112976e91b01d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Apreensão de Pessoas e Coisas', '## Busca e Apreensão de Pessoas e Coisas

A busca e apreensão de pessoas e coisas devem ser feitas de acordo com as formalidades estabelecidas, incluindo a intimação de vizinhos em casos de busca em compartimentos habitados. A autoridade pode penetrar em território alheia para apreensão, desde que apresente-se à competente autoridade local e tenha fundadas razões para duvidar da legitimidade das pessoas que entram pelos distritos.

### Conceitos
- **Intimação de vizinhos**: Obrigação de intimar vizinhos em casos de busca em compartimentos habitados
- **Busca em território alheia**: Autoridade pode penetrar em território alheia para apreensão, desde que apresente-se à competente autoridade local
- **Legitimidade das pessoas**: A autoridade deve ter fundadas razões para duvidar da legitimidade das pessoas que entram pelos distritos
- **Mandados de busca**: Obrigação de apresentar mandados de busca válidos e legítimos
- **Diligência infrutífera**: Situação em que a diligência não é bem-sucedida, e os motivos da diligência devem ser comunicados à pessoa que sofreu a busca

### Referências legais
- Art. 246 do CPP
- Art. 250 do CPP
- Art. 247 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre as formalidades de busca e apreensão
- Entenda a noção de busca em território alheia e suas limitações
- Conheça os requisitos para legitimidade das pessoas que entram pelos distritos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.365 (1)", "page_number": 365, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 246 do CPP", "Art. 250 do CPP", "Art. 247 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:04:44.665380+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=365", "doc_key": "9103d9dffceff4572bf112976e91b01d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b0bf4fb1c13601fcfb7ac65d6e226c9e8ed68f186fea3a44d171e171e3a2778b'),
  ('cpiuris2025::b9d2e218fdbe3860dc1035b3f90577af', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso às mensagens telemáticas em aparelhos celulares', '## Acesso às mensagens telemáticas em aparelhos celulares

O acesso às mensagens telemáticas em aparelhos celulares pode ser feito com autorização judicial ou, em casos de busca e apreensão domiciliar prévia, mesmo sem autorização expressa.

### Conceitos
- **Autorização Judicial**: Poder do juiz competente para permitir o acesso às mensagens telemáticas
- **Busca e Apreensão Domiciliar Prévia**: Ordem de busca e apreensão que já é suficiente para permitir o acesso aos dados dos aparelhos celulares

### Referências legais
- Art. 6º, II e III do CPP

### Jurisprudência
- {''RE'': ''593'', ''Tema'': ''STJ. 5ª Turma. RHC 67.379-RN''}
- {''RE'': ''77.232/SC'', ''Tema'': ''STJ. 5ª Turma. RHC''}

### Dicas de prova
- Distinção entre autorização judicial e busca e apreensão domiciliar prévia
- Importância da ordem de busca e apreensão para permitir o acesso aos dados dos aparelhos celulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.365 (2)", "page_number": 365, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 6º, II e III do CPP"], "jurisprudence": ["{''RE'': ''593'', ''Tema'': ''STJ. 5ª Turma. RHC 67.379-RN''}", "{''RE'': ''77.232/SC'', ''Tema'': ''STJ. 5ª Turma. RHC''}"], "confidence": 0.8, "extracted_at": "2026-05-29T04:05:04.261398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=365", "doc_key": "b9d2e218fdbe3860dc1035b3f90577af"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '97aba4c35a221432959c6fcc512954f6dc19be7738bfed43f35e5a7f8c688057'),
  ('cpiuris2025::0e68e92538ed626d16c1504c18e4be95', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso às mensagens do celular de uma vítima morta', '## Acesso às mensagens do celular de uma vítima morta

A autoridade policial pode acessar as mensagens do celular de uma vítima morta entregue à polícia pela pessoa que ficou viúva, independentemente de ordem judicial.

### Conceitos
- **Acesso às provas**: O direito da autoridade policial a acessar provas relacionadas a um caso
- **Mensagens do celular**: As mensagens contidas no aparelho móvel de uma vítima morta
- **Ordem judicial**: Uma ordem emitida por um juiz para que alguém faça algo ou para que algo seja feito
- **Polícia**: A autoridade responsável pela manutenção da ordem pública e pela investigação de crimes
- **Viúva**: A pessoa que fica sem marido após a morte dele

### Referências legais
- Art. 366 do Código de Processo Penal

### Jurisprudência
