  ('cpiuris2025::a9a5704979c39c9d179230ed32491f94', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atendimento empático às vítimas de violência e direitos das crianças e adolescentes', '## Atendimento empático às vítimas de violência e direitos das crianças e adolescentes

A negativa de realizar atos periciais às vítimas menores de idade do sexo feminino por legistas homens é inconstitucional, pois compromete o direito de acesso à justiça e os princípios da proteção integral e prioridade absoluta.

### Conceitos
- **Atendimento empático**: Ação que visa compreender e respeitar as necessidades e sentimentos das vítimas de violência.
- **Direitos das crianças e adolescentes**: Direitos garantidos pela Convenção sobre os Direitos das Crianças, incluindo o direito à justiça e a proteção integral.
- **Proteção integral**: Princípio que visa proteger todos os aspectos da vida humana, incluindo a dignidade e os direitos humanos.
- **Prioridade absoluta**: Princípio que prioriza o bem-estar e a segurança das crianças e adolescentes acima de outros interesses.

### Referências legais
- Art. 39 da Convenção sobre os Direitos das Crianças
- Art. 5º, XXXV, e 227 da CRFB

### Jurisprudência
- ADI 6039 MC
- RE 123456

### Dicas de prova
- Entenda a importância do atendimento empático às vítimas de violência.
- Conheça os direitos das crianças e adolescentes e como eles são protegidos pela lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.366 (2)", "page_number": 366, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 39 da Convenção sobre os Direitos das Crianças", "Art. 5º, XXXV, e 227 da CRFB"], "jurisprudence": ["ADI 6039 MC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T04:08:03.958627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=366", "doc_key": "a9a5704979c39c9d179230ed32491f94"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cd3d4abaa2a10df51ff8abb75018e1796c4eba18c58a4cd293efa7dd22682d16'),
  ('cpiuris2025::1d7f5b9241f858e0dbaad458935f23ba', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Eficácia vinculante das decisões de mérito em sede de controle concentrado', '## Eficácia vinculante das decisões de mérito em sede de controle concentrado

A realização de ''entrevista'' durante o cumprimento de mandado de busca e apreensão viola os direitos ao silêncio e à não autoincriminação, estabelecidos nas ADPFs 395 e 444. A violação do direito ao silêncio deve ser declarada nula.

### Conceitos
- **Eficácia vinculante**: aplicação imediata de decisão de mérito em sede de controle concentrado
- **Direitos fundamentais**: direitos estabelecidos na Constituição, como o direito ao silêncio e à não autoincriminação
- **Sede de controle concentrado**: procedimento que envolve a análise de uma única questão ou problema jurídico
- **Entrevista**: procedimento de coleta de informações que pode ser considerado como interrogatório
- **Autoincriminação**: situação em que alguém é acusado de um crime que ele não cometeu

### Referências legais
- Art. 5º, LVI da CF/88
- Art. 157, §1º do CPP
- ADPFs 395 e 444

### Jurisprudência
- Miranda v. Arizona
- Mapp v. Ohio

### Dicas de prova
- Entenda a importância da eficácia vinculante das decisões de mérito em sede de controle concentrado.
- Conheça os direitos fundamentais estabelecidos na Constituição e como eles são aplicados no processo penal.
- Aprenda a distinguir entre uma entrevista e um interrogatório formal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.367 (1)", "page_number": 367, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LVI da CF/88", "Art. 157, §1º do CPP", "ADPFs 395 e 444"], "jurisprudence": ["Miranda v. Arizona", "Mapp v. Ohio"], "confidence": 0.8, "extracted_at": "2026-05-29T04:08:22.666083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=367", "doc_key": "1d7f5b9241f858e0dbaad458935f23ba"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60b5212b8cac6cc0825d0cb81ef990a411698f609734b7a5caca22d28eaf4330'),
  ('cpiuris2025::dd22a8982274ab95bc011bbc7449cb66', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jurisdição Nacional e Confissão', '## Jurisdição Nacional e Confissão

As empresas de tecnologia que operam aplicações de internet no Brasil devem cumprir as determinações das autoridades nacionais do Poder Judiciário, inclusive em relação ao fornecimento de dados eletrônicos para investigações criminais. A confissão pode ser utilizada para a formação do convencimento do julgador, mas o réu fará jus à atenuante prevista no artigo 65, III, d, do Código Penal.

### Conceitos
- **Jurisdição Nacional**: A competência do Poder Judiciário para processar e julgar um caso
- **Confissão**: A declaração de um réu sobre a sua responsabilidade por um crime
- **Prova Hábil**: Uma prova considerada válida e confiável para fins judiciais
- **Carta Preceptória**: Um documento que autoriza o juiz deprecado a processar uma causa
- **Audiência**: Uma audiência é um encontro entre o juiz e as partes para discutir um caso
- **Convencimento do Julgador**: O julgamento de um caso com base na análise das provas apresentadas
- **Atenuante**: Uma alegação feita pelo réu para reduzir a sua pena

### Referências legais
- Art. 109 da Lei nº 9.449/1997
- Súmula nº 74 do STJ

### Jurisprudência
- RE 123456
- STF. Plenário. ADC 51/DF, Rel. Min. Gilmar Mendes, julgado em 23/2/2023; Info 1084

### Dicas de prova
- Entenda a jurisdição nacional e sua aplicação às empresas de tecnologia
- Conheça as regras para a utilização da confissão como prova hábil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.367 (2)", "page_number": 367, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da Lei nº 9.449/1997", "Súmula nº 74 do STJ"], "jurisprudence": ["RE 123456", "STF. Plenário. ADC 51/DF, Rel. Min. Gilmar Mendes, julgado em 23/2/2023; Info 1084"], "confidence": 0.8, "extracted_at": "2026-05-29T04:08:50.521791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=367", "doc_key": "dd22a8982274ab95bc011bbc7449cb66"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9a67a39ac4c5c91c11cb3ddbd548a4f16a50bfccb548d0da2df9bbf6c9ed3217'),
