  ('cpiuris2025::714879546ea36f488416b670fdd8877f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Constrangimento ilegal evidenciado e agravo regimental provido', '## Constrangimento ilegal evidenciado e agravo regimental provido

O Supremo Tribunal Federal (STF) anulou a decisão que decretou prisão preventiva em um caso envolvendo o uso do aplicativo WhatsApp para coletar dados, considerando que o espelhamento das mensagens ocorre em um sítio eletrônico disponibilizado pela própria empresa.

### Conceitos
- **Constrangimento ilegal**: Ato ilegal que viola os direitos do réu
- **Agravo regimental**: Recurso apresentado para revisar uma decisão anterior
- **Prisão preventiva**: Medida de segurança que impede o réu de se libertar até a sentença final
- **Espelhamento de mensagens**: Ação de capturar e analisar as mensagens de um aplicativo eletrônico
- **Sítio eletrônico**: Local onde os dados são armazenados e acessados
- **Autorização judicial**: Decisão do juiz que permite a realização de uma ação específica
- **Interceptação telefônica**: Ação de capturar e analisar as mensagens de um aplicativo eletrônico sem autorização prévia

