  ('cpiuris2025::6255afd84b7cad7600664cd1ae15c19a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência da Justiça Federal em casos de desvios de verbas do SUS', '## Competência da Justiça Federal em casos de desvios de verbas do SUS

A competência da Justiça Federal é reconhecida para processar e julgar os desvios de verbas do Sistema Único de Saúde - SUS, devido ao dever de fiscalização e supervisão do governo federal. No entanto, os atos processuais devem ser avaliados pelo Juízo competente.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é reconhecida para processar e julgar os desvios de verbas do SUS.
- **Teoria do Juízo Aparente**: A Teoria do Juízo Aparente é aplicada quando há dúvida sobre a competência do Juízo.
- **Inviolabilidade do Domicílio**: O domicílio é considerado asilo inviolável, e ninguém pode penetrar sem consentimento do morador.
- **Busca e Apreensão**: A busca e a prensão devem ter objetivo certo e pessoa determinada.
- **Competência Absoluta**: A competência absoluta é reconhecida quando não há dúvida sobre a competência do Juízo.
- **Remessa de Processo**: O processo deve ser remetido à Justiça Federal se houver dúvida sobre a competência.
- **Avaliação da Validade da Prova**: A avaliação da validade da prova é importante para determinar a competência do Juízo.
- **Fiscalização e Supervisão**: O governo federal tem o dever de fiscalizar e supervisionar as entidades públicas.

### Referências legais
- Art. 240 do Código de Processo Penal
- Art. 242 do Código de Processo Penal
- Art. 244 do Código de Processo Penal
- Art. 245 do Código de Processo Penal
- Art. 248 do Código de Processo Penal
- Art. 249 do Código de Processo Penal
- Art. 5º, XI da Constituição Federal

### Jurisprudência
- Súmula nº 630, STJ

### Dicas de prova
- Pergunte sobre a competência da Justiça Federal em casos de desvios de verbas do SUS.
- Entenda a Teoria do Juízo Aparente e sua aplicação.
- Conheça a Inviolabilidade do Domicílio e como ela se aplica ao caso.
- Avalie a Busca e Apreensão em relação à competência do Juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.368 (1)", "page_number": 368, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 240 do Código de Processo Penal", "Art. 242 do Código de Processo Penal", "Art. 244 do Código de Processo Penal", "Art. 245 do Código de Processo Penal", "Art. 248 do Código de Processo Penal", "Art. 249 do Código de Processo Penal", "Art. 5º, XI da Constituição Federal"], "jurisprudence": ["Súmula nº 630, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T04:12:53.934403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=368", "doc_key": "6255afd84b7cad7600664cd1ae15c19a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '21188b64bbeb5c26c198661307de8c6a1a447668cb84ea1e8e3427cd0f130bc4'),
  ('cpiuris2025::5256a9f576a3113a0e63ace868493227', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Limitação do direito de privacidade', '## Limitação do direito de privacidade

A ausência de indícios razoáveis da autoria ou participação em infração penal não justifica a limitação do direito de privacidade. Além disso, a fixação de prazo sem base legal é ilegal.

### Conceitos
- **Limitação do direito de privacidade**: Direito que protege a privacidade das pessoas
- **Indícios razoáveis da autoria ou participação em infração penal**: Prova suficiente para comprovar a autoria ou participação em crime
- **Fixação de prazo sem base legal**: Prazo estabelecido sem fundamento na lei

### Referências legais
- Art. 5º, § 11 da CF/88
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre limitação do direito de privacidade e sua justificativa
