  ('cpiuris2025::dcab8da8e9f9b3c27b7950167c04fc6d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Espelhamento via Código QR e direitos do investigado', '## Espelhamento via Código QR e direitos do investigado

O espelhamento via Código QR permite ao investigador de polícia acesso a todas as comunicações realizadas antes da autorização judicial, operando efeitos retroativos. Isso implica que a admissão desse meio de obtenção de prova pode implicar indevida presunção absoluta da legitimidade dos atos do investigador.

### Conceitos
- **Investigador de polícia**: Pessoa autorizada a realizar investigações
- **Espelhamento via Código QR**: Méodo de obtenção de provas que permite acesso a todas as comunicações realizadas antes da autorização judicial
- **Direitos do investigado**: Direitos protegidos pelo Estado para garantir a privacidade e a liberdade individual
- **Autorização judicial**: Decisão do juiz que autoriza a realização de uma medida de investigação
- **Interceptação telefônica**: Méodo de obtenção de provas que envolve a escuta de conversas realizadas apenas depois da autorização judicial

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do espelhamento via Código QR e direitos do investigado

### Dicas de prova
- Entenda a diferença entre interceptação telefônica e espelhamento via Código QR
- Conheça os direitos do investigado em relação à privacidade e liberdade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.369 (2)", "page_number": 369, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do espelhamento via Código QR e direitos do investigado"], "confidence": 0.8, "extracted_at": "2026-05-29T04:14:24.480829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=369", "doc_key": "dcab8da8e9f9b3c27b7950167c04fc6d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8b864515b40f80db5adadcf7a311456f4f99ce4b4c2a4acbb28136ff5c19c141'),
  ('cpiuris2025::ad54fc92534357802e5b7956e92d410f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus Substitutivo', '## Habeas Corpus Substitutivo

O habeas corpus substitutivo do recurso não cabe para apreciar a absolvição do paciente, pois isso requer revolvimento do conjunto fático-probatório, o que é inviável na via eleita.

### Conceitos
- **Habeas Corpus**: Ação judicial para garantir liberdade de alguém preso
- **Substitutivo**: Recurso que substitui outro recurso previsto em lei
- **Absolvição**: Condenação sem punição
- **Inversão do ônus da prova**: Mudança da responsabilidade de provar algo de uma parte para outra

### Referências legais
- Art. 156 do Código de Processo Penal

### Jurisprudência
- RE 123456
- RE 433.679/RS

### Dicas de prova
- Distinção entre habeas corpus substitutivo e recurso ordinário
- Inviabilidade da absolvição em sede de writ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 156 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "RE 433.679/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T04:15:02.127603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=370", "doc_key": "ad54fc92534357802e5b7956e92d410f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b12ef10e114918690a461285efc50ff9c86f9cf7c51c482a95c3d174499a9ec1'),
  ('cpiuris2025::edf8dfae594298544d9117829483ed29', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova de dados armazenados em aparelhos celulares', '## Prova de dados armazenados em aparelhos celulares

A busca e análise de dados armazenados em aparelhos celulares são restritas a casos em que haja autorização judicial prévia, exceto quando o aparelho é preendido em cumprimento de ordem judicial.

### Conceitos
- **Autorização Judicial**: Prévia autorização judicial necessária para busca e análise de dados armazenados em aparelhos celulares
- **Busca e Apreensão**: Ação realizada pela polícia para buscar e apreender objetos ou evidências relacionadas a um crime
- **Prova Obtida Diretamente**: Prova obtida sem a necessidade de autorização judicial, como em casos de busca e apreensão

### Referências legais
- Art. 3° da Lei n. 9.472/97
- Art. 7° da Lei n. 12.965/14

### Jurisprudência
- HC 127.900/AM
- RHC 77.232/SC

### Dicas de prova
- Distinção entre busca e análise de dados armazenados em aparelhos celulares
- Importância da autorização judicial prévia para tal ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.371 (1)", "page_number": 371, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3° da Lei n. 9.472/97", "Art. 7° da Lei n. 12.965/14"], "jurisprudence": ["HC 127.900/AM", "RHC 77.232/SC"], "confidence": 0.8, "extracted_at": "2026-05-29T04:16:48.589845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=371", "doc_key": "edf8dfae594298544d9117829483ed29"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7c7a778f7debcdbfcb800d771e79e9d2e6758fdd9503ec69f65ddf7e64c46fd1'),
  ('cpiuris2025::4a202e0197ab966658e26941d868d046', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Inaplicabilidade do artigo 5º, XII, da Constituição Federal e da Lei n. 9.296/96 em relação à análise e utilização de dados armazenados em aparelhos celulares', '## Inaplicabilidade do artigo 5º, XII, da Constituição Federal e da Lei n. 9.296/96 em relação à análise e utilização de dados armazenados em aparelhos celulares

O recurso analisa a inaplicabilidade do artigo 5º, XII, da Constituição Federal e da Lei n. 9.296/96 em relação à análise e utilização de dados armazenados em aparelhos celulares, considerando que os dados em si mesmos não são invioláveis, mas sim as informações relacionadas à vida privada e intimidade do indivíduo.

### Conceitos
- **Inaplicabilidade**: A falta de aplicação de uma norma legal ou constitucional em um determinado caso ou situação.
- **Art. 5º, XII, da Constituição Federal**: Proteção das comunicações em fluxo
- **Lei n. 9.296/96**: Lei que regula a interceptação telefônica ou telemática
- **Dados armazenados em aparelhos celulares**: Informações armazenadas nos aparelhos celulares, como mensagens e conversas.

### Referências legais
- Art. 5º, XII, da Constituição Federal
- Lei n. 9.296/96

### Jurisprudência
- RE 123456
- Tema repetitivo: proteção das comunicações em fluxo e dados armazenados em aparelhos celulares

### Dicas de prova
- Entenda a distinção entre a proteção da comunicação em fluxo e a proteção dos dados em si mesmos.
- Conheça as normas legais que regem a interceptação telefônica ou telemática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XII, da Constituição Federal", "Lei n. 9.296/96"], "jurisprudence": ["RE 123456", "Tema repetitivo: proteção das comunicações em fluxo e dados armazenados em aparelhos celulares"], "confidence": 0.8, "extracted_at": "2026-05-29T04:17:15.911132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=370", "doc_key": "4a202e0197ab966658e26941d868d046"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6dd59e37bfb61ba737d6d5a71b727027b539e2b459504743ad390329e13fb807'),
  ('cpiuris2025::a29f0d0d3ed72ffff2c42ab1e86b0aa2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Novo entendimento do Supremo Tribunal Federal sobre o interrogatório no processo penal', '## Novo entendimento do Supremo Tribunal Federal sobre o interrogatório no processo penal

O Supremo Tribunal Federal estabeleceu um novo entendimento sobre o interrogatório, determinando que ele deve ser sempre o último ato da instrução, mesmo em procedimentos regidos por lei especial. Isso significa que a solução de antinomias com base no princípio da especialidade não é mais aplicável.

### Conceitos
- **Interrogatório**: O último ato da instrução do processo penal
- **Princípio da especialidade**: Princípio que determina a aplicação de uma lei específica para cada caso
- **Contraditório e ampla defesa**: Direitos do acusado que garantem sua liberdade de escolha
- **Sistema acusatório**: Sistema que coloca a responsabilidade sobre o acusado

### Referências legais
- Art. 400 do CPP (com redação da Lei nº 11.719/08)

### Jurisprudência
- RE 118.533/MS

### Dicas de prova
- Entenda a mudança no entendimento sobre o interrogatório e sua aplicação nos processos penais
- Conheça as implicações do princípio da especialidade na jurisprudência brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.371 (2)", "page_number": 371, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 400 do CPP (com redação da Lei nº 11.719/08)"], "jurisprudence": ["RE 118.533/MS"], "confidence": 0.8, "extracted_at": "2026-05-29T04:17:32.587044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=371", "doc_key": "a29f0d0d3ed72ffff2c42ab1e86b0aa2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '081f4732bf44a3ec5e99bec769c7257e0406e89ee436442f18c1978fef5161cb'),
  ('cpiuris2025::9cd8bb02c28933b6466f7947e956664f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas em Processo', '## Provas em Processo

O processo deve ter elementos probatórios mínimos que corroborem a acusação, sendo essencial a existência de provas conclusivas para comprovar a materialidade e autoria do delito.

### Conceitos
- **Provas Conclusivas**: provas que comprovam a materialidade e autoria do delito
- **Elementos Probatórios Mínimos**: elementos necessários para sustentar a acusação
- **Materialidade**: qualidade de ser objeto de punição legal
- **Autoria**: qualidade de ser o autor do delito

### Referências legais
- Art. 214 do Código de Processo Penal

### Dicas de prova
- Distinção entre provas conclusivas e probatórias mínimas
- Importância da existência de elementos probatórios mínimos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.372 (3)", "page_number": 372, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 214 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:19:03.365386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=372", "doc_key": "9cd8bb02c28933b6466f7947e956664f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd5760de1790309142c04b99ad596604afb3de6adbe1c18436e8e48e75973c859'),
  ('cpiuris2025::63fba4d1b2ee7a74d64d06aed8b31496', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Substituição da pena privativa de liberdade por regras de direitos', '## Substituição da pena privativa de liberdade por regras de direitos

A Corte entende que é possível a substituição da pena privativa de liberdade por regras de direitos em condenações por tráfico de drogas, desde que as particularidades do caso concreto sejam consideradas.

### Conceitos
- **Substituição da pena**: substituir a pena privativa de liberdade por regras de direitos
- **Tráfico de drogas**: crime de tráfico de substâncias ilegais
- **Regime inicial semiaberto**: regime de prisão com liberdade condicional
- **Habeas corpus**: mandado judicial que exige a liberdade do preso

### Referências legais
- Art. 33, §2º, alínea b, do Código Penal

### Jurisprudência
- HC nº 118.533/MS
- HC 403.550/SP

### Dicas de prova
- Entenda o conceito de substituição da pena e suas implicações no direito processual penal.
- Conheça as particularidades do caso concreto que podem influenciar a decisão sobre a substituição da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.372 (1)", "page_number": 372, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 33, §2º, alínea b, do Código Penal"], "jurisprudence": ["HC nº 118.533/MS", "HC 403.550/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T04:19:03.850174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=372", "doc_key": "63fba4d1b2ee7a74d64d06aed8b31496"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b9dd5cebc113d93f458adfe018cb8d91b57dbebba6b0ebb4703e60835f9b7372'),
  ('cpiuris2025::c8727297891e214419e3e9fb631d0b24', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Apreensão de objetos e sigilo telefônico', '## Apreensão de objetos e sigilo telefônico

A apreensão de objetos pode ocorrer sem prévia autorização judicial, mas o sigilo telefônico deve ser protegido por ordem judicial. A quebra do sigilo é permitida apenas em casos de indício razoável da autoria ou participação em infração penal.

### Conceitos
- **Apreensão**: ato processual pelo qual se tomam medidas para prevenir o crime
- **Sigilo telefônico**: direito à privacidade das comunicações telefônicas
- **Inviolabilidade do sigilo**: direito constitucional que protege o sigilo das comunicações telefônicas e outras formas de comunicação

### Referências legais
- Art. 5º, XI da Constituição Federal
- Art. 41 do CPP
- Art. 5º, LV da CF/1988

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre apreensão e sigilo telefônico
- Entender a importância da autorização judicial para quebra do sigilo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.372 (2)", "page_number": 372, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XI da Constituição Federal", "Art. 41 do CPP", "Art. 5º, LV da CF/1988"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:19:25.675533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=372", "doc_key": "c8727297891e214419e3e9fb631d0b24"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '27c1d8a1d7135f965a039d7a1432ccf722b0c8bbea1e2ae090e4633d0b7fbaba'),
  ('cpiuris2025::8e718b14cccbbf2bc44f8f07db396079', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento da justa causa para ação penal', '## Reconhecimento da justa causa para ação penal

A justa causa para ação penal deve ser demonstrada com elementos probatórios, mas não é possível reexaminar os mesmos em sede de recurso especial. O princípio do in dubio pro societate deve ser privilegiado na fase de admissibilidade da acusação.

### Conceitos
- **Princípio do in dubio pro societate**: Preceito processual que favorece a sociedade, concedendo benefícios ao Estado
- **Justa causa**: Elemento necessário para a ação penal
- **Fase de admissibilidade da acusação**: Período em que se avalia a justa causa para a ação penal

### Referências legais
- Art. 382 do Código de Processo Civil
- Súmula 7/STJ

### Jurisprudência
- REsp 1578209/SC
- AgRg no REsp 67.379/RN

### Dicas de prova
- Entenda o conceito de justa causa e sua importância na ação penal
- Conheça o princípio do in dubio pro societate e sua aplicação na fase de admissibilidade da acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.373 (1)", "page_number": 373, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do Código de Processo Civil", "Súmula 7/STJ"], "jurisprudence": ["REsp 1578209/SC", "AgRg no REsp 67.379/RN"], "confidence": 0.8, "extracted_at": "2026-05-29T04:20:01.709744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=373", "doc_key": "8e718b14cccbbf2bc44f8f07db396079"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '19cc7c843293d7f1f1cc2a8371580ce935f8d0df3f436c3094b6f3f75fcb86ab'),
  ('cpiuris2025::4ef0b4628c25ca66ecf7d0c1ccd18c08', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acessibilidade a documentos de colaboração premiada no habeas corpus', '## Acessibilidade a documentos de colaboração premiada no habeas corpus

O habeas corpus não foi adequadamente instruído para comprovar o acesso a documentos da colaboração premiada, impedindo o provimento do recurso. A cadeia de custódia visa garantir que os vestígios arrecadados pela polícia correspondam aos deixados no mundo material.

### Conceitos
- **Habeas corpus**: Mecanismo processual destinado a garantir a liberdade de uma pessoa presa ou detida
- **Acesso a documentos de colaboração premiada**: Direito do recorrente à visibilidade dos documentos obtidos por meio de operações de colaboração com testemunhas ou informantes
- **Cadeia de custódia**: Procedimento que visa garantir a integridade das provas arrecadadas pela polícia

### Referências legais
- Súmula 7/STJ
- Súmula 284/STF
- Súmula 231/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre a acessibilidade aos documentos de colaboração premiada e o direito ao provimento do recurso
- Importância da cadeia de custódia para garantir a integridade das provas arrecadadas pela polícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.373 (2)", "page_number": 373, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula 7/STJ", "Súmula 284/STF", "Súmula 231/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T04:22:35.585388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=373", "doc_key": "4ef0b4628c25ca66ecf7d0c1ccd18c08"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1e73077893ffd2911323f828a00d4b9fcbe75043c3feeb2e2878cf2b24ff5679'),
  ('cpiuris2025::c89252537fffdba8a727846b6a023064', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Violação de Domicílio e Posse Ilegal de Arma de Fogo', '## Violação de Domicílio e Posse Ilegal de Arma de Fogo

A Corte decidiu que, em casos de crimes permanentes, como o tráfico de entorpecentes, é prescindível o mandado de busca e apreensão para que os policiais adentrem o domicílio de quem está em situação de flagrante delito.

### Conceitos
- **Violação de Domicílio**: Agressividade do Estado contra a privacidade individual
- **Posse Ilegal de Arma de Fogo**: Possessão ilegal de arma de fogo sem autorização legal
- **Crimes Permanentes**: Tipos de crimes que não dependem da presença do agresso para sua configuração
- **Mandado de Busca e Apreensão**: Medida processual que autoriza a busca e apreensão de pessoas ou coisas
- **Prescindibilidade**: Conceito jurídico que significa que uma medida processual não é necessária para a configuração do crime

### Referências legais
- Art. 557, § 4º, do Código de Processo Civil
- Súmula 635 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- AgRg no RHC n. 143.169/RJ
- AgRg no RHC n. 144.098/RS

### Dicas de prova
- Entenda a prescindibilidade em casos de crimes permanentes
- Conheça as hipóteses em que o mandado de busca e apreensão é prescindível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.374 (2)", "page_number": 374, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 557, § 4º, do Código de Processo Civil", "Súmula 635 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "AgRg no RHC n. 143.169/RJ", "AgRg no RHC n. 144.098/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T04:23:04.278776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=374", "doc_key": "c89252537fffdba8a727846b6a023064"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '660c9c4491963281cd9b86f1535114f1ff6fa71343921af5709e5679c72fb116'),
  ('cpiuris2025::8c41f3ae2b006acf152d4f699f83d95b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cadeia de Custódia e Preservação de Provas Digitais', '## Cadeia de Custódia e Preservação de Provas Digitais

A necessidade de preservar a cadeia de custódia não surgiu com o regramento dos arts. 158-A a 158-F do CPP, mas é necessária para garantir a integridade das provas digitais.

### Conceitos
- **Cadeia de Custódia**: Conceito que se refere à preservação da integridade de uma prova desde o momento em que ela é coletada até o momento em que é apresentada ao juiz.
- **Preservação de Provas Digitais**: Importância de preservar a integridade das provas digitais, especialmente em casos de investigações criminais.
- **Prova Digital**: Prova obtida através da análise de dados digitais, como computadores, dispositivos de armazenamento de informações digitais, etc.
- **Integridade das Provas**: Condição necessária para que as provas sejam consideradas confiáveis e acreditáveis.
- **Custódia Policial**: Responsabilidade da polícia em preservar a integridade das provas coletadas durante o inquérito.
- **Prova Extraída**: Prova obtida após a coleta inicial, que pode ser considerada confiável apenas se a cadeia de custódia for preservada.
- **Análise de Dados Digitais**: Técnica utilizada para analisar e interpretar os dados digitais coletados durante o inquérito.
- **Hash**: Assinatura única gerada por uma técnica de algoritmo hash, que pode ser usada para verificar a integridade dos dados digitais.

### Referências legais
- Art. 158-A a 158-F do CPP
- Súmula 478/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Cadeia de Custódia e Preservação de Provas Digitais

### Dicas de prova
- Entenda a importância da cadeia de custódia para preservar a integridade das provas digitais.
- Conheça as técnicas utilizadas para analisar e interpretar os dados digitais, como a análise de hashes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.374 (1)", "page_number": 374, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 158-A a 158-F do CPP", "Súmula 478/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cadeia de Custódia e Preservação de Provas Digitais"], "confidence": 0.8, "extracted_at": "2026-05-29T04:24:17.874487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=374", "doc_key": "8c41f3ae2b006acf152d4f699f83d95b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd49198d8287d7e0c46bdb53521ac2f6eec1b9eb986fd86df6e6b5ba43353c0ab'),
  ('cpiuris2025::7136a7fbff2f7ec82945b86a50c4e39c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contexto fático que evidencia o crime permanente e a situação de flagrância apta a mitigar a garantia constitucional da inviolabilidade de domicílio', '## Contexto fático que evidencia o crime permanente e a situação de flagrância apta a mitigar a garantia constitucional da inviolabilidade de domicílio

O contexto fático deve ser suficiente para evidenciar a ocorrência de crime permanente e a existência de situação de flagrância que permita a entrada dos policiais em um endereço diverso do contido na ordem judicial.

### Conceitos
- **Crime Permanente**: Atividade criminosa que não se limita ao momento da sua prática
- **Situação de Flagrância**: Condição que permite a entrada dos policiais em um endereço diverso do contido na ordem judicial

### Referências legais
- Art. 159, § 4º, CP

### Dicas de prova
- Distinção entre o contexto fático e a prova técnica
- Importância da palavra da vítima em crimes de violência doméstica
- Ausência de justificação para não realizar prova técnica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.375 (1)", "page_number": 375, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 159, § 4º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:24:42.965784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=375", "doc_key": "7136a7fbff2f7ec82945b86a50c4e39c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a1ba470136d7b5ee1084382550edc70166f2018ad6c5f203739ea5264deeaf84'),
  ('cpiuris2025::5f82395ece831f0c70aa5d5be37047c6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Apreensão em Empresas', '## Busca e Apreensão em Empresas

A busca e apreensão em empresas são regulamentadas pela autorização expressa de uma pessoa que atua como representante da empresa. A teoria da aparência permite a busca e apreensão na sede da empresa, mesmo que o representante não seja sócio formal.

### Conceitos
- **Autorização Expressa**: Declaração feita por uma pessoa que atua como representante de uma empresa, autorizando a busca e apreensão.
- **Teoria da Aparência**: Princípio que permite a busca e apreensão na sede de empresa mesmo que o representante não seja sócio formal.
- **Faculdades Defensivas**: Direito do acusado de consultar os elementos obtidos na busca e apreensão para exercer suas defesas.
- **Elementos Utilizados pela Acusação**: Materiais escolhidos pelo MP que serão utilizados pela acusação, enquanto o material restante permanece à livre consulta do acusado.

### Referências legais
- Art. 312 do Código de Processo Penal
- Súmula 394 da STJ

### Jurisprudência
- RE 123456
- RMS 60.531-RO

### Dicas de prova
- Distinção entre autorização expressa e teoria da aparência.
- Importância das faculdades defensivas do acusado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.375 (2)", "page_number": 375, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do Código de Processo Penal", "Súmula 394 da STJ"], "jurisprudence": ["RE 123456", "RMS 60.531-RO"], "confidence": 0.8, "extracted_at": "2026-05-29T04:25:35.546200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=375", "doc_key": "5f82395ece831f0c70aa5d5be37047c6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8f56b6fbbb38adae4fbece36f157fbfbd905389f313b20b091205f35cc9c22ab'),
  ('cpiuris2025::f3fbd1b2769052955aa7a0b277f1c553', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso à integridos dos dados obtidos no cumprimento do mandado judicial', '## Acesso à integridos dos dados obtidos no cumprimento do mandado judicial

O relatório sobre o resultado da diligência deve ser adstrito aos elementos relacionados com os fatos sob apuração e a defesa deve ter acesso à integridos dos dados obtidos no cumprimento do mandado judicial.

### Conceitos
- **Acesso à integridos dos dados**: O direito da defesa de acessar todos os dados obtidos durante o cumprimento do mandado judicial
- **Relatório sobre resultado da diligência**: O documento que resume as informações obtidas durante a diligência

### Referências legais
- Art. 236 do Código de Processo Penal
- ...

### Jurisprudência
- STJ. 6ª Turma. RHC 114.683/RJ
- STJ. 6ª Turma. RHC 141.737/PR
- STJ. 5ª Turma. AREsp 701.833/SP

### Dicas de prova
- Entenda a importância do acesso à integridos dos dados para a defesa.
- Conheça as regras sobre o relatório sobre resultado da diligência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.376 (1)", "page_number": 376, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 236 do Código de Processo Penal", "..."], "jurisprudence": ["STJ. 6ª Turma. RHC 114.683/RJ", "STJ. 6ª Turma. RHC 141.737/PR", "STJ. 5ª Turma. AREsp 701.833/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T04:26:32.555619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=376", "doc_key": "f3fbd1b2769052955aa7a0b277f1c553"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '27a92777edbddc53752e0696ec06dfc0f097348cf35aebb9de8774b059611ddf'),
  ('cpiuris2025::23914ed281d3cea737accf452d999912', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Entrada no domicílio e prisão', '## Entrada no domicílio e prisão

A entrada no domicílio para efetuar uma prisão não confere salvo-conduto para vasculhar todo o interior, evitando-se a nulidade das provas colhidas por desvio de finalidade.

### Conceitos
- **Desvio de finalidade**: Ação que vai contra a intenção original da lei ou procedimento
- **Salvo-conduto**: Concessão de imunidade a uma pessoa ou coisa para evitar a aplicação de uma lei ou medida
- **Prova probatória**: Elemento que comprova a veracidade de um fato ou situação
- **Nulidade das provas**: Anulação de provas coletadas por meio ilegal ou irregular

### Referências legais
- Art. 311 do Código de Processo Penal

### Jurisprudência
- RE 123456
- HC 663.055-MT (STJ, 6ª Turma, Rel. Min. Rogerio Schietti Cruz)

### Dicas de prova
- Entenda a diferença entre salvo-conduto e desvio de finalidade.
- Conheça as regras para a entrada no domicílio e prisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.376 (2)", "page_number": 376, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "HC 663.055-MT (STJ, 6ª Turma, Rel. Min. Rogerio Schietti Cruz)"], "confidence": 0.8, "extracted_at": "2026-05-29T04:27:02.318283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=376", "doc_key": "23914ed281d3cea737accf452d999912"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2f5ad6ed5d47f8106c30f4d4a318edada64698afb7a7bb9e5e7d8e34cf996b9a'),
  ('cpiuris2025::fd9274a20dc62e2f80c8db73188e9367', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova em Processo Penal', '## Prova em Processo Penal

Resumo sobre as regras de prova em processo penal, incluindo o ônus probante e a formação da convicção do juiz.

### Conceitos
- **Ônus probante**: A responsabilidade de provar a acusação ou o réu em um processo penal.
- **Prova cautelar**: Prova antecipada que pode ser considerada pelo juiz na formação da sua convicção, mesmo sem reproduzir-se perante o contraditório.
- **Testemunhas**: Pessoas que podem ser ouvidas em um processo penal, incluindo menores de 14 anos, doentes mentais e familiares do acusado.
- **Excludente de ilicitude**: Condição que pode ser aduz pelo réu para justificar a ausência de ilicitude no crime.
- **Dirimente de culpabilidade**: Condição que pode ser aduz pelo réu para justificar a redução da pena.
- **Álibi**: Testemunho do réu sobre sua localização no momento do crime.

### Referências legais
- Art. 400 do CPP
- Art. 571, I e II do CPP

### Jurisprudência
- REsp 2.037.491-SP
- REsps 1.933.759-PR e 1.946.472-PR
- Tema 1114

### Dicas de prova
- Entenda o conceito de ônus probante e como ele é distribuído entre a acusação e o réu.
- Conheça as regras sobre prova cautelar e sua importância na formação da convicção do juiz.
- Avalie a capacidade das pessoas de serem testemunhas no processo penal, incluindo menores de 14 anos e doentes mentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.377 (1)", "page_number": 377, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 400 do CPP", "Art. 571, I e II do CPP"], "jurisprudence": ["REsp 2.037.491-SP", "REsps 1.933.759-PR e 1.946.472-PR", "Tema 1114"], "confidence": 0.8, "extracted_at": "2026-05-29T04:28:53.128038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=377", "doc_key": "fd9274a20dc62e2f80c8db73188e9367"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ab42ca74c2324cf9c73b2593ad0698e3b343a414954b1e42ba9103b9bf9f4706'),
  ('cpiuris2025::23932f8853512e837e44868e373f7a0a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Provas e Interrogatórios no Processo Penal', '## Provas e Interrogatórios no Processo Penal

Resumo do texto: Discute-se a inidoneidade jurídica de provas obtidas ilegalmente, a rejeição de perícia irrelevante, prioridades na realização do exame de corpo de delito, o interrogatório presencial e a testemunhagem em processos penais.

### Conceitos
- **Inidoneidade jurídica**: Prova obtida ilegalmente
- **Interrogatório**: Pergunta ao réu para obter confissão
- **Testemunhagem**: Declaração de testemunhas em processo penal
- **Exame de corpo de delito**: Análise física do corpo do acusado
- **Prova comprometida**: Prova que pode ser questionada por sua origem

### Referências legais
- Art. 5º, LIV, da CF; Art. 6º, § 3º, da CF; Código de Processo Penal

### Jurisprudência
- Súmula 657/2010 do STF; Súmula 394/2011 do STJ

### Dicas de prova
- Entenda a noção de inidoneidade jurídica e sua aplicação prática.
- Conheça as regras para o interrogatório presencial e pessoal.
- Avalie a importância da prioridade na realização do exame de corpo de delito em crimes contra a pessoa ou patrimônio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.377 (2)", "page_number": 377, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 6º, § 3º, da CF; Código de Processo Penal"], "jurisprudence": ["Súmula 657/2010 do STF; Súmula 394/2011 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T04:29:16.050761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=377", "doc_key": "23932f8853512e837e44868e373f7a0a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1aef05d6e8049ada6ebad16f9dd4b0c079d8faf08bf3a9486b81e5784187bd58'),
  ('cpiuris2025::5b48b471b33b7e16d315427a261bf7a5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Testemunha em Processo Criminal', '## Audiência de Testemunha em Processo Criminal

Resumo do texto sobre audiência de testemunha em processo criminal, destacando as regras e princípios que regem essa fase do processo.

### Conceitos
- **Audiência de Testemunha**: Fase do processo em que a testemunha é ouvida para fornecer informações sobre o fato
- **Carta Preceptória**: Documento que autoriza a realização da audiência de testemunha em outro juízo
- **Intimação**: Atividade processual que notifica o réu ou sua defesa sobre um ato do processo
- **Nulidade Relativa**: Causa de nulidade que pode ser sanada com a reforma do ato processual

