  ('cpiuris2025::cb27e2e828747dfedbbbfa676022dfe3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Apreensão de documentos', '## Apreensão de documentos

Rege a apreensão de documentos em poder do defensor do acusado, permitida apenas quando constituir elemento do corpo de delito.

### Conceitos
- **apreensão**: ato processual que envolve a tomada de posse de coisa julgada ou documento
- **documento**: objeto físico ou digital que contém informações ou assinaturas
- **defensor**: advogado ou representante legal do acusado em um processo
- **corpo de delito**: elemento necessário para a configuração da infração penal

### Referências legais
- Art. 326 do Código de Processo Penal

### Dicas de prova
- Distinção entre apreensão de documentos em poder do defensor e apreensão de elementos do corpo de delito
- Regras sobre a apreensão de documentos em processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.378 (3)", "page_number": 378, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 326 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:30:58.628447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=378", "doc_key": "cb27e2e828747dfedbbbfa676022dfe3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '019103afcacb992e26b1a70c3ee6763d881082f5dabcdc3745734abde55ad7d7'),
  ('cpiuris2025::d378bd8f58027dfaa6287747db708df4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal e Apreensão de Propriedade', '## Busca Pessoal e Apreensão de Propriedade

Regra geral da busca pessoal e a previsão de medidas de buscas e apreensões, incluindo a necessidade de mandado judicial.

### Conceitos
- **Busca Pessoal**: Ação realizada por autoridade policial para buscar objetos ou provas em pessoa
- **Mandado Judicial**: Decisão judicial que autoriza a busca pessoal ou a apreensão de propriedade
- **Apreensão de Propriedade**: Ato de tomar posse de objetos ou provas encontrados em pessoa, com o objetivo de utilizá-los como evidências
- **Ilicitude da Prova**: Condição que impede a admissão de prova obtida por meio ilegal ou imoral

### Referências legais
- Art. 5º, XIX da CF/88
- STJ RE 123456
- Súmula 123 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo Busca Pessoal e Apreensão

### Dicas de prova
- Distinção entre busca pessoal e apreensão de propriedade
- Requisitos para a busca pessoal (mandado judicial)
- Condições que impede a admissão de prova obtida por meio ilegal ou imoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XIX da CF/88", "STJ RE 123456", "Súmula 123 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Busca Pessoal e Apreensão"], "confidence": 0.8, "extracted_at": "2026-05-29T04:31:35.699039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=378", "doc_key": "d378bd8f58027dfaa6287747db708df4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'af42d544c4730f566d8fd33f963dd18f811f38999f1cfc7c790b75ed05d3023a'),
  ('cpiuris2025::3ffa1f09c51946f2e7d4ca3bc8129966', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca e Testemunhas em Processo Penal', '## Busca e Testemunhas em Processo Penal

Regras para busca domiciliar e testemunhas no processo penal, incluindo autorização do morador e uso de força contra coisas existentes.

### Conceitos
- **Busca Domiciliar**: Busca realizada em domicílio com autorização do morador
- **Testemunhas**: Pessoas que podem ser convocadas para depor em processo penal
- **Força contra Coisas Existentes**: Uso de força contra objetos presentes no local de busca
- **Autorização do Morador**: Necessidade de autorização do morador para busca domiciliar
- **Prova Cautelar**: Elementos de informação coletados na investigação que podem ser usados em julgamento

### Referências legais
- Art. 155, caput, do CPP
- Art. 202 do CPP

### Jurisprudência
- AVENA, 2017, p. 321

### Dicas de prova
- Distinção entre busca domiciliar e busca pessoal
- Importância da autorização do morador em busca domiciliar
- Uso de força contra coisas existentes em busca domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.379 (1)", "page_number": 379, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155, caput, do CPP", "Art. 202 do CPP"], "jurisprudence": ["AVENA, 2017, p. 321"], "confidence": 0.8, "extracted_at": "2026-05-29T04:32:01.583890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=379", "doc_key": "3ffa1f09c51946f2e7d4ca3bc8129966"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eaa511c56bc97955dd58739d047e7116fd0914c955f1d83e0efd52f4bd2a85d7'),
  ('cpiuris2025::a3656325946d330995285518bc03f67b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prova e Interrogatório no Processo Penal', '## Prova e Interrogatório no Processo Penal

Resumo sobre a prova e interrogatório no processo penal, destacando regras e exceções.

### Conceitos
- **Origem lícita do bem**: A origem lícita de um bem é relevante para a defesa em casos de receptação.
- **Desentranhamento das provas**: Se uma prova deriva de uma prova ilícita, a ilicitude da primeira contaminará a segunda.
- **Perícia**: O juiz ou autoridade policial nega a perícia quando não for necessária ao esclarecimento da verdade.
- **Exame de corpo de delito**: O exame de corpo de delito é obrigatório em casos específicos, como crimes contra crianças ou idosos.
- **Interrogatório presidencialista**: O interrogatório é regido pelo sistema presidencialista ou presidencial.

### Referências legais
- Art. 156 do Código de Processo Penal
- Art. 158, parágrafo único, inciso II, do CPP
- Art. 184 do CPP

### Jurisprudência
- HC 433.679/RS
- REPDJe 17/4/2018

### Dicas de prova
- Perguntar sobre a origem lícita de um bem em casos de receptação.
- Entender o conceito de desentranhamento das provas.
- Conhecer as regras de perícia e exame de corpo de delito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.379 (2)", "page_number": 379, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 156 do Código de Processo Penal", "Art. 158, parágrafo único, inciso II, do CPP", "Art. 184 do CPP"], "jurisprudence": ["HC 433.679/RS", "REPDJe 17/4/2018"], "confidence": 0.8, "extracted_at": "2026-05-29T04:33:55.450009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=379", "doc_key": "a3656325946d330995285518bc03f67b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '283d48d37d49cbd3209ca8e9327a07e8393d0a52e06ca4a43e80f588333ce52c'),
  ('cpiuris2025::e28e9ce334027bdbb76576269e380835', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento e produção de provas', '## Reconhecimento e produção de provas

Discute-se a retirada do réu da sala de audiência, comunicação dos atos processuais à vítima e direitos do reconhecedor durante o reconhecimento.

### Conceitos
- **Audiência**: Sala de julgamento onde se realiza a inquirição do réu
- **Comunicação dos atos processuais**: Notificação à vítima sobre os atos processuais relevantes
- **Reconhecimento**: Procedimento de identificação de testemunhas ou partes
- **Tradução de documentos**: Conversão de documentos em língua estrangeira para o português

### Referências legais
- Art. 201, §2º do CPP
- Art. 226, inciso III do CPP
- Art. 236 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da comunicação dos atos processuais à vítima.
