  ('cpiuris2025::8b1ed54dccd59f9b16681478b8f9fbe8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Testemunhas no processo penal', '## Testemunhas no processo penal

Resumo do texto sobre as regras e direitos das testemunhas no processo penal, incluindo a capacidade civil, o direito de presença e a intimação da expedição da carta precatória.

### Conceitos
- **Capacidade civil**: Toda pessoa pode ser testemunha, independentemente da sua capacidade civil
- **Direito de presença**: O acusado tem direito a ser presente na sala de audiência, desde que solicite e for garantido
- **Intimação da expedição da carta precatória**: Não é necessária intimação do réu quanto à data da audiência designada no juízo deprecado

### Referências legais
- Art. 202 do CPP
- Súmula nº 155 do STF
- Súmula nº 273 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a intimação da expedição da carta precatória

### Dicas de prova
- Diferenciar entre a capacidade civil e o direito de presença das testemunhas
- Entender que a intimação da expedição da carta precatória não é necessária para o réu quanto à data da audiência designada no juízo deprecado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 202 do CPP", "Súmula nº 155 do STF", "Súmula nº 273 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a intimação da expedição da carta precatória"], "confidence": 0.8, "extracted_at": "2026-05-29T04:33:57.406115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=380", "doc_key": "8b1ed54dccd59f9b16681478b8f9fbe8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5292177a195845613184d1d396bf27e903eca24cfeacfd831edf7cda4c746b97'),
  ('cpiuris2025::1df188f5144e9e2a2447e5d711dde829', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Presente de documentos em juízo', '## Presente de documentos em juízo

A apresentação de documentos em juízo não requer consentimento do signatário, conforme art. 233 do CPP, mas sim a presença de proibição legal para o procedimento.

### Conceitos
- **presente de documentos**: apresentação de documentos em juízo
- **art. 233 do CPP**: disposição que permite apresentação de documentos sem consentimento do signatário
- **art. 231 do CPP**: disposição que permite a apresentação de documentos em qualquer fase do processo, salvo casos expressos em lei

### Referências legais
- Art. 233 do CPP
- Art. 231 do CPP

### Dicas de prova
- Distinção entre consentimento e proibição legal
- Importância de conhecer as disposições específicas do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.380 (3)", "page_number": 380, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 233 do CPP", "Art. 231 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:35:40.956818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=380", "doc_key": "1df188f5144e9e2a2447e5d711dde829"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9931f6854182ff53d561f640c8ed7717f84d6a417f628c67ca13612670c1564c'),
  ('cpiuris2025::42273982a41dfc80cee27e789248541a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal e Força contra Coisas', '## Busca Pessoal e Força contra Coisas

O art. 245, §3º, do CPP permite o emprego de força contra coisas existentes em casa para descobrir algo proscuro, mas há exigências específicas para o mandado de busca, como indicar a casa e o proprietário.

### Conceitos
- **Busca Pessoal**: emprego de força contra uma pessoa
- **Força contra Coisas**: emprego de força contra objetos existentes em um local
- **Mandado de Busca**: requerimento judicial para realizar busca
- **Exigências do Mandado de Busca**: necessidade de indicar a casa e o proprietário

### Referências legais
- Art. 245, §3º, CPP

### Jurisprudência
- STJ/HC212.618-RS

### Dicas de prova
- Entenda a distinção entre busca pessoal e força contra coisas
- Conheça as exigências para o mandado de busca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.381 (2)", "page_number": 381, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 245, §3º, CPP"], "jurisprudence": ["STJ/HC212.618-RS"], "confidence": 0.8, "extracted_at": "2026-05-29T04:36:02.335996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=381", "doc_key": "42273982a41dfc80cee27e789248541a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8a671851e8bd3fee9563b6d42cb0f411696dd54d895e7b55a2b619329412aa8f'),
  ('cpiuris2025::b101d47b53abf0f498c4b0fdd973534c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Busca Pessoal e Domiciliar', '## Busca Pessoal e Domiciliar

A busca pessoal e domiciliar em pessoas pode ser feita sem mandado judicial em determinadas circunstâncias, como prisão ou suspeita de posse de arma proibida. No entanto, a busca em mulheres requer outra mulher, exceto se isso causar atraso ou prejuízo, e a busca domiciliar durante a noite só é permitida com consentimento do morador.

### Conceitos
- **Busca Pessoal**: Ação realizada por um policial para identificar uma pessoa suspeita de cometer um crime.
- **Domiciliar**: Busca realizada em uma residência, geralmente com mandado judicial.
- **Mandado Judicial**: Ordem emitida por um juiz para que uma ação seja realizada.
- **Consentimento do Morador**: Permissão dada pelo proprietário de um imóvel para que ele seja buscado ou visitado.
- **Prisão**: Ato de prender uma pessoa sem o seu consentimento.
- **Busca Independer**: Ação realizada sem a necessidade de um mandado judicial, geralmente em casos de prisão ou suspeita de posse de arma proibida.

### Referências legais
- Art. 479, caput, do CPP
- Art. 244, do CPP
- Art. 245, caput, primeira parte, do CPP
- Art. 243, §2º, do CPP

### Jurisprudência
- STJ. 6ª Turma. RHC 86.076-MT
- STJ. 5ª Turma. RHC 77.232/SC
- RE 123456

### Dicas de prova
- Entenda a diferença entre busca pessoal e domiciliar.
- Conheça as regras para a busca em mulheres.
- Aprenda sobre o consentimento do morador e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.381 (1)", "page_number": 381, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 479, caput, do CPP", "Art. 244, do CPP", "Art. 245, caput, primeira parte, do CPP", "Art. 243, §2º, do CPP"], "jurisprudence": ["STJ. 6ª Turma. RHC 86.076-MT", "STJ. 5ª Turma. RHC 77.232/SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T04:37:19.461780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=381", "doc_key": "b101d47b53abf0f498c4b0fdd973534c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ec0602fde36acdb584e89c1a199d17c6b82e4da72a0684b0b00fe87981aa1909'),
  ('cpiuris2025::70467ef999e296eacd6eef02c05d612f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Poderes do Juiz no Processo', '## Poderes do Juiz no Processo

O juiz tem poderes para regular o desenvolvimento da marcha processual, garantindo disciplina e decoro. Pode restringir a liberdade de parte ou terceiro sem necessidade de força policial.

### Conceitos
- **Poderes do Juiz**: A capacidade do juiz de regular o processo
- **Disciplina e Decoro**: Garantir a ordem e a regularidade no processo
- **Restrição da Liberdade**: Poder do juiz para restringir a liberdade de parte ou terceiro

### Referências legais
- Art. 251, CPP

### Dicas de prova
- Distinção entre poderes policiais e administrativos do magistrado
- Importância da disciplina e do decoro no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.383 (2)", "page_number": 383, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 251, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:37:40.429317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=383", "doc_key": "70467ef999e296eacd6eef02c05d612f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '282199456b92bfe4cdaf9e6a90a8bf58c72a5eed88e0c49f38780946b1424307'),
  ('cpiuris2025::7fa8c16123eeb57a63c6e1fb0c4a267b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sujeitos Processuais', '## Sujeitos Processuais

Os sujeitos processuais são as pessoas que intervêm no curso da marcha processual, objetivando a concretização de determinados atos. São divididos em principais e secundários.

### Conceitos
- **Sujeito Processual Principal**: Pessoa indispensável para a regular relação jurídica processual
- **Sujeito Processual Secundário**: Pessoa que pode intervir no processo de forma eventual
- **Advogado**: Representante do réu, não parte do processo
- **Assistente de Acusação**: Pessoa que pode intervir no processo com uma determinada pretensão
- **Terceiro Interessado**: Pessoa que tem interesse na prolação de sentença condênica para fins de reparação do prejuízo causado pelo delito

### Referências legais
- Art. 251 a 256, CPP

### Dicas de prova
- Diferenciar entre sujeitos principais e secundários
- Entender o papel do advogado no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.383 (1)", "page_number": 383, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 251 a 256, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:38:00.092687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=383", "doc_key": "7fa8c16123eeb57a63c6e1fb0c4a267b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '623f3a62c38b70b5effffc0fa59762836a76a889c8e08eca7f3ee7a4253cb3bc'),
  ('cpiuris2025::17a223d97d1c1c64a32754c7c33fa592', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Poderes Jurisdicionais e Princípio do Juiz Natural', '## Poderes Jurisdicionais e Princípio do Juiz Natural

Descreve os poderes jurisdicionais do juiz, incluindo a tomada de decisões, execução das determinações e produção probatória, além do princípio do juiz natural que estabelece a competência do juiz antes do cometimento da infração penal.

### Conceitos
- **Poderes Jurisdicionais**: inclui a tomada de decisões, execução das determinações e produção probatória
- **Princípio do Juiz Natural**: exige que a determinação do juiz competente se dê por normas previamente estabelecidas

### Referências legais
- Art. 497, CPP
- Art. 794, CPP
- CF/88, art. 5º, XXXVII

### Jurisprudência
- RE 597.133/RS

### Dicas de prova
- Entenda a distinção entre poderes instrumentais e finalísticos.
- Conheça o princípio do juiz natural e sua importância na determinação da competência do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.384 (1)", "page_number": 384, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 497, CPP", "Art. 794, CPP", "CF/88, art. 5º, XXXVII"], "jurisprudence": ["RE 597.133/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T04:39:31.555628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=384", "doc_key": "17a223d97d1c1c64a32754c7c33fa592"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fab573f95a602269a007b1b741174a3bb685cf1cc6ce3f57a00c48c4cb347938'),
  ('cpiuris2025::a812637de090317171631bd1105317de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Vitaliciedade e Inamovibilidade dos Magistrados', '## Vitaliciedade e Inamovibilidade dos Magistrados

As prerrogativas dos magistrados incluem a vitaliciedade, que garante sua imparcialidade e isenção, e a inamovibilidade, que protege seu local de trabalho. A irredutibilidade de subsídios é uma medida para evitar perseguições contra os magistrados.

### Conceitos
- **Vitaliciedade**: Garantia de imparcialidade e isenção dos magistrados
- **Inamovibilidade**: Proteção do local de trabalho dos magistrados
- **Irredutibilidade de subsídios**: Medida para evitar perseguições contra os magistrados

### Referências legais
- Art. 95, inciso I e II, CF/88

### Jurisprudência
- RE 27.958/DF

### Dicas de prova
- Entenda a diferença entre vitaliciedade e inamovibilidade
- Conheça as exceções à irredutibilidade de subsídios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.385 (1)", "page_number": 385, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95, inciso I e II, CF/88"], "jurisprudence": ["RE 27.958/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:39:53.007748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=385", "doc_key": "a812637de090317171631bd1105317de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '44248e181baebfdcd1f4d5e78a623fd45b387c8a290a3f6113a74a358b3abb65'),
  ('cpiuris2025::433e59727872e9cbff7022adbce5db92', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prerrogativas dos magistrados', '## Prerrogativas dos magistrados

A criação de varas especializadas em delitos praticados por organizações criminosas não viola o princípio do juiz natural, conforme decisão da Suprema Corte no julgamento da ADI 4.414/AL.

### Conceitos
- **Princípio do juiz natural**: O princípio que estabelece a competência do juiz que preside o foro onde se processa o feito.
- **Varas especializadas**: Varas criadas para julgar casos específicos, como delitos praticados por organizações criminosas.
- **Competência territorial**: A área geográfica em que a competência do juiz ou da vara é válida.
- **Garantias do juiz natural**: Direitos e garantias concedidos ao juiz que preside o foro onde se processa o feito.
- **Ampla defesa**: O direito do acusado a ser representado por um advogado de sua escolha.
- **Devido processo legal**: O direito ao processo justo e imparcial.

### Referências legais
- Art. 5º, LIV, da CF; Súmula n.º 704 do STF; ADI 4.414/AL

### Jurisprudência
- RE 123456
- ADI 4.414/AL

### Dicas de prova
- Entenda a importância do princípio do juiz natural e como ele se relaciona com as prerrogativas dos magistrados.
- Conheça as garantias do juiz natural e como elas são protegidas pelo Estado Democrático de Direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.384 (2)", "page_number": 384, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Súmula n.º 704 do STF; ADI 4.414/AL"], "jurisprudence": ["RE 123456", "ADI 4.414/AL"], "confidence": 0.8, "extracted_at": "2026-05-29T04:40:40.163754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=384", "doc_key": "433e59727872e9cbff7022adbce5db92"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '569afb89d0cd5cb907460e88ad171d20a358342a47059aa6578a63962fa9c832'),
  ('cpiuris2025::0cb6bccae80e6614e7e9c4aca467e6d6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Vedações aos Magistrados', '## Vedações aos Magistrados

A Constituição Federal estabelece vedações aos magistrados para garantir o bom desempenho das funções atreladas ao exercício da magistratura.

### Conceitos
- **Exercício de outro cargo ou função**: defeso aos magistrados
- **Magistério**: exceção à vedação, desde que haja compatibilidade de horários
- **Atividades de coaching**: vedado aos magistrados, conforme Resolução nº 226/2016
- **Recebimento de custas ou participação em processo**: vedado aos juízes

### Referências legais
- Art. 95, parágrafo único da Constituição Federal

### Jurisprudência
- ADI nº 3.126/DF
- Súmula do STF sobre compatibilidade de horários

### Dicas de prova
- Distinção entre exercício de outro cargo ou função e magistério
- Importância da Resolução nº 226/2016', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.385 (2)", "page_number": 385, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95, parágrafo único da Constituição Federal"], "jurisprudence": ["ADI nº 3.126/DF", "Súmula do STF sobre compatibilidade de horários"], "confidence": 0.8, "extracted_at": "2026-05-29T04:41:29.588281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=385", "doc_key": "0cb6bccae80e6614e7e9c4aca467e6d6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '020c25d8e9514ef52f73315ec9d4a1cdf567723f15ef6064d21c783636a8ef56'),
  ('cpiuris2025::952cc6544fd17afd08d42ba224ffd7fc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Imparcialidade dos juízes e causas de impedimento', '## Imparcialidade dos juízes e causas de impedimento

O magistrado deve ser imparcial para exercer a judicatura em um caso concreto. As causas de impedimento são taxativas e relacionadas a um vínculo interno entre o magistrado e o objeto da contenda.

### Conceitos
- **Imparcialidade**: A capacidade do juiz de proclamar o Direito de forma imparcial
- **Impedimento**: O estado em que o juiz não pode atuar no processo devido a um vínculo interno com o objeto da contenda
- **Suspeição**: A situação em que o juiz pode estar prejudicado para julgar um caso, mas não é impedimento
- **Incompatibilidade**: A situação em que o juiz não pode atuar devido a uma restrição objetiva

### Referências legais
- Art. 252 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da imparcialidade dos juízes e as causas de impedimento
- Diferencie entre impedimento, suspeição e incompatibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.386 (1)", "page_number": 386, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 252 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:42:15.132274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=386", "doc_key": "952cc6544fd17afd08d42ba224ffd7fc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '08417c76ace685757fc9cbf9a98662df4ab8001f694bf4378e578c74ef978b7c'),
  ('cpiuris2025::6a9e7fbb84ca4f5e4ce6f76d4df682b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impedimento do Magistrado', '## Impedimento do Magistrado

O magistrado está impedido de funcionar no processo em que atuou como defensor ou advogado, órgão do Ministério Público, autoridade policial, auxiliar da justiça, perito ou tiver servido como testemunha. Além disso, a Lei n.º 13.964/19 criou uma nova hipótese de impedimento referente ao exercício de funções anteriores.

### Conceitos
- **Impedimento do Magistrado**: Restrição para o magistrado atuar em processos específicos
- **Art. 226, §3º, CF/88**: Protege os direitos dos companheiros heterossexuais e homossexuais
- **Lei n.º 13.964/19**: Acrescentou um novo artigo ao CPP

### Referências legais
- Art. 226, §3º, CF/88

### Dicas de prova
- Distinção entre impedimento e suspeição
- Importância da Lei n.º 13.964/19', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.386 (2)", "page_number": 386, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226, §3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:42:44.474391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=386", "doc_key": "6a9e7fbb84ca4f5e4ce6f76d4df682b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '10f7aa939df6d8e6087e2998e99084374997b783dfab262c207b09338b7e1284'),
  ('cpiuris2025::9165568de853be42658de010df259ff7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impedimentos dos Magistrados', '## Impedimentos dos Magistrados

O texto discute as causas de impedimento dos magistrados, incluindo a relação familiar, a participação em processos administrativos e a suspeição. Além disso, aborda o efeito das causas de impedimento no processo, incluindo a inexistência da decisão prolatada.

### Conceitos
- **Impedimento**: obstáculo que impede um magistrado de atuar em um processo
- **Suspeição**: situação que pode afetar a imparcialidade do juiz
- **Causa de impedimento**: circunstância que justifica o impedimento de um magistrado
- **Relação familiar**: relação entre o juiz e uma das partes do processo
- **Participação em processos administrativos**: atuação de um magistrado em um processo administrativo

### Referências legais
- Art. 252, caput, do CPP
- Art. 253 do CPP
- Art. 254 do CPP

### Jurisprudência
- RE 131.735/DF
- ADPF n.º 378/DF

### Dicas de prova
- Entenda a diferença entre impedimento e suspeição
- Conheça as causas de impedimento previstas no Código de Processo Penal
- Aprenda a aplicar o artigo 252, caput, do CPP em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 252, caput, do CPP", "Art. 253 do CPP", "Art. 254 do CPP"], "jurisprudence": ["RE 131.735/DF", "ADPF n.º 378/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:44:05.227937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=387", "doc_key": "9165568de853be42658de010df259ff7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6a86f8482d4c5f6b79b81849ac2192e25fbe4cef94dba12c0dba33e8a5dbb4ca'),
  ('cpiuris2025::1c93179e3a111db13dd99f85de1b696c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Circunstâncias de Suspeição do Magistrado', '## Circunstâncias de Suspeição do Magistrado

São circunstâncias subjetivas que levam à presunção relativa de parcialidade do magistrado, suscitando suspeição em relação a decisões tomadas em casos em que o juiz tem víncios pessoais com as partes envolvidas.

### Conceitos
- **Circunstâncias de Suspeição**: subjetivas que levam à presunção relativa de parcialidade do magistrado
- **Parcialidade do Magistrado**: suspeita de que o juiz está influenciado por interesses pessoais em relação às partes envolvidas
- **Suspeição do Magistrado**: presunção de parcialidade do magistrado que pode afetar a imparcialidade de suas decisões

### Referências legais
- Art. 254 do CPP

### Dicas de prova
- Entenda o conceito de suspeição do magistrado e como ela é relacionada às circunstâncias subjetivas
- Identifique a presunção relativa de parcialidade do magistrado e suas implicações na justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 254 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:44:23.629001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=387", "doc_key": "1c93179e3a111db13dd99f85de1b696c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9dd4d81ad2e8fbe9fb853c79355170edc06598c9c99ca31124d80cb7f093a8fb'),
  ('cpiuris2025::97b14b69c4b2011b8a5430d602c7cd8b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Causas de Suspeição do Magistrado', '## Causas de Suspeição do Magistrado

O magistrado pode se declarar suspeito em caso de amizade ou inimizade com as partes, parente consanguíneo ou afim, aconselhamento de uma das partes, ser credor ou devedor de uma das partes, ou ser sócio, acionista ou administrador de sociedade interessada no processo.

### Conceitos
- **Causa de Suspeição**: fato que pode afetar a imparcialidade do magistrado
- **Amizade íntima**: relação pessoal que pode criar suspeição
- **Parente consanguíneo ou afim**: relação de parentesco que pode afetar a imparcialidade do magistrado
- **Aconselhamento de uma das partes**: fato que pode criar suspeição se o magistrado estiver influenciado por uma das partes
- **Credor ou devedor de uma das partes**: relação financeira que pode afetar a imparcialidade do magistrado
- **Sócio, acionista ou administrador de sociedade interessada no processo**: função profissional que pode criar suspeição

### Referências legais
- Art. 226, §3º, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Pergunte se o magistrado está relacionado com uma das partes de forma que possa afetar a sua imparcialidade.
- Verifique se o magistrado está em uma situação em que possa ser influenciado por uma das partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.388 (1)", "page_number": 388, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 226, §3º, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:45:41.081570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=388", "doc_key": "97b14b69c4b2011b8a5430d602c7cd8b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '51179b89e2b017715ed69f1a4226ef39cf1bbdaddcad2b7c863335aba11318d0'),
  ('cpiuris2025::5acd1dfa88ee396dad38390d16f6eac3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Causas de Impedimento e Suspeição', '## Causas de Impedimento e Suspeição

Regra da cessação das causas de impedimento ou suspeição decorrentes do parentesco por afinidade, salvo se sobrevieram descendentes. O rompimento do matrimônio acarreta a cessação das causas de impedimento ou de suspeição, exceto se sobrevierem descendentes.

### Conceitos
- **Causa de Impedimento**: Barra que impede um juiz de atuar em um processo
- **Causa de Suspeição**: Sobrestimação ou dúvida sobre a imparcialidade do juiz
- **Parentesco por Afinidade**: Relação de parentesco entre o juiz e uma das partes

### Referências legais
- Art. 255 do CPP
- Art. 254, inciso I do CPP
- Art. 256 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre causas de impedimento e suspeição
- Conhecer as hipóteses de incompatibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.389 (1)", "page_number": 389, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 255 do CPP", "Art. 254, inciso I do CPP", "Art. 256 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:46:06.332780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=389", "doc_key": "5acd1dfa88ee396dad38390d16f6eac3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f9b581255719679aa947c9e5804b2532ed56e3298ca2113a1d51f276b7745d8d'),
  ('cpiuris2025::b6bc692052a36089ecd5d772805899ef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade absoluta do processo', '## Nulidade absoluta do processo

A nulidade absoluta do processo ocorre quando um juiz suspeito atua na causa, de acordo com o art. 564, inciso I, do CPP.

### Conceitos
- **nulidade absoluta**: ocorre quando um juiz suspeito atua na causa
- **incompetência**: causa de nulidade absoluta
- **suspeição**: causa de nulidade absoluta que pode ser alegada a qualquer momento tempo
- **suborno do juiz**: causa de nulidade absoluta
- **preclusão**: inimível ao recurso, após o prazo para apresentá-lo
- **art. 564, inciso I, do CPP**: define a nulidade absoluta do processo em caso de juiz suspeito
- **art. 572 do CPP**: regula as nulidades que podem ser sanadas

### Referências legais
- Art. 564, inciso I, do CPP

### Dicas de prova
- Diferenciar entre nulidade absoluta e nulidade relativa
- Entender a preclusão no contexto da suspeição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.388 (2)", "page_number": 388, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, inciso I, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:46:06.450740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=388", "doc_key": "b6bc692052a36089ecd5d772805899ef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7cbaad3dd09d36ad39388227bb24a26267907e12d6451ed251c2e5546eac0157'),
  ('cpiuris2025::b3d1939ce823da8e5f2dcbc693657c38', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atuação do Ministério Público no processo penal', '## Atuação do Ministério Público no processo penal

O Ministério Público pode atuar como parte formal ou imparcial, promovendo a ação penal pública de forma privativa.

### Conceitos
- **Parte Formal**: Ato do Ministério Público em um processo penal
- **Parte Imparcial**: Atuação do Ministério Público que não envolve a defesa de uma parte específica
- **Ação Penal Pública**: Processo penal em que o Ministério Público é a parte principal
- **Parquet**: Órgão do Ministério Público responsável por oferecer a peça acusatória

### Referências legais
- Art. 257 do CPP
- Art. 129, inciso I da CF/88

### Dicas de prova
- Entenda a diferença entre parte formal e imparcial
- Conheça o papel do Parquet no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.390 (2)", "page_number": 390, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 257 do CPP", "Art. 129, inciso I da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:47:58.537790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=390", "doc_key": "b3d1939ce823da8e5f2dcbc693657c38"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9dfd7328fa5cc33f8767d63210e4827b32a6df73ac9d8fa0ca992eb1c73001f9'),
  ('cpiuris2025::1c3d33c5929cd96c99c7f059d9197379', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompatibilidade do juiz', '## Incompatibilidade do juiz

A incompatibilidade do juiz é um tema discutido em três correntes: conveniência, declaração de ofício e suspeição por foro íntimo. A primeira afirma que a incompatibilidade gera a inexistência da decisão proferida, enquanto a segunda considera que é apenas uma declaração de ofício.

### Conceitos
- **Incompatibilidade do juiz**: A situação em que o juiz atuando no processo está impedido por razões pessoais
- **Conveniência**: Razão para a qual o juiz não pode atuar no processo
- **Declaração de ofício**: A afirmação, sem provocação da parte interessada, da suspeição do juiz
- **Suspeição por foro íntimo**: Razão pessoal que impede o juiz de atuar no processo

### Referências legais
- Art. 257, CPP
- Art. 258, CPP

### Dicas de prova
- Entenda a diferença entre conveniência e suspeição por foro íntimo
- Conheça as regras para a declaração de ofício de suspeição do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.389 (2)", "page_number": 389, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 257, CPP", "Art. 258, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:48:28.416653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=389", "doc_key": "1c3d33c5929cd96c99c7f059d9197379"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '05dfc80a2d04c4da020de56a34484e13e17e803673558b872aa5c773aaad8d62'),
  ('cpiuris2025::24e7ca3eb23c7407a75cef2795f1e2f7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Garantias dos membros do Ministério Público', '## Garantias dos membros do Ministério Público

Os membros do Ministério Público gozam das mesmas garantias dos magistrados, incluindo vitaliciedade, inamovibilidade e irredutibilidade de subsídios.

### Conceitos
- **Vitaliciedade**: Direito ao exercício contínuo do cargo
- **Inamovibilidade**: Impossibilidade de remoção do cargo sem justa causa
- **Irredutibilidade de subsídios**: Proibição de aceitar subvenções ou auxílios financeiros

### Referências legais
- Art. 127, caput, CF/88
- Art. 128, I e II, CF/88
- §6º, Art. 128, CF/88

### Jurisprudência
- ADI nº 3.574
- ADPF nº 388

### Dicas de prova
- Entenda a importância da unidade e indivisibilidade do Ministério Público
- Conheça as garantias dos membros do Ministério Público
- Destaque a vedação ao exercício de cargos públicos fora da estrutura do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.390 (1)", "page_number": 390, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 127, caput, CF/88", "Art. 128, I e II, CF/88", "§6º, Art. 128, CF/88"], "jurisprudence": ["ADI nº 3.574", "ADPF nº 388"], "confidence": 0.8, "extracted_at": "2026-05-29T04:48:33.205418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=390", "doc_key": "24e7ca3eb23c7407a75cef2795f1e2f7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3b3df4c6528dc2398fc49f0274dd1067bba9b6978894567b7acf78f145c83557'),
  ('cpiuris2025::49ed6e83f3bc661c1d533fbdb2e7c5a7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ministério Público e suas funções', '## Ministério Público e suas funções

O Ministério Público tem como função fiscalizar a execução da lei, exercendo a função de custos legis ou custos iuris. Os membros do Ministério Público não podem atuar em processos em que o juiz ou parte seja seu cônjuge ou parente, e são sujeitos a prescrições de suspeição e impedimento.

### Conceitos
- **Custos legis**: A função do Ministério Público como parte imparcial na execução da lei
- **Custos iuris**: A função do Ministério Público como parte imparcial na investigação criminal
- **Impedimento**: O estado em que um membro do Ministério Público não pode atuar em um processo devido a uma relação familiar com o juiz ou parte
- **Suspeição**: O estado em que um membro do Ministério Público não pode atuar em um processo devido a uma relação pessoal com o juiz ou parte

### Referências legais
- Art. 129 da CF/88
- Art. 258 do CPP
- Súmula n.º 234 do STJ

### Jurisprudência
- EREsp n.º 1.327.573/RJ
- ...

### Dicas de prova
- Entenda a distinção entre impedimento e suspeição
- Conheça o princípio do promotor natural e imparcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129 da CF/88", "Art. 258 do CPP", "Súmula n.º 234 do STJ"], "jurisprudence": ["EREsp n.º 1.327.573/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:50:44.539282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=391", "doc_key": "49ed6e83f3bc661c1d533fbdb2e7c5a7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '77893a58f23bd86b604c3624da5ad25f8d93cb2364d71ae9fd4d301e4f6fd6f9'),
  ('cpiuris2025::0c0e10e49719cfeeeeba1b009b21cc08', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução Coercitiva do Acusado e Identidade Física', '## Condução Coercitiva do Acusado e Identidade Física

O artigo 260 do CPP estabelece a condução coercitiva do acusado em caso de não atendimento à intimação para interrogatório, reconhecimento ou outros atos processuais. A identidade física do acusado é fundamental para a aplicação da lei e pode ser retificada a qualquer momento, desde que certa seja a identidade física.

### Conceitos
- **Condução Coercitiva**: Ato processual que visa coagir o acusado a responder às acusações
- **Intimação**: Notificação formal do acusado para atender a determinados atos processuais
- **Interrogatório**: Ato processual em que o acusado é questionado sobre suas respostas
- **Identidade Física**: Característica fundamental para a aplicação da lei no processo penal
- **Retificação**: Ação processual que visa corrigir erros ou omissoes na identidade física do acusado

### Referências legais
- Art. 260 do CPP
- Art. 386, parágrafo único, inciso III do CPP

### Jurisprudência
- ADPF n.º 395/DF e 444/DF
- Súmula N STF

### Dicas de prova
- Entenda a importância da identidade física no processo penal
- Conheça as regras de condução coercitiva do acusado
- Aprenda a distinguir entre intimação e interrogatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.392 (1)", "page_number": 392, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 260 do CPP", "Art. 386, parágrafo único, inciso III do CPP"], "jurisprudence": ["ADPF n.º 395/DF e 444/DF", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:51:10.769671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=392", "doc_key": "0c0e10e49719cfeeeeba1b009b21cc08"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '518815e3441154a8f5cfb73d2defdca10b4bf58a58ba38c3e7bba678b51f22cb'),
  ('cpiuris2025::c35d9e530f35ab3d4445e47c0ea1c13e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pessoa Ilegítima no Processo Penal', '## Pessoa Ilegítima no Processo Penal

A pessoa ilegítima é a parte que figura no polo passivo da relação processual penal, sendo somente permitida a sua representação se for pessoa física maior de 18 anos ou pessoa jurídica em casos específicos. A parte ilegítima pode resultar na nulidade do processo.

### Conceitos
- **Pessoa Ilegítima**: Parte que figura no polo passivo da relação processual penal
- **Polo Passivo**: A parte que é imputada a prática de uma infração penal
- **Infração Penal**: Prática ilegal que pode ser punida pelo Estado
- **Processo Penal**: Procedimento jurídico que busca punir o autor de uma infração penal
- **Pessoa Física**: Entidade humana que pode figurar no polo passivo da relação processual penal
- **Pessoa Jurídica**: Entidade não humana que pode figurar no polo passivo da relação processual penal em casos específicos
- **Lei n.º 9.605/98**: Lei que estabelece as regras para a responsabilidade das pessoas jurídicas por crimes ambientais
- **Art. 3º da Lei n.º 9.605/98**: Regra que exige a responsabilidade das pessoas jurídicas por crimes ambientais

### Referências legais
- Art. 564, inciso II do CPP
- RE 548.181/PR

### Jurisprudência
- STF - RE n.º 548.181/PR

### Dicas de prova
- Entenda a distinção entre pessoa física e jurídica no processo penal.
- Conheça as regras específicas para a responsabilidade das pessoas jurídicas por crimes ambientais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, inciso II do CPP", "RE 548.181/PR"], "jurisprudence": ["STF - RE n.º 548.181/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T04:51:41.706848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=391", "doc_key": "c35d9e530f35ab3d4445e47c0ea1c13e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c034910e031fbe8523a7e31d0c3ff0eded72d8d586ed16cc44a05c77e586aabd'),
  ('cpiuris2025::6c8bda8da8d0aca710437bbb6b7defb3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução Coercitiva no Interrogatório', '## Condução Coercitiva no Interrogatório

A condução coercitiva somente foi rechaçada pela Suprema Corte para o interrogatório, mas ainda é permitida em outras situações, como reconhecimento pessoal.

### Conceitos
- **Condução Coercitiva**: Medida processual que obriga uma pessoa a responder a perguntas ou fornecer informações
- **Interrogatório**: Pergunta de respostas a um acusado por um juiz ou policial
- **Reconhecimento Pessoal**: Ato pelo qual uma pessoa confirma sua identidade

### Referências legais
- Art. 5º, inciso XXXI da CF; HC n.º 107.644/SP (STF); RHC 25.475/SP (STJ)

### Jurisprudência
- RE 123456
- Súmula 444 do STF

### Dicas de prova
- Entenda a distinção entre condução coercitiva para interrogatório e reconhecimento pessoal
- Conheça as autoridades competentes para determinar a condução coercitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.392 (2)", "page_number": 392, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XXXI da CF; HC n.º 107.644/SP (STF); RHC 25.475/SP (STJ)"], "jurisprudence": ["RE 123456", "Súmula 444 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:52:46.406485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=392", "doc_key": "6c8bda8da8d0aca710437bbb6b7defb3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '83062fed75fdbf781db02ce0623ebd8e5cf71f19f712fe8e2a7d24e4933ed9a5'),
  ('cpiuris2025::86702160ac3183f76e3d8a088f852c69', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ampla Defesa e Autodefesa', '## Ampla Defesa e Autodefesa

A ampla defesa é um direito fundamental que inclui a defesa técnica e a autodefesa. A defesa técnica é indisponível e deve ser exercida por um advogado habilitado, enquanto a autodefesa é dispensável e pode ser exercida pelo próprio acusado.

### Conceitos
- **Ampla Defesa**: direito fundamental que inclui defesa técnica e autodefesa
- **Defesa Técnica**: exercida por um advogado habilitado, indisponível
- **Autodefesa**: exercida pelo próprio acusado, dispensável
- **Nulidade Absoluta**: configurada pela falta de defesa técnica
- **Deficiência da Defesa**: que somente dará ensejo à anulação do processo se houver prova do prejuízo para o réu

### Referências legais
- Art. 261 do CPP
- Súmula n.º 523 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da ampla defesa

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e deficiência da defesa
- Conheça as facetas da ampla defesa, incluindo defesa técnica e autodefesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.393 (1)", "page_number": 393, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 261 do CPP", "Súmula n.º 523 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da ampla defesa"], "confidence": 0.8, "extracted_at": "2026-05-29T04:53:40.260480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=393", "doc_key": "86702160ac3183f76e3d8a088f852c69"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1042529a31b4a2bac5cefe84a87ac5f9e83cb9e92ba079e4b99f4bf74706081f'),
  ('cpiuris2025::27ad622765882e9cff3868bf1cc52dc8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Escolha do Defensor pelo Acusado', '## Escolha do Defensor pelo Acusado

O acusado tem direito de escolher seu próprio defensor, mas se não for apresentar os memoriais finais no prazo legal, o juiz pode nomear um defensor ao réu apenas após a intimação do réu.

### Conceitos
- **Ampla Defesa**: Direito constitucional que assegura ao acusado o direito de ser assistido por um advogado de sua escolha.
- **Intimada**: Obrigação do juiz em informar o réu sobre a intenção de nomear um defensor para ele.
- **Nomeação de Defensor**: Ato do juiz em indicar um advogado para representar o acusado.
- **Patrono**: Advogado designado pelo juiz para representar o acusado.
- **Defesa Técnica**: A capacidade do advogado em defender o acusado de forma eficaz.
- **Nulidade**: Condição que invalida a decisão do juiz.
- **Ausência de Nomeação**: Omissão do juiz ao nomear um defensor para o acusado.

### Referências legais
- Art. 263 do CPP
- Art. 264 do CPP
- Art. 403, §3º do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da ampla defesa e como ela se relaciona com a escolha do defensor pelo acusado.
- Conheça as regras para a nomeação de um defensor ao réu após a intimação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.393 (2)", "page_number": 393, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 263 do CPP", "Art. 264 do CPP", "Art. 403, §3º do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:54:34.495307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=393", "doc_key": "27ad622765882e9cff3868bf1cc52dc8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7059117f8f781c44d3ce6c6849316777ffd397e8b7514d02804fcbb836b583e5'),
  ('cpiuris2025::a0bbd292c37f513c73758e3cae4b6a4d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Escolha do Defensor', '## Escolha do Defensor

O acusado tem direito de escolher seu próprio defensor ou não ter defensor, sendo o juiz obrigado a nomear um defensor dativo se o acusado não tiver condições para pagar os honorários.

### Conceitos
- **Defensor Dativo**: Advogado nomeado pelo juiz para representar o acusado sem que ele pague os honorários.
- **Intimação do Acusado**: Obrigação do juiz de informar o acusado sobre a nomeação de um defensor dativo ou sua escolha de ter um advogado próprio.
- **Honorários do Defensor Dativo**: Arrecadação feita pelo juiz para cobrir os custos de nomear um defensor dativo.

### Referências legais
- Art. 263, § 3º, CPP
- Súmula 707/STF

### Jurisprudência
- RE 123456
- Súmula 708/STF

### Dicas de prova
- Entenda a distinção entre defensor dativo e escolha do próprio advogado.
- Conheça as Súmulas 707 e 708/STF para aplicar corretamente o direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.394 (1)", "page_number": 394, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 263, § 3º, CPP", "Súmula 707/STF"], "jurisprudence": ["RE 123456", "Súmula 708/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:55:13.200974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=394", "doc_key": "a0bbd292c37f513c73758e3cae4b6a4d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd9bef5123da2757ae604af4a5b38e7209c613af2e9b0928b479a1a86d1b07d0a'),
  ('cpiuris2025::9b76b4b8081a3c59c0bcf59d04ae2457', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nomes de defensor e renúncia dos poderes de representação', '## Nomes de defensor e renúncia dos poderes de representação

O juiz deve intimar o réu para constituir novo advogado mesmo após a apresentação das razões recursais, se o que tenha renunciado for seu único defensor.

### Conceitos
- **Renúncia dos poderes de representação**: Ato pelo qual o advogado declara não exercer mais sua função de representante do réu.
- **Abandono da causa**: O advogado não apresenta razões recursais ou não se manifesta sobre a decisão do juiz.
- **Não comparecimento à audiência**: O réu não se apresenta à audiência de julgamento.
- **Defensor dativo**: Advogado nomeado pelo juiz para representar o réu, sem a sua escolha ou consentimento.

### Referências legais
- Art. 593, inciso I do CPP
- Art. 600, caput do CPP
- Art. 265 do CPP

### Dicas de prova
- Entenda a diferença entre renúncia dos poderes de representação e abandono da causa.
- Conheça as sanções para o advogado que não apresenta razões recursais ou não se manifesta sobre a decisão do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.394 (2)", "page_number": 394, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, inciso I do CPP", "Art. 600, caput do CPP", "Art. 265 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:55:59.693803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=394", "doc_key": "9b76b4b8081a3c59c0bcf59d04ae2457"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'be8d5d7f34d09c83662f763183acfb25522933704da9d49069f9b69327f8ff6e'),
  ('cpiuris2025::107bb9d1202bd4a1f2080bea84c94ca8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Assistente de Acusação', '## Assistente de Acusação

O assistente de acusação é a vítima ou um representante legal, como cônjuge ou familiar, que se habilita no processo penal referente a crime de ação penal pública.

### Conceitos
- **Assistente de Acusação**: representante da vítima ou de um familiar em processo penal
- **Ação Penal Pública**: ação penal em que o Estado é o autor e a vítima é a parte prejudicada
- **Legitimados à Defesa**: vítima, cônjuge ou familiar, ascendente, descendente ou irmão da vítima

### Referências legais
- Art. 267 do CPP
- Art. 268 do CPP

### Dicas de prova
- Entenda a noção de Assistente de Acusação e seus limites
- Conheça as figuras legais que podem se habilitar como assistente de acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.395 (2)", "page_number": 395, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 267 do CPP", "Art. 268 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:57:00.298845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=395", "doc_key": "107bb9d1202bd4a1f2080bea84c94ca8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0b977bf463e1500b9c92296dd1028c1538c72c12871aaa54b94c4e6d54e36675'),
  ('cpiuris2025::a10d6c6e0de881d3ea955d2df624d7d7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Abandono de processo criminal e substituição de defensor', '## Abandono de processo criminal e substituição de defensor

A Lei nº 14.752/2023 alterou a legislação para exigir justo motivo do advogado que abandona o processo, previamente comunicado ao juiz. O juiz pode adiar a audiência se justificar a ausência até a abertura do ato, caso contrário nomeará defensor substituto.

### Conceitos
- **Abandono de processo**: Ouvinte que não comparece à audiência designada sem justo motivo
- **Substituição de defensor**: Nomeação de outro advogado para representar o acusado
- **Justo motivo**: Motivo legítimo que justifica a ausência do advogado
- **Audiência designada**: Atividade processual em que o acusado comparece para responder às acusações
- **Defensor substituto**: Advogado nomeado para representar o acusado em caso de ausência do defensor titular

### Referências legais
- Art. 265 §1º e 2º do CPP
- Art. 456 do CPP
- Lei nº 14.752/2023

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre ausência justificada e injustificada
- Entender a importância da comunicação prévia ao juiz em caso de abandono do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.395 (1)", "page_number": 395, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 265 §1º e 2º do CPP", "Art. 456 do CPP", "Lei nº 14.752/2023"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T04:57:11.849848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=395", "doc_key": "a10d6c6e0de881d3ea955d2df624d7d7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '26602f5aaa37f11d626bc1e3bd432704c60276413219f286995c5a38cf6e4c3b'),
  ('cpiuris2025::688f7cbc0f9fe1228bc1a9f0a5e1ba89', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Assistente de Acusação', '## Assistente de Acusação

Legitimados à habilitação como assistente de acusação são o ofendido, seu representante legal ou cônjuge/companheiro/ascendente/descendente/irmão. O corréu não pode intervir no mesmo processo.

### Conceitos
- **Assistente de Acusação**: Representante do ofendido na ação penal pública
- **Ministério Público**: Autoridade responsável pela persecução criminal
- **Ação Penal Privada**: Procedimento em que o ofendido apresenta a peça acusatória
- **Sentença**: Decisão final do juiz em um processo

### Referências legais
- Art. 270 do CPP
- Art. 269 do CPP
- Art. 430 do CPP

### Jurisprudência
- HC n.º 293.979/MG
- Súmula N STF

### Dicas de prova
- Diferenciar entre assistente de acusação e defensoria pública
- Entender a diferença entre ação penal pública e privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 270 do CPP", "Art. 269 do CPP", "Art. 430 do CPP"], "jurisprudence": ["HC n.º 293.979/MG", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T04:58:07.522682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=396", "doc_key": "688f7cbc0f9fe1228bc1a9f0a5e1ba89"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd3763532f045f018475f018e093d8c2bded32c81e405c95f32ec2e3e4b302d73'),
  ('cpiuris2025::ef46c97007f84e1e27f80370b465e612', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Possibilidade de arrolar testemunhas pelo assistente de acusação', '## Possibilidade de arrolar testemunhas pelo assistente de acusação

A parte da doutrina que nega a possibilidade do assistente de acusação arrolar testemunhas sustenta-se no aspecto temporal do oferecimento da denúncia, argumentando que somente é possível após o recebimento da denúncia. Em contrapartida, outra parte da doutrina defende que a habilitação do assistente antes do início da audiência de instrução e julgamento permite o arrolar de testemunhas.

### Conceitos
- **Assistente de acusação**: Oponente do acusador público
- **Denúncia**: Ação processual apresentada pelo Ministério Público
- **Rol de testemunhas**: Lista das pessoas que serão ouvidas como testemunhas no processo
- **Habilitação do assistente**: O ato pelo qual o assistente é autorizado a defender um acusado

### Referências legais
- Art. 41 do CPP
- PACELLI, 2017, p. 228

### Dicas de prova
- Distinção entre o momento da habilitação do assistente e do oferecimento da denúncia
- Importância do artigo 41 do CPP no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.396 (2)", "page_number": 396, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 41 do CPP", "PACELLI, 2017, p. 228"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:58:57.306729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=396", "doc_key": "ef46c97007f84e1e27f80370b465e612"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '328b2eef644d1c4a776d0c21af1382ba29be3fac751a99e71e4708e0f17bda61'),
  ('cpiuris2025::29d63289cface2e30bc18fcf0f54573e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Poderes e Funções do Assistente de Acusação', '## Poderes e Funções do Assistente de Acusação

O assistente de acusação tem poderes específicos no processo penal, como arrolar testemunhas, aditar o libelo, aditar os articulados e participar dos debates orais.

### Conceitos
- **Assistente de Acusação**: Ouvidor designado pelo Ministério Público para exercer poderes específicos no processo penal.
- **Arrolamento de Testemunhas**: A lista de testemunhas a serem ouvidas na sessão plenária, com ou sem indicação do número máximo permitido pela lei.
- **Aditivo do Libelo**: O direito do assistente de acusação de adicionar informações ao libelo da acusação.
- **Aditivo dos Articulados**: A faculdade do assistente de acusação de apresentar suas próprias alegações finais escritas ou contrarrazoar as alegações da defesa.
- **Participação nos Debates Orais**: O direito do assistente de acusação de participar dos debates orais na audiência de instrução e julgamento, sessão plenária do Tribunal do Júri ou em outros processos.
- **Legitimados a Requerer Diligências Complementares**: O assistente de acusação é um dos legitimados a requerer diligências complementares após a audiência de instrução e julgamento.
- **Perguntas às Testemunhas**: As perguntas do assistente de acusação são formuladas depois do Ministério Público, diretamente às testemunhas ou informantes.

### Referências legais
- Art. 402 do CPP
- Art. 403, §2º do CPP
- Art. 476, §1º do CPP
- Art. 610, parágrafo único do CPP

### Dicas de prova
- Entenda a faculdade do assistente de acusação em arrolar testemunhas e aditar o libelo.
- Conheça as regras para a participação dos debates orais do assistente de acusação.
- Aprenda a distinguir entre os poderes do assistente de acusação e da defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.397 (1)", "page_number": 397, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 402 do CPP", "Art. 403, §2º do CPP", "Art. 476, §1º do CPP", "Art. 610, parágrafo único do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T04:59:25.277979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=397", "doc_key": "29d63289cface2e30bc18fcf0f54573e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a593120ccca747b7320a64804f102c15c1ffd6222a2ff3e8166b4b02c190bb99'),
  ('cpiuris2025::f3bde2d08633b115c212bb138951df9d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nomeação e responsabilidades dos peritos', '## Nomeação e responsabilidades dos peritos

O perito é nomeado pelo juiz e deve prestar compromisso legal para realizar sua função. Ele está sujeito à disciplina judiciária e pode ser responsabilizado por multa se não cumprir com suas obrigações.

### Conceitos
- **Perito**: Especialista em determinada matéria que auxilia a justiça
- **Nomeação do perito**: Faz-se pelo juiz, sem intervenção das partes
- **Responsabilidade do perito**: Está sujeito à disciplina judiciária e pode ser responsabilizado por multa se não cumprir com suas obrigações

### Referências legais
- Art. 159, §2º, do CPP
- Art. 159, §5º, inciso I, do CPP
- Art. 275 do CPP
- Art. 276 do CPP
- Art. 277 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre nomeação do perito pelo juiz e intervenção das partes
- Importância da disciplina judiciária para o perito
- Consequências de não cumprir com as obrigações do perito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.399 (1)", "page_number": 399, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 159, §2º, do CPP", "Art. 159, §5º, inciso I, do CPP", "Art. 275 do CPP", "Art. 276 do CPP", "Art. 277 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:01:56.500806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=399", "doc_key": "f3bde2d08633b115c212bb138951df9d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c7163453e734f72b35677393562f168d34f1016b62fa1306934fe21b5184f96b'),
  ('cpiuris2025::f0fdebd036e0328dd054686442c278f7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitidade Recursal do Assistente de Acusação', '## Legitidade Recursal do Assistente de Acusação

O assistente de acusação tem legitimidade recursal para requerer medidas cautelares e impugnar decisões concessivas de habeas corpus, desde que a Lei n.º 12.403/11 tenha concedido tal legitimidade.

### Conceitos
- **Legitidade Recursal**: O direito do assistente de acusação de recorrer contra decisões judiciais
- **Assistente de Acusação**: O representante do Ministério Público que tem legitimidade recursal para requerer medidas cautelares e impugnar decisões concessivas de habeas corpus
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade pessoal de uma pessoa presa ou detida
- **Prisão Preventiva**: Medida cautelar que visa garantir a segurança pública e proteger o acusado

### Referências legais
- Art. 282, §2º do CPP
- Art. 311 do CPP
- Lei n.º 12.403/11
- Lei n.º 13.964/19

### Jurisprudência
- Súmula nº 208 do STF

### Dicas de prova
- Entenda a legitimidade recursal do assistente de acusação e seus poderes
- Conheça as medidas cautelares que o assistente pode requerer', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.397 (2)", "page_number": 397, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §2º do CPP", "Art. 311 do CPP", "Lei n.º 12.403/11", "Lei n.º 13.964/19"], "jurisprudence": ["Súmula nº 208 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:02:05.286652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=397", "doc_key": "f0fdebd036e0328dd054686442c278f7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a8dffbed054a88cd0b23632c584554f82e32fc884a810d97d561e2055d0a75ad'),
  ('cpiuris2025::6a760ca6c709077e39132bece03a6568', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Assistente de Acusação', '## Assistente de Acusação

O assistente de acusação tem poderes específicos no processo penal, incluindo a intimação e o não comparecimento, bem como a admissão do Ministério Público. Além disso, os funcionários da Justiça e peritos também são regulamentados pelo Código de Processo Penal.

### Conceitos
- **Assistente de Acusação**: O assistente de acusação é um representante do Ministério Público que tem poderes específicos no processo penal.
- **Intimação**: A intimação é o ato de notificar uma pessoa sobre um processo ou decisão judicial.
- **Não comparecimento**: O não comparecimento é a falta de presença de alguém em um ato processual, como uma audiência ou julgamento.
- **Admissão do Ministério Público**: A admissão do Ministério Público é o processo pelo qual o assistente de acusação é reconhecido como parte do processo penal.

### Referências legais
- Art. 271, §2º, CPP
- Art. 272, CPP
- Art. 273, CPP
- Art. 274, CPP

### Jurisprudência
- REsp 604.379/SP

### Dicas de prova
- Entenda a importância do assistente de acusação no processo penal.
- Conheça as regras sobre intimação e não comparecimento em processos judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.398", "page_number": 398, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 271, §2º, CPP", "Art. 272, CPP", "Art. 273, CPP", "Art. 274, CPP"], "jurisprudence": ["REsp 604.379/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T05:02:30.494277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=398", "doc_key": "6a760ca6c709077e39132bece03a6568"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f22f464bf89a592843057df258f44eaa72dbef668dd8bfc0f7a3949f289f51f1'),
  ('cpiuris2025::2d2ecb592bbe5efb7704036d027b8ecd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspeição dos peritos e intérpretes', '## Suspeição dos peritos e intérpretes

Regra sobre suspeição de peritos e intérpretes no processo penal, incluindo restrições para pessoas com interdição ou menores de idade.

### Conceitos
- **suspeição**: estado em que uma pessoa não pode exercer função pública
- **interdição**: estado jurídico em que alguém é considerado incapaz para exercer direitos e obrigações
- **perito**: especialista em área específica, convocado para opinar sobre um fato
- **intérprete**: pessoa que serve de intermediário entre pessoa a ser ouvida em juízo e o magistrado e as partes

### Referências legais
- Art. 279 do CPP
- Art. 280 do CPP
- Art. 281 do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre perito e intérprete
- Conhecer a restrição para pessoas com interdição ou menores de idade funcionar como perito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.400 (1)", "page_number": 400, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 279 do CPP", "Art. 280 do CPP", "Art. 281 do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:04:07.324661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=400", "doc_key": "2d2ecb592bbe5efb7704036d027b8ecd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '153c9be9fe4afb5d4e012a1dd8d27d79503a927b3f19dc2bea39e6de19542c9f'),
  ('cpiuris2025::51cb17b52fa9d0eb5f1093c32e0d77fd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução Coercitiva de Peritos', '## Condução Coercitiva de Peritos

O artigo 278 do CPP estabelece a possibilidade de condução coercitiva do perito em caso de não comparecimento, sem justa causa. Além disso, o artigo 279 lista as pessoas que não podem funcionar como perito.

### Conceitos
- **Condução Coercitiva**: Ato compulsório para que alguém compareça a um local ou cumpra uma determinação
- **Perito**: Especialista em área específica, designado para realizar exames periciais
- **Art. 278 do CPP**: Disposição que permite a condução coercitiva do perito em caso de não comparecimento sem justa causa
- **Art. 279 do CPP**: Listagem de pessoas que não podem funcionar como perito
- **Justa Causa**: Motivo legítimo para o não comparecimento do perito

### Referências legais
- Art. 160, parágrafo único, do CPP
- Art. 277 do CPP
- Art. 278 do CPP
- Art. 279 do CPP

### Dicas de prova
- Entenda a distinção entre não comparecimento com justa causa e sem justa causa
- Conheça as exceções ao prazo máximo de 10 dias para elaboração do laudo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.399 (2)", "page_number": 399, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 160, parágrafo único, do CPP", "Art. 277 do CPP", "Art. 278 do CPP", "Art. 279 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:04:31.463985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=399", "doc_key": "51cb17b52fa9d0eb5f1093c32e0d77fd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '173406c9c1edb195bbd5049bc9a98030cf97c5dd0666d1a3b805ba72fc9ace16'),
  ('cpiuris2025::4a60e6f98fa6a4588d69f4135045c64c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hipótese de deferimento de assistência à acusação e intervenção dos pais como assistentes da acusação', '## Hipótese de deferimento de assistência à acusação e intervenção dos pais como assistentes da acusação

Discute a possibilidade de intervenção dos pais como assistentes da acusação em casos de homicídio, com legítima defesa ou sem ela.

### Conceitos
- **Hipótese de deferimento de assistência à acusação**: Princípio que permite a intervenção do Ministério Público em casos específicos
- **Assistentes da acusação**: Partes que apoiam o Ministério Público na investigação e processamento de um caso
- **Legítima defesa**: Direito que permite a autodefesa em situações de perigo iminente

### Referências legais
- Art. 8.625/93

### Jurisprudência
- RE 123456
- INF 644 - HC 98.841/PA, rel. Min. Gilmar Mendes, 11/10/2011
- INF 574 - RMS 43.227-PE, Rel. Min. Gurgel de Faria, julgado em 3/11/2015, DJe 7/12/2015
- INF 560 - RMS 47.575-SP, Rel. Min. Maria Thereza de Assis

### Dicas de prova
- Distinção entre legítima defesa e hipótese de deferimento de assistência à acusação
- Reconhecimento da ausência de direito líquido e certo de intervenção como assistente do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.400 (2)", "page_number": 400, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 8.625/93"], "jurisprudence": ["RE 123456", "INF 644 - HC 98.841/PA, rel. Min. Gilmar Mendes, 11/10/2011", "INF 574 - RMS 43.227-PE, Rel. Min. Gurgel de Faria, julgado em 3/11/2015, DJe 7/12/2015", "INF 560 - RMS 47.575-SP, Rel. Min. Maria Thereza de Assis"], "confidence": 0.8, "extracted_at": "2026-05-29T05:05:15.472834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=400", "doc_key": "4a60e6f98fa6a4588d69f4135045c64c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e29e7066021f92e07989fff8c14f02d2e284210c7dc870098cc1faebe9d95eb5'),
  ('cpiuris2025::33036b4318ccad03ae3cd68a0e6f2e0f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nomeação do Núcleo de Prática Jurídica em Juízo e Procuração', '## Nomeação do Núcleo de Prática Jurídica em Juízo e Procuração

A nomeação judicial de Núcleo de Prática Jurídica dispensa a juntada de procuração, pois não há atuação provocada pelo assistido, mas sim exercício do munus público por determinação judicial.

### Conceitos
- **Núcleo de Prática Jurídica**: Entidade que patrocina a defesa de réu em juízo
- **Procuração**: Instrumento que autoriza alguém a agir em nome de outro
- **Defensoria Pública**: Instituição pública que assiste réus hipossuficientes
- **Munus público**: Exercício do poder pelo Estado

### Referências legais
- Art. 135, § 3º, inciso IV, Código de Processo Civil
- Súmula 115/STJ

### Jurisprudência
- RE 624 - EAREsp 798.496-DF
- INF 624

### Dicas de prova
- Entenda a diferença entre defensor dativo e defensor nomeado
- Conheça o princípio da confiança e sua aplicação no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 135, § 3º, inciso IV, Código de Processo Civil", "Súmula 115/STJ"], "jurisprudence": ["RE 624 - EAREsp 798.496-DF", "INF 624"], "confidence": 0.8, "extracted_at": "2026-05-29T05:06:28.299651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=401", "doc_key": "33036b4318ccad03ae3cd68a0e6f2e0f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '675e89de03a3fbf107886fce2243c07ed37979a12242bc6276dce89a4fb091a1'),
  ('cpiuris2025::3095d9503218ddf00a720d7a10b0bfe2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intervenção do ofendido no processo penal', '## Intervenção do ofendido no processo penal

Resumo sobre a intervenção do ofendido no processo penal, incluindo a ação pública subsidiária e as limitações da intervenção do MP.

### Conceitos
- **Ação pública subsidiária**: Ação penal privada movida pelo ofendido que depende da ação pública para proceder.
- **Intervenção do MP**: O Ministério Público não intervém na ação pública subsidiária.
- **Impedimento e suspeição do juiz**: As causas de impedimento e suspeição do juiz também afetam os membros do MP.
- **Pessoas jurídicas no polo passivo**: As pessoas jurídicas não podem figurar no polo passivo da relação processual penal.
- **Intervenção do ofendido**: O ofendido ou seu representante legal pode intervir no processo como assistente do MP.

### Referências legais
- Art. 82, § 2º, do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação pública subsidiária e intervenção do ofendido.
- Conheça as limitações da intervenção do MP no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.401 (2)", "page_number": 401, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 82, § 2º, do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:06:54.885149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=401", "doc_key": "3095d9503218ddf00a720d7a10b0bfe2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '322d74e10effcfe5024346d0321fdd06e2000eb8acabf9a8e4f1fea57ab6102c'),
  ('cpiuris2025::89f7bd31afd0ea3dddba6c86bf45a550', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sujeitos processuais e assistente do Ministério Público', '## Sujeitos processuais e assistente do Ministério Público

O texto destaca a definição dos sujeitos processuais principais (juiz, acusador e acusado) e secundários (advogado, terceiro prejudicado e fiador), bem como a figura do assistente do Ministério Público.

### Conceitos
- **Sujeito processual**: Parte que tem direito de agir ou ser atingida no processo
- **Assistente do Ministério Público**: Figura processual que representa o Ministério Público em determinadas fases do processo

### Referências legais
- Art. 29 do CPP
- Art. 258 do CPP
- Art. 269 do CPP

### Dicas de prova
- Entenda a definição de sujeito processual e assistente do Ministério Público.
- Conheça as prescrições relativas à suspeição e aos impedimentos dos juízes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.402", "page_number": 402, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 29 do CPP", "Art. 258 do CPP", "Art. 269 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:07:28.066622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=402", "doc_key": "89f7bd31afd0ea3dddba6c86bf45a550"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e7b08fd485c7dce501760c166ad03e13049cc7544a9e2fa5eba6a040546f0cbf'),
  ('cpiuris2025::7a8a711e9f5ce4bb619c6331b083319a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Assistente do Ministério Público e Prisão Temporária', '## Assistente do Ministério Público e Prisão Temporária

Resumo sobre a prisão temporária, assistente do Ministério Público e suas regras.

### Conceitos
- **Prisão Temporária**: Decretada pelo Juiz, com prazo de 5 dias, prorrogável em caso de extrema necessidade.
- **Assistente do Ministério Público**: Ente que representa o Ministério Público no processo penal
- **Recurso contra a decisão do assistente do Ministério Público**: Não cabe, mas é possível o manejo do mandado de segurança.

### Referências legais
- Art. 269 do CPP
- Art. 271, §2º, CPP
- Art. 273 do CPP
- Art. 4º, §6º da Lei n.º 12.850/13

### Jurisprudência
- HC 194.677 – SP
- ...

### Dicas de prova
- Distinção entre a prisão temporária e a prisão preventiva.
- Regras para o assistente do Ministério Público
- Limites da intervenção do Poder Judiciário no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.403", "page_number": 403, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 269 do CPP", "Art. 271, §2º, CPP", "Art. 273 do CPP", "Art. 4º, §6º da Lei n.º 12.850/13"], "jurisprudence": ["HC 194.677 – SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:08:50.464944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=403", "doc_key": "7a8a711e9f5ce4bb619c6331b083319a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '43a49ce4754b7115349d5f82d912b519fa2d4bf0ae2cad4443bf89f99f1e483e'),
  ('cpiuris2025::3beceefdc24ff5b80855eb3e610bf1b7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Receio de fuga ou perigo à integridade física própria ou alheia', '## Receio de fuga ou perigo à integridade física própria ou alheia

Excepcionalidade para justificar o uso de algemas, com responsabilidade disciplinar e penal para agente ou autoridade.

### Conceitos
- **Excepcionalidade**: Condição que justifica a excepcionalidade do uso de algemas
- **Responsabilidade disciplinar**: Pena imposta ao agente ou autoridade por não cumprir com as normas de segurança
- **Penal**: Condenação do agente ou autoridade por não cumprir com as normas de segurança

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a excepcionalidade e suas implicações
- Conheça as hipóteses que autorizam o uso de algemas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.405 (2)", "page_number": 405, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:09:07.425971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=405", "doc_key": "3beceefdc24ff5b80855eb3e610bf1b7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '76608c3543b374f267ba89c5ab18764cf30dceeeac21f82d2bb689645ddfd09d'),
  ('cpiuris2025::de1df326e178391dc939da8bbaf87960', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar é um direito fundamental que visa impedir prisões ilegais ou arbitrárias, protegendo a integridade física e moral dos presos. O Estado é responsável por ressarcir os danos causados aos detentos em decorrência de falta ou insuficiência das condições legais de encarceramento.

### Conceitos
- **Tutela Cautelar**: direito fundamental que visa impedir prisões ilegais ou arbitrárias
- **Direitos Humanos**: regras fundamentais estabelecidas pela Constituição e tratados internacionais para proteger a liberdade de locomoção
- **Respeito à Integridade Física e Moral**: garantia constitucional que abrange a indevida exposição do preso à mídia e o uso excepcional de algemas

### Referências legais
- Art. 5º, XLIX, da CF/88

### Jurisprudência
- RE 580252/MS
- STF. Plenário. RE 841526/RS
- Súmula Vinculante 11: Só é lícito o uso de algemas em casos de resistência e de fundado risco para a segurança dos agentes

### Dicas de prova
- Entenda a tutela cautelar como um direito fundamental que visa proteger a liberdade de locomoção
