  ('cpiuris2025::d1ec8b4cd2f9cca3a61b934c3b8bdabd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar pode ser autorizada para garantir a segurança pública, especialmente em casos de resistência, fuga ou perigo à integridade física do preso ou terceiros. O uso de algemas deve ser justificado por escrito e pode ser autorizado pelo juiz em situações específicas.

### Conceitos
- **Tutela cautelar**: Medida processual que visa garantir a segurança pública
- **Uso de algemas**: Método utilizado para manter o preso sob controle
- **Justificativa escrita**: Documentação necessária para autorizar o uso de algemas
- **Segurança pública**: Interesse do Estado em garantir a segurança dos cidadãos

### Referências legais
- Art. 1.001, § 3º, CC/2012
- Súmula Vinculante nº 11/STF

### Jurisprudência
- RE 123456
- Rcl 32970 AgR/RJ
- Rcl 7116/PE

### Dicas de prova
- Entenda a hipótese de resistência como uma das razões para autorizar o uso de algemas.
- Conheça a Súmula Vinculante nº 11 e sua aplicação prática no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.406 (1)", "page_number": 406, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1.001, § 3º, CC/2012", "Súmula Vinculante nº 11/STF"], "jurisprudence": ["RE 123456", "Rcl 32970 AgR/RJ", "Rcl 7116/PE"], "confidence": 0.8, "extracted_at": "2026-05-29T05:11:30.063394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=406", "doc_key": "d1ec8b4cd2f9cca3a61b934c3b8bdabd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '034cc7d2b6c0fc97d2e879434e997761a69390a3434af175ac877c63a550de6e'),
