- **Dignidade da pessoa humana**: direito fundamental que protege a dignidade e os direitos humanos
- **Tratamento desumano e degradante**: prática que viola os direitos humanos e a dignidade da pessoa
- **Resolução nº 2010/16**: resolução das Nações Unidas sobre o tratamento de indivíduos em situação de vulnerabilidade
- **Submissão ao tratamento desumano e degradante**: prática que viola os direitos humanos e a dignidade da pessoa

