Regras para o emprego de algemas em mulheres presas, incluindo a vedação do uso em situações específicas e a comunicação imediata à família do preso.

### Conceitos
- **Algemas**: Instrumentos utilizados para restringir a liberdade de um preso
- **Resistência**: Ação do preso que pode justificar o emprego de algemas
- **Fuga**: Ação do preso que pode justificar o emprego de algemas
- **Perigo à integridade física**: Risco de dano ao próprio corpo ou a terceiros
- **Tratamento humanitário dos presos**: Princípio que determina o tratamento digno e respeitoso aos presos
- **Vulnerabilidade**: Condição de fragilidade ou suscetibilidade de um indivíduo
- **Comunicação imediata ao juiz competente**: Obrigação de comunicar a localização do preso ao juiz competente
- **Direito à assistência da família**: Direito do preso de receber apoio e assistência de sua família

