  ('cpiuris2025::83d98f527e1da0e01352bd02159cb40d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direitos do Preso em Prisão', '## Direitos do Preso em Prisão

O art. 306, §1º, do CPP determina que o autuado não informe o nome do seu advogado e será remetida cópia integral do auto de prisão para a Defensoria Pública. Em caso de não haver Defensoria, é necessária a nomeação de defensor dativo.

### Conceitos
- **Defensoria Pública**: instituição que representa os presos sem recursos financeiros
- **nome do advogado**: informação obrigatória para o autuado
- **prisão em flagrante**: tipo de prisão que não requer a nomeação de defensor dativo
- **autuado**: parte que sofre a prisão
- **mandado**: instrumento que determina a prisão
- **prisão ilegal**: prisão que não é autorizada pela lei
- **relaxamento da prisão**: anulação da prisão ilegal

### Referências legais
- Art. 5º, LXIII, da CF/88
- Art. 306, §1º, do CPP
- Art. 263 do CPP

### Dicas de prova
- Entenda a importância da Defensoria Pública no contexto de prisão.
