O fumus boni iuris é a aparência do bom direito, com probabilidade de plausibilidade do direito requerido pela parte. O periculum in mora é o perigo da demora do processo que põe em risco sua eficácia.

### Conceitos
- **Fumus boni iuris**: Aparência do bom direito, probabilidade de plausibilidade do direito requerido pela parte
- **Periculum in mora**: Perigo da demora do processo que põe em risco sua eficácia

### Referências legais
- Art. 2º, inciso II, do Código de Processo Penal
- Súmula 279/STF

