  ('cpiuris2025::959fd636bb674d384eb33f2e4a31acff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

Medidas cautelares em processos penais têm como objetivo evitar práticas de infrações penais, garantir a aplicação da lei penal e proteger o patrimônio e a liberdade do imputado.

### Conceitos
- **Periculum in mora**: Risco de dilapidação do patrimônio pelo sujeito
- **Periculum libertatis**: Risco criado pela liberdade do agente
- **Princípio da proporcionalidade**: Medida que deve ser escolhida como a menos gravosa ao agente, preservando a sua liberdade de locomoção

### Referências legais
- Art. 282 do CPP
- Art. 312 do CPP
- Lei nº 13.964/2019

### Jurisprudência
- ADI 7.496/GO
- STF julgou inconstitucional norma de Constituição Estadual

### Dicas de prova
