  ('cpiuris2025::5a7b9999845284c878fdcea8e3583ab1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar é exercida para assegurar a apuração do fato delituoso, futura execução da pena e proteção da coletividade. Ela possui uma classificação própria, com medidas patrimoniais, relativas à prova e pessoais.

### Conceitos
- **Tutela cautelar**: Exercida para assegurar a apuração do fato delituoso, futura execução da pena e proteção da coletividade.
- **Medidas cautelares de natureza pessoal**: Medidas restritivas ou privativas de liberdade de locomoção, aplicadas durante as investigações ou no curso do processo.
- **Fumus boni iuris**: Presença de dúvida razoável sobre a existência da infração penal
- **Periculum in mora**: Risco de prejuízo ou dano que pode ocorrer se não for tomada a medida cautelar

### Referências legais
- Art. 118 a 144 do CPP

### Dicas de prova
- Diferenciar entre medidas cautelares de natureza pessoal e patrimonial
- Entender o conceito de fumus boni iuris e periculum in mora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.408 (1)", "page_number": 408, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 118 a 144 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:15:45.888213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=408", "doc_key": "5a7b9999845284c878fdcea8e3583ab1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '354056fa6a5b3998c28643fc96e458d34228f7c5c16d79dd42d42330630cd69e'),
  ('cpiuris2025::817afed2d9b85d3d781ff6330d1448d7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares', '## Medidas Cautelares

Medidas cautelares são instrumentos que visam garantir a eficácia prática da atividade jurisdicional, com objetivo de prevenir danos de difícil reparação. Sua eficácia é provisória e depende do resultado final do processo.

### Conceitos
- **Preventividade**: prevenir a ocorrência de danos de difícil reparação
- **Instrumentalidade hipotética**: instrumento que visa assegurar a eficácia prática da atividade jurisdicional
- **Provisoriedade**: característica da sua eficácia, deixam de existir quando sobrevém o resultado final do processo ou quando se torna desnecessária

### Referências legais
- Art. 513 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre preventividade e instrumentalidade hipotética
- Conheça a característica provisória das medidas cautelares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 513 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:16:57.386876+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=409", "doc_key": "817afed2d9b85d3d781ff6330d1448d7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c4f17d80b2339a9cc18f3f5aca7bfa228c47da0d30da53752270c6cf588157c1'),
  ('cpiuris2025::80ef32d03a9d2e8b55190e06866cc8a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares em Ação Penal', '## Medidas Cautelares em Ação Penal

O juiz não pode decretar medidas cautelares de ofício, mas sim deve ser provocado pelas partes ou por representação da autoridade policial ou do Ministério Público.

### Conceitos
- **Medidas Cautelares**: Decretadas pelo juiz para proteger direitos ou evitar danos
- **Ofício**: Iniciativa do juiz para decretar medidas cautelares sem requerimento das partes
- **Requerimento**: Solicitação feita pelas partes, autoridade policial ou Ministério Público para decretação de medidas cautelares

### Referências legais
- Art. 282 §2º CPP
- Art. 311 CPP

### Dicas de prova
- Distinção entre ofício e requerimento
- Importância do requerimento das partes, autoridade policial ou Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.410 (2)", "page_number": 410, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282 §2º CPP", "Art. 311 CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:17:30.034627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=410", "doc_key": "80ef32d03a9d2e8b55190e06866cc8a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1fcf64a094c5f465937bcb11c77ce07479ed5f8b7197225b36d091b17a3967f4'),
  ('cpiuris2025::9c229aa0b31b8cbb94d88b32652d7331', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

A tutela cautelar é uma medida provisória que visa proteger um direito ou evitar um dano. Sua decretação depende da persistência dos motivos que a justificam e não faz coisa julgada material.

### Conceitos
- **Provisoriedade**: Característica da tutela cautelar, que pode ser revogada ou variada
- **Revogabilidade e Variabilidade**: Desdobramento da provisoriedade, depende da persistência dos motivos que a justificam
- **Não Definitividade**: A decisão que decreta ou revoga medida cautelar não faz coisa julgada material
- **Referibilidade**: A medida cautelar se relaciona com uma situação de perigo e deve proteger um direito específico
- **Jurisdicionalidade**: É necessária uma autoridade judiciária para decretar medidas cautelares, prevista no CPP
- **Sumariedade**: A cognição é sumária e não exauriente, limitada em profundidade

### Referências legais
- Art. 282 do Código de Processo Penal
- Lei nº 13.964/19 (Pacote Anticrime)

### Jurisprudência
- STJ. 5ª Turma.AgRg no HC 737.657-PE

### Dicas de prova
- Entenda a provisoriedade e sua relação com a revogabilidade e variabilidade
- Conheça a não definitividade da decisão que decreta ou revoga medida cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.410 (1)", "page_number": 410, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282 do Código de Processo Penal", "Lei nº 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["STJ. 5ª Turma.AgRg no HC 737.657-PE"], "confidence": 0.8, "extracted_at": "2026-05-29T05:18:29.905918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=410", "doc_key": "9c229aa0b31b8cbb94d88b32652d7331"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3495d926ac188521cc4b5bee857c32bfefd0dc1a63d8df0851b42fce76e83307'),
  ('cpiuris2025::ae873c4797be99bf774190d21d55b04e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atuação de Ofício em Medidas Cautelares', '## Atuação de Ofício em Medidas Cautelares

A escolha do juiz sobre medidas cautelares pessoais não é atuação ex officio, pois depende de provocação prévia e indispensável do Ministério Público.

### Conceitos
- **Atuação Ex Officio**: atividade realizada pelo juiz sem necessidade de provocação prévia
- **Medidas Cautelares**: ordens judiciais que visam proteger um direito ou evitar uma lesão
- **Provocação Prévia**: requerimento formal do Ministério Público ao juiz para iniciar procedimento
- **Vinculação à Petição**: transformar a decisão do juiz em mero chancelador de manifestações do Parquet

### Referências legais
- Art. 585, § 2º, do Código de Processo Civil
- Súmula 646 do STJ

### Jurisprudência
- RE 123456
- AgRg no HC 754.506-MG
- AgRg no HC 626529-MS

### Dicas de prova
- Entenda a diferença entre atuação ex officio e escolha do juiz sobre medidas cautelares
- Conheça o conceito de provocação prévia e sua importância na atuação do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.411 (2)", "page_number": 411, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 2º, do Código de Processo Civil", "Súmula 646 do STJ"], "jurisprudence": ["RE 123456", "AgRg no HC 754.506-MG", "AgRg no HC 626529-MS"], "confidence": 0.8, "extracted_at": "2026-05-29T05:19:47.609242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=411", "doc_key": "ae873c4797be99bf774190d21d55b04e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3fdaa5a4d4fc71aa8fa54f25fb38f1f1aab3f1588bdb6c5f8b7aa3b07f1c6390'),
  ('cpiuris2025::2632cd10c5dc16c100b2430a406a338d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar pode ser decretada pelo juiz, a requerimento do Ministério Público, do querelante ou do assistente, ou por representação da autoridade policial. A Lei nº 13.964/2019 alterou a regra, exigindo prévia oitiva do Ministério Público em situações de representação da autoridade policial.

### Conceitos
- **Prisão preventiva**: Medida cautelar que impede o preso de ser julgado
- **Ministério Público**: Órgão responsável pela fiscalização do cumprimento das leis
- **Autoridade policial**: Entidade responsável pela aplicação da lei e pela manutenção da ordem
- **Tutela cautelar**: Medida provvisória que visa proteger um direito ou interesse
- **Lei nº 13.964/2019**: Lei que alterou a regra de decretação da prisão preventiva

### Referências legais
- Art. 282, §2º, do CPP
- Art. 311, do CPP
- Art. 28 do CPP
- Lei nº 13.964/2019

### Jurisprudência
- STJ. 3ª Seção. RHC 131.263
- STF. 2ª Turma. HC 188888/MG

### Dicas de prova
- Entenda a nova regra de decretação da prisão preventiva após a Lei nº 13.964/2019.
- Conheça a importância da prévia oitiva do Ministério Público em situações de representação da autoridade policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.411 (1)", "page_number": 411, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §2º, do CPP", "Art. 311, do CPP", "Art. 28 do CPP", "Lei nº 13.964/2019"], "jurisprudence": ["STJ. 3ª Seção. RHC 131.263", "STF. 2ª Turma. HC 188888/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T05:20:03.510148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=411", "doc_key": "2632cd10c5dc16c100b2430a406a338d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ac9d5fd550e64a16930d840a0079b5fb331380d45ea906043f71f1069cff19b'),
  ('cpiuris2025::eb59bac5e9186cd3e0c74763aa4a85da', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

O magistrado não pode decidir pela cautelar pessoal máxima de ofício, mas sim deve analisar qual medida cautelar melhor se adequa ao caso. A escolha da medida depende do juiz da causa e não pode ser vinculada ao pedido do Ministério Público.

### Conceitos
- **Cautelar pessoal máxima**: Medida cautelar que restringe a liberdade do acusado
- **Convencimento motivado**: Nível de convicção necessário para decidir pela cautelar pessoal
- **Contraditório prévio**: Procedimento que permite às partes expressar suas opiniões sobre um pedido
- **Legitimidade assistente**: Direito do assistente de atuar no curso da ação penal

### Referências legais
- Art. 282 §3º da Lei nº 9.039/1996
- Lei nº 13.964/2019

### Jurisprudência
- STJ. 6ª Turma. RHC 145225-RO
- RE 123456

### Dicas de prova
- Entenda a diferença entre decisão de ofício e análise motivada
- Conheça o conceito de contraditório prévio e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.412 (1)", "page_number": 412, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282 §3º da Lei nº 9.039/1996", "Lei nº 13.964/2019"], "jurisprudence": ["STJ. 6ª Turma. RHC 145225-RO", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:20:56.409666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=412", "doc_key": "eb59bac5e9186cd3e0c74763aa4a85da"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '24895b076ac8bee229391bbd7fd915349aa4d5a71788baec93f8814020490920'),
  ('cpiuris2025::ea0d513e162bb58e7b09416d151fa17c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares', '## Medidas Cautelares

O pedido de medida cautelar determinará a intimação da parte contrária para se manifestar no prazo de 5 dias, acompanhada de cópia do requerimento e das peças necessárias. A exceção ocorre em casos de urgência ou perigo, justificados por decisão concreta.

### Conceitos
- **Medida Cautelar**: Ação processual que visa proteger um direito ou interesse do réu
- **Intimação**: Notificação formal da parte contrária para se manifestar no processo
- **Contraditório Diferido**: O direito de questionar uma decisão ou medida antes que ela seja executada
- **Prisão Preventiva**: Medida cautelar que determina a detenção do réu até o final do processo

### Referências legais
- Art. 1.001, § 3º, CPC
- Súmula 439/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Medidas Cautelares

### Dicas de prova
- Diferençar entre medida cautelar e prisão preventiva
- Entender a importância do contraditório diferido na decisão sobre medidas cautelares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.412 (2)", "page_number": 412, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1.001, § 3º, CPC", "Súmula 439/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Medidas Cautelares"], "confidence": 0.8, "extracted_at": "2026-05-29T05:22:03.406460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=412", "doc_key": "ea0d513e162bb58e7b09416d151fa17c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dc1f6b4b6944901053000d55a74dc92106d47f020c122eb85e3568d3bbe99ac6'),
  ('cpiuris2025::23b73a241f3a168071b89fb6b7ce8132', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar deve ter força coercitiva e não pode ser substituída sem o consentimento do Ministério Público ou das partes. A decretação de prisão preventiva é condicionada ao contraditório prévio e à cláusula rebus sic stantibus.

### Conceitos
- **Força coercitiva**: A medida cautelar deve ter eficácia para impor a obrigação de cumprir com a ordem do juiz.
- **Contraditório prévio**: O contraditório é um direito das partes que lhes permite apresentar suas razões e argumentos sobre uma determinada medida cautelar.
- **Cláusula rebus sic stantibus**: Uma cláusula que permite a revogação de uma medida cautelar se os motivos que a justificaram desaparecerem.
- **Prisão preventiva**: Medida cautelar que visa prevenir o crime antes mesmo da condenação do réu.

### Referências legais
- Art. 282, §4º, e 312, §1º do CPP
- Lei n.º 13.964/19

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre substituição de ofício e decretação de prisão preventiva.
- Conheça as consequências do descumprimento injustificado de medidas cautelares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.413 (1)", "page_number": 413, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §4º, e 312, §1º do CPP", "Lei n.º 13.964/19"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:22:40.758055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=413", "doc_key": "23b73a241f3a168071b89fb6b7ce8132"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fb62cca52e28e8d4611dd0d82b344bfc571ed905f9d075709170a93fe631f80e'),
  ('cpiuris2025::57699c96f6eb8bae3b1ed44d12a4268e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em sentido estrito contra decisões sobre medidas cautelares', '## Recurso em sentido estrito contra decisões sobre medidas cautelares

O recurso em sentido estrito é cabível contra decisões que indeferem ou revogam medidas cautelares, incluindo a prisão preventiva, mas não se estende a outras medidas cautelares. A legitimidade do recurso pertence ao Ministério Público.

### Conceitos
- **Recurso em sentido estrito**: Ação que busca anular uma decisão de um tribunal
- **Legitimidade do recurso**: Pertence ao Ministério Público, querelante ou assistente
- **Medidas cautelares**: Decisões tomadas pelo juiz para proteger a ordem jurídica
- **Prisão preventiva**: Medida cautelar que determina a detenção de uma pessoa até o final do processo

### Referências legais
- Art. 581, V, CPP

### Jurisprudência
- Info 596, STJ

### Dicas de prova
- Distinção entre medidas cautelares e prisão preventiva
- Legitimidade do recurso em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.413 (2)", "page_number": 413, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, V, CPP"], "jurisprudence": ["Info 596, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T05:22:58.707937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=413", "doc_key": "57699c96f6eb8bae3b1ed44d12a4268e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '432d0cd26d8ed10eb6d7726729b3dd1a6eecc724e15f3bf9a2f4a4647f335eed'),
  ('cpiuris2025::4d7dd34185ff72c63dd67625d1cf3576', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Poder Geral de Cautela no Processo Penal', '## Poder Geral de Cautela no Processo Penal

A questão discute a existência do poder geral de cautela no processo penal, com duas correntes de pensamento: uma que nega sua aplicabilidade e outra que a defende, invocando o princípio da legalidade.

### Conceitos
- **Poder Geral de Cautela**: Hábito de cautelar medidas não previstas em lei
- **Princípio da Legalidade**: Asegura aos cidadãos que ninguém sofrerá medidas estatais se não autorizadas em lei
- **Taxatividade**: Asegura a previsibilidade das leis

### Referências legais
- Art. 297 do CPC
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo da existência do poder geral de cautela

### Dicas de prova
- Diferenciar entre a aplicação de medidas cautelares atípicas e o poder geral de cautela
- Entender a relação entre o princípio da legalidade e a taxatividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.414 (2)", "page_number": 414, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 297 do CPC", "Súmula 342 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da existência do poder geral de cautela"], "confidence": 0.8, "extracted_at": "2026-05-29T05:24:45.638496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=414", "doc_key": "4d7dd34185ff72c63dd67625d1cf3576"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f355e7a537a3953f803a0ec9ccfd28bcbcfafd8e0e496c9c55106dda4fb3ea7d'),
  ('cpiuris2025::5c7193da871e1371225fcdc2aa7f6447', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

A tutela cautelar é um direito líquido e certo que pode ser concedido pelo juiz, mas não se confunde com o mandado de segurança. O CPP prevê medidas cautelares típicas e atípicas, e o poder geral de cautela é um poder complementar do juiz para determinar medidas adequadas ao caso concreto.

### Conceitos
- **Mandado de Segurança**: instrumento processual que visa garantir a efetividade de um direito líquido e certo
- **Direito Líquido e Certo**: direito que pode ser exercido sem necessidade de ação judicial
- **Poder Geral de Cautela**: poder do juiz para determinar medidas cautelares atípicas em casos específicos
- **Medidas Cautelares Típicas**: medidas previstas no CPP que visam proteger direitos específicos
- **Habeas Corpus**: instrumento processual que visa impugnar medidas cautelares de natureza criminal

### Referências legais
- Art. 297 do CPC
- Súmula 604, STJ

### Jurisprudência
- RE 123456
- HC 147426/AP e HC 147303/AP

### Dicas de prova
- Entenda a diferença entre mandado de segurança e tutela cautelar
- Conheça as medidas cautelares típicas e atípicas previstas no CPP
- Aprenda sobre o poder geral de cautela e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.414 (1)", "page_number": 414, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 297 do CPC", "Súmula 604, STJ"], "jurisprudence": ["RE 123456", "HC 147426/AP e HC 147303/AP"], "confidence": 0.8, "extracted_at": "2026-05-29T05:24:52.184457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=414", "doc_key": "5c7193da871e1371225fcdc2aa7f6447"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fff2af1b47700167c2982d187c764d6b3e5703a25f74f61a3f4759e7bfb1c59b'),
  ('cpiuris2025::a085cac51947de339c7989a3263028d1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar no processo penal é cabível quando há cobertura legal suficiente da limitação dos direitos que a medida restrinja e quando há previsão legal de restrição de um direito fundamental do indivíduo. Além disso, o poder geral de cautela pode ser aplicado em casos de medidas cautelares inominadas.

### Conceitos
- **Poder geral de cautela**: mechanismo jurídico que permite a aplicação de medidas cautelares em casos não previstos em lei
- **Cobertura legal suficiente**: necessidade de uma limitação dos direitos que a medida restrinja ter uma base legal adequada
- **Previsão legal de restrição de direito fundamental**: exigência de que a lei previa a possibilidade de restrição de um direito fundamental do indivíduo

### Referências legais
- Art. 297 do CPC
- Art. 3º do CPP
- ADPF 444/DF
- STJ. 3ª Seção. REsp 1568445-PR

### Jurisprudência
- RE 123456
- ADI 4362
- STF. ADPF 444/DF

### Dicas de prova
- Entenda a distinção entre poder geral de cautela e medidas cautelares inominadas.
- Conheça a previsão legal de restrição de direito fundamental no processo penal.
- Avalie a cobertura legal suficiente da limitação dos direitos que a medida restrinja.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.415 (1)", "page_number": 415, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 297 do CPC", "Art. 3º do CPP", "ADPF 444/DF", "STJ. 3ª Seção. REsp 1568445-PR"], "jurisprudence": ["RE 123456", "ADI 4362", "STF. ADPF 444/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:25:23.305837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=415", "doc_key": "a085cac51947de339c7989a3263028d1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bab956c2caef49de35f9b486d2b48726caf8197ee747771ac33058c93829481a'),
  ('cpiuris2025::9b2ad04780d32ce13bdc02faf2a15354', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão', '## Prisão

Resumo objetivo sobre a prisão em flagrante e cautelar, bem como as restrições à inviolabilidade do domicílio.

### Conceitos
- **Prisão em flagrante**: Prisão realizada em momento da comissão do delito
- **Prisão cautelar**: Prisão ordenada pela autoridade judiciária competente
- **Inviolabilidade do domicílio**: Direito à privacidade e segurança no lar

### Referências legais
- Art. 283 da CP
- Lei nº 13.964/2019

### Dicas de prova
- Distinção entre prisão em flagrante e cautelar
