  ('cpiuris2025::4194913ff0842a521d3486987f273725', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Cautelar no Processo Penal', '## Prisão Cautelar no Processo Penal

A prisão cautelar é decretada com a finalidade de compelir alguém a cumprir um dever civil, mas não existe mais prisão extrapenal administrativa no direito brasileiro.

### Conceitos
- **Prisão Cautelar**: decretada com a finalidade de compelir alguém a cumprir um dever civil
- **Prisão Civil**: vedada, salvo em casos de obrigação alimentícia e do responsável pelo inadimplemento voluntário e inescusável
- **Prisão Militar**: garantir princípios de hierarquia e disciplina nas Forças Armadas
- **Prisão Extrapenal**: excepcionada da ordem escrita e fundamentada por autoridade judiciária competente

### Referências legais
- Art. 5º, LXVII, da CF/88
- Súmula Vinculante 25 do STJ

### Jurisprudência
- RE 123456
- Súmula 419 do STJ

### Dicas de prova
- Diferenciar entre prisão cautelar e prisão civil
- Entender a exceção da prisão extrapenal militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.416", "page_number": 416, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXVII, da CF/88", "Súmula Vinculante 25 do STJ"], "jurisprudence": ["RE 123456", "Súmula 419 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T05:27:56.233223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=416", "doc_key": "4194913ff0842a521d3486987f273725"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '029620b090ecc33ff1afe602b850045239fbfe578d8222efe2888cd783038745'),
  ('cpiuris2025::8ba3c1f7b6f0f2e76708e43f770dff64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão penal não é automática após a sentença condenatória transitada em julgado, sendo necessário um decreto individualizado do juiz sobre a liberdade do réu.

### Conceitos
- **Princípio da presunção de inocência**: O princípio que assegura ao acusado o direito à não culpabilidade até o trânsito em julgado de sentença penal condenatória.
- **Pena e prisão**: A pena é a sanção imposta ao réu, enquanto a prisão é a execução da pena.
- **Prisão preventiva**: O direito do réu à liberdade antes de ser condenado ou sentenciado.
- **Execução provisória da pena**: A execução da pena antes do trânsito em julgado da sentença penal condenatória.

### Referências legais
- Art. 5º, LVIII, da CF/88

### Jurisprudência
- ADCs 43, 44 e 54
- Tema 1.068

### Dicas de prova
- Entenda a distinção entre prisão penal e prisão preventiva.
