  ('cpiuris2025::9dc4be635d8a2d177cb91f14bfa1b2d5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Provisória de Pena no Júri', '## Execução Provisória de Pena no Júri

A Lei nº 13.964/19 autorizou a execução provisória de pena igual ou superior a 15 anos de reclusão no procedimento do júri, mas a STF decidiu que isso não viola o princípio da presunção de inocência ou da não culpabilidade.

### Conceitos
- **Execução Provisória**: execução imediata da condenação imposto pelo Júri
- **Pena no Júri**: pena aplicada pelo corpo de jurados
- **Princípio da Presunção de Inocência**: princípio que assegura à pessoa acusada a não ser culpada até o veredito do júri
- **Condenação pelo Júri**: condenação imposto pelo corpo de jurados

### Referências legais
- Art. 492, I, ''e'', do CPP
- Lei nº 13.964/19 (Pacote Anticrime)

### Jurisprudência
- RE 1.235.340/SC
- Tema 1068 – Info 1150

### Dicas de prova
- Entenda a diferença entre execução provisória e condenação pelo júri
- Reconheça o princípio da presunção de inocência e sua aplicação no caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.417 (2)", "page_number": 417, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 492, I, ''e'', do CPP", "Lei nº 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["RE 1.235.340/SC", "Tema 1068 – Info 1150"], "confidence": 0.8, "extracted_at": "2026-05-29T05:28:34.847090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=417", "doc_key": "9dc4be635d8a2d177cb91f14bfa1b2d5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9decbf7593988d9e23080ee48431418987f09b89c7e0b5050337fb6f24d77177'),
  ('cpiuris2025::69ea47a436ab89b69fdc5fd892dacd11', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão cautelar é medida excepcional para assegurar a eficácia do processo ou das investigações, somente permitida quando presentes todos os requisitos autorizadores.

### Conceitos
- **Prisão cautelar**: Medida excepcional para assegurar a eficácia do processo ou das investigações
- **Penas alternativas à prisão**: Substituição da prisão por outras medidas cautelares
- **Inviolabilidade do domicílio**: Direito do indivíduo a ter sua casa inviolável, com exceções específicas

### Referências legais
- Art. 282
- Art. 283
- Lei nº 13.964/2019

### Jurisprudência
- STJ. 5ª Turma. AgRg no HC 714884-SP
- STF. Tem 1.068

### Dicas de prova
- Entenda a distinção entre prisão cautelar e prisão preventiva
- Conheça as exceções à inviolabilidade do domicílio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.418", "page_number": 418, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282", "Art. 283", "Lei nº 13.964/2019"], "jurisprudence": ["STJ. 5ª Turma. AgRg no HC 714884-SP", "STF. Tem 1.068"], "confidence": 0.8, "extracted_at": "2026-05-29T05:30:03.480335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=418", "doc_key": "69ea47a436ab89b69fdc5fd892dacd11"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '95331eb4975569ae99f4289be8b3c956841d0890ad732ac278afbcfac3ef3521'),
  ('cpiuris2025::92e7294376475744140fc4494ea2f0fa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Limitação da entrada em domicílio durante o dia', '## Limitação da entrada em domicílio durante o dia

A entrada em domicílio pode ser realizada apenas durante o dia, mas há controvérsia sobre a definição de ''dia''. O período entre a aurora e o pôr do sol é um critério, enquanto outros entendem como o período entre 6h e 18h. O consentimento do morador é sempre necessário, independentemente da hora.

### Conceitos
- **Limitação de entrada em domicílio**: A entrada em domicílio pode ser realizada apenas durante o dia
- **Definição de ''dia''**: Período entre a aurora e o pôr do sol ou período entre 6h e 18h
- **Consentimento do morador**: Necessário para qualquer entrada em domicílio, independentemente da hora

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre ''dia'' e ''noite''
- Importância do consentimento do morador
- Exceções ao princípio da limitação de entrada em domicílio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.419 (2)", "page_number": 419, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:30:37.946044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=419", "doc_key": "92e7294376475744140fc4494ea2f0fa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '63e909e81aab0bb6bda5a3353cc9bd988057e1e1d7b69356620f73c45d1a4f4b'),
  ('cpiuris2025::0a90f358f31e53a9341eae3e2d1a3f32', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar no processo penal é regulada pelo Código de Processo Penal, especificamente pelo artigo 150, §4º. O conceito de domicílio é mais amplo que o do Código Civil e deve ser utilizado para fins penais. A entrada forçada em domicílio sem consentimento do morador é lícita apenas quando amparada em fundadas razões justificadas a posteriori.

### Conceitos
- **Domicílio**: Conceito mais amplo que o do Código Civil, abrangendo qualquer compartimento habitado, aposento ocupado de habitação coletiva e compartimento não aberto ao público
- **Justa causa**: Fundadas razões justificadas a posteriori que sinalizam a ocorrência de crime no interior da residência
- **Tutela cautelar**: Medida processual que visa proteger um direito ou interesse, geralmente com caráter temporário e preventivo

### Referências legais
- Art. 150, §4º, do CP

### Jurisprudência
- STJ. 6ª Turma. REsp 1.574.681-RS
- STF. Plenário. RE 603616/RO

### Dicas de prova
- Entenda o conceito de domicílio e sua aplicação no processo penal
- Identifique a condição necessária para a entrada forçada em domicílio sem consentimento do morador
- Aprenda sobre a tutela cautelar e seu papel no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.419 (1)", "page_number": 419, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 150, §4º, do CP"], "jurisprudence": ["STJ. 6ª Turma. REsp 1.574.681-RS", "STF. Plenário. RE 603616/RO"], "confidence": 0.8, "extracted_at": "2026-05-29T05:31:12.156118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=419", "doc_key": "0a90f358f31e53a9341eae3e2d1a3f32"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3eddd86b461510261fc79fd43f367472b50d930f8bb17467f7c2cc26fc95e4fc'),
  ('cpiuris2025::0d7b3ddecbb102e532b51e4fd4234b7c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Imunidades prisionais', '## Imunidades prisionais

A regra é que toda pessoa pode ser presa, mas há exceções previstas na Constituição e no Código de Processo Penal, como a imunidade do Presidente da República, dos chefes de governo estrangeiros e de outros funcionários públicos.

### Conceitos
- **Imunidade prisional**: Prerrogativa que exime uma pessoa de ser presa por delito cometido no Brasil
- **Presidente da República**: O chefe do Estado brasileiro, isento de prisão cautelar e de responsabilidade por atos estranhos ao exercício das funções
- **Imunidade diplomática**: Prerrogativa que exime uma pessoa estrangeira de ser processada no Brasil por delitos cometidos no país de origem
- **Código de Processo Penal (CPP)**: Legislação que regula o processo penal no Brasil

### Referências legais
- Art. 86, §3º, da CF/88
- Art. 53, §2º, e 27, §1º, da CF/88
- §4º do CPP

### Jurisprudência
- Info 816
- Info 888

### Dicas de prova
- Entenda a diferença entre imunidade prisional e imunidade diplomática
- Conheça as exceções previstas na Constituição para a prisão de funcionários públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.420 (1)", "page_number": 420, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 86, §3º, da CF/88", "Art. 53, §2º, e 27, §1º, da CF/88", "§4º do CPP"], "jurisprudence": ["Info 816", "Info 888"], "confidence": 0.8, "extracted_at": "2026-05-29T05:32:44.289053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=420", "doc_key": "0d7b3ddecbb102e532b51e4fd4234b7c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5783cda8909dada2299dc61d59ad467819ccd6fa350eaaac6ba8afe0589be382'),
  ('cpiuris2025::938fbbb24e715bbdcc6eebac7264ecb6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Presença e Processo de Magistrados e Ministério Público', '## Presença e Processo de Magistrados e Ministério Público

Regra sobre a presença e processo de magistrados e membros do Ministério Público, incluindo a necessidade de ordem judicial escrita para prisão.

### Conceitos
- **Impeachment**: Processo que visa remover um juiz ou membro do Ministério Público da função
- **Flagrante**: Situação em que a infração é comprovada na própria ocasião do fato
- **Ordem judicial escrita**: Decisão do juiz que determina a prisão de uma pessoa
- **Presença de magistrados e membros do Ministério Público**: Regra que regula a presença dessas pessoas em locais públicos

### Referências legais
- Art. 33, I, da LOMAN
- Art. 40, III, da Lei n.º 8.625/93

### Jurisprudência
- STJ. 5ª Turma. RHC 88.804-RN
- RE 123456

### Dicas de prova
- Distinção entre flagrante e presença de magistrados e membros do Ministério Público
- Importância da ordem judicial escrita para prisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.420 (2)", "page_number": 420, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 33, I, da LOMAN", "Art. 40, III, da Lei n.º 8.625/93"], "jurisprudence": ["STJ. 5ª Turma. RHC 88.804-RN", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:32:54.285035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=420", "doc_key": "938fbbb24e715bbdcc6eebac7264ecb6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '03c87e2aa3f7263f3c74bafe2920baf319fe5e9ebf2b350fa7e920ff8ee170ba'),
  ('cpiuris2025::8ede9ff49ded2d52f122c72928f966b9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Magistrados e membros do Ministério Público estão sujeitos a prisões temporárias e preventivas, mas não à prisão em flagrante por crime afiançável. Defensores Públicos federais e estaduais não têm garantia de não serem presos senão por flagrante de crime inafiançável. Advogados podem ser presos em flagrante apenas por motivo ligado à profissão.

### Conceitos
- **Prisão cautelar**: Medida provisória para garantir a ordem pública e a segurança nacional
- **Prisão temporária**: Medida provisória que mantém o preso em cativeiro até a decisão final do processo
- **Prisão preventiva**: Medida provisória que mantém o preso em cativeiro para evitar a fuga ou perigo à ordem pública e à segurança nacional
- **Flagrante**: Ato de ser capturado no ato do crime
- **Crime afiançável**: Crime que não exige prisão em flagrante

### Referências legais
- Art. 44, II, da LC n.º 80/94
- Art. 89, II, da LC n.º 80/94
- Art. 128, II, da LC n.º 80/94

### Dicas de prova
- Diferencie entre prisão cautelar e prisão preventiva
- Entenda a noção de flagrante e crime afiançável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.421 (1)", "page_number": 421, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 44, II, da LC n.º 80/94", "Art. 89, II, da LC n.º 80/94", "Art. 128, II, da LC n.º 80/94"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:33:59.624821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=421", "doc_key": "8ede9ff49ded2d52f122c72928f966b9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6e7fa78803d18e7a68ec518846f930edeeca007da833b5dde620997db3681a2e'),
  ('cpiuris2025::09471e6723611fd07c93f9cd944592d9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pessoas que não estão sujeitas à prisão especial', '## Pessoas que não estão sujeitas à prisão especial

Lista de pessoas que não estão sujeitas à prisão especial, incluindo cidadãos inscritos no Livro de Mérito e magistrados.

### Conceitos
- **Prisão Special**: Condição em que uma pessoa não pode ser presa
- **Livro de Mérito**: Registro de cidadãos inscritos para exercer funções públicas
- **Magistrado**: Pessoa que exerce a função de juiz

### Referências legais
- Art. 2º, § 3º da Lei nº 7.210/82
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão Special

