- Entenda a definição de prisão especial e quem não está sujeito a ela
- Conheça o Livro de Mérito e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.421 (2)", "page_number": 421, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, § 3º da Lei nº 7.210/82", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão Special"], "confidence": 0.8, "extracted_at": "2026-05-29T05:34:35.638223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=421", "doc_key": "09471e6723611fd07c93f9cd944592d9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9e3f6fc06840f60103f8f030b3abe5a4c343264303b5315c9a27fa57cc2b2fb1'),
  ('cpiuris2025::994f4418f14a8a87aa130e0feb911626', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão especial é incompatível com a Constituição Federal por ofensa ao princípio da isonomia, exceto para pessoas com diploma de ensino superior. A sala de Estado Maior não confere garantia de prisão em um ambiente separado e equiparado à sala de Estado Maior.

### Conceitos
- **Prisão especial**: Condição que permite ao preso ter direitos diferentes do comum
- **Isonomia**: Princípio da igualdade perante a lei
- **Sala de Estado Maior**: Compartimento localizado em unidade militar utilizado por oficiais para exercer suas funções

### Referências legais
- Art. 295, §3º do CPP
- Art. 439 da Lei n.º 12.403/11

### Jurisprudência
- Súmula 717, STF
- Info 778, STF

### Dicas de prova
- Entenda a incompatibilidade da prisão especial com a Constituição Federal
- Conheça a diferença entre sala de Estado Maior e ambiente equiparado à sala de Estado Maior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.422 (1)", "page_number": 422, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 295, §3º do CPP", "Art. 439 da Lei n.º 12.403/11"], "jurisprudence": ["Súmula 717, STF", "Info 778, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:35:05.823444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=422", "doc_key": "994f4418f14a8a87aa130e0feb911626"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c76177cb2dd34a2472aa2734427104363e8992a8795db252dd159279f957830c'),
  ('cpiuris2025::8133f0fcd22ac6c8b62b0db204fc050b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito à sala de Estado Maior', '## Direito à sala de Estado Maior

O direito à sala de Estado Maior é aplicável em casos de prisão cautelar, perdendo relevância após o início do cumprimento da pena. Os que fazem jus a esse direito incluem membros do Ministério Público, magistrados, Defensoria Pública e advogados.

### Conceitos
- **Prisão Cautelar**: Prisão temporária, realizada antes de sentença condenatória
- **Sala de Estado Maior**: Área específica do presídio onde são mantidos os prisioneiros de alta segurança
- **Direito à Sala**: Direito dos detentos a ser mantidos em uma área específica do presídio

### Referências legais
- Art. 40, II, da Lei nº 8.625/93
- Art. 18, II, ''e'', da LC nº 75/93
- Art. 33 da LOMAN
- Art. 44, III, da LC nº 80/94

### Jurisprudência
- STJ Info 591
- STJ Info 755

### Dicas de prova
- Distinção entre prisão cautelar e cumprimento de pena
- Relevância do direito à sala de Estado Maior em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.422 (2)", "page_number": 422, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 40, II, da Lei nº 8.625/93", "Art. 18, II, ''e'', da LC nº 75/93", "Art. 33 da LOMAN", "Art. 44, III, da LC nº 80/94"], "jurisprudence": ["STJ Info 591", "STJ Info 755"], "confidence": 0.8, "extracted_at": "2026-05-29T05:36:19.805162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=422", "doc_key": "8133f0fcd22ac6c8b62b0db204fc050b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '402d1c82fec714b1c42164d78fcf8154bdf21f326711e4908a32b0c9b753e9fe'),
  ('cpiuris2025::a9a0bbe563e5d8e021e93efc4fb1cc3c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Prisão', '## Mandado de Prisão

O mandado de prisão é o instrumento que materializa a ordem de prisão escrita e fundamentada de autoridade judiciária competente, cuja apresentação ao respectivo diretor ou carcereiro é obrigatória para o recolhimento à prisão.

### Conceitos
- **Mandado de Prisão**: Instrumento que materializa a ordem de prisão escrita e fundamentada de autoridade judiciária competente
- **Prisão em Flagrante**: Prisão realizada sem necessidade de mandado judicial, nos casos de transgressões militares e crimes propriamente militares
- **Fiança**: Declaração do valor da fiança arbitrada, quando afiançável a infração penal

### Referências legais
- Art. 285 do CPP
- Art. 286 do CPP
- Art. 287 do CPP
- Art. 9º da Lei n.º 13.869/19

### Dicas de prova
- Entenda a importância do mandado de prisão e seus requisitos
