  ('cpiuris2025::d3662b9ba1f32be3b6f13787409b1cef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição e Execução de Mandado Judicial', '## Requisição e Execução de Mandado Judicial

O mandado judicial pode ser requisitado para capturar um acusado, mesmo sem sua exibição imediata. A prisão pode ser deprecada se o acusado estiver no território nacional, fora da jurisdição do juiz processante.

### Conceitos
- **Mandado Judicial**: Instrumento processual que autoriza a captura de um acusado
- **Requisição**: Ação de solicitar algo, como a prisão de um acusado
- **Prisão Preventiva**: Medida cautelar que impede o liberdade do acusado até o julgamento

### Referências legais
- Art. 289
- Art. 299

### Dicas de prova
- Entenda a diferença entre prisão preventiva e deprecada
- Conheça as condições para requisicionar um mandado judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.423 (2)", "page_number": 423, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 289", "Art. 299"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:37:00.866838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=423", "doc_key": "d3662b9ba1f32be3b6f13787409b1cef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7dded1ec3c3860a61f767fb5c63970848f33e26134e60198cce883218bce74c9'),
  ('cpiuris2025::e2bd75d52c1618ddd0800401b594eff5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar no processo penal deve cumprir os requisitos do art. 285 e 286 do CPP, incluindo a comunicação ao juiz competente e registro no Conselho Nacional de Justiça.

### Conceitos
- **Mandado de prisão**: Documento que determina a prisão de uma pessoa
- **Pretocaria**: Procedimento que envolve a comunicação entre autoridades policiais e judiciárias
- **Banco de dados**: Sistema que registra mandados de prisão existentes no país
- **Executoriedade**: Capacidade do mandado de prisão para ser cumprido em todo o Brasil
- **Voz de prisão**: Prisão feita sem a necessidade de apresentar o mandado, em casos de flagrante delito

### Referências legais
- Art. 289-A do CPP
- Art. 285 e 286 do CPP
- Art. 290 do CPP

### Dicas de prova
- Entenda a importância da comunicação entre autoridades policiais e judiciárias
- Conheça o sistema de banco de dados que registra mandados de prisão
- Aprenda a diferença entre voz de prisão e apresentação do mandado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.424 (1)", "page_number": 424, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 289-A do CPP", "Art. 285 e 286 do CPP", "Art. 290 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:38:13.899471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=424", "doc_key": "e2bd75d52c1618ddd0800401b594eff5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '81a0ce5be942c25730c6d00c549261cec3a1955bbe0dad1704611506da92f4ae'),
  ('cpiuris2025::bdc181d9e923d071172ea3dc03283f27', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão em Outra Localidade', '## Prisão em Outra Localidade

A prisão pode ser efetuada em outra localidade se o executor está perseguidor do réu, que passou para outro município ou comarca.

### Conceitos
- **Prisão em Outra Localidade**: Efetuação da prisão em local diferente ao onde o preso foi encontrado
- **Perseguição**: Ação de perseguir alguém, com o objetivo de capturá-lo
- **Auto de Flagrante**: Documento que certifica a prisão de alguém
- **Remoção do Preso**: Movimentação do preso para outro local, com o objetivo de cumprir sua pena

### Referências legais
- Art. 290 da Lei Código de Processo Penal
- Súmula 444 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão em Outra Localidade

### Dicas de prova
- Entenda a noção de perseguição e como ela afeta a efetuação da prisão
- Conheça as exceções ao emprego de força na prisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.424 (2)", "page_number": 424, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 290 da Lei Código de Processo Penal", "Súmula 444 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão em Outra Localidade"], "confidence": 0.8, "extracted_at": "2026-05-29T05:38:15.341793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=424", "doc_key": "bdc181d9e923d071172ea3dc03283f27"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '484d7d700f3f80bd20cc95dd4324a041ebc9bd26374934c0cdb1e23bc358f69b'),
  ('cpiuris2025::2fb8c1699153929025a6e37ae2ed6e9a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar pode ser exercida de maneira ativa ou passiva. A resistência ativa é a praticada mediante violência ou ameaça, enquanto a resistência passiva ocorre quando o capturando foge ou queda-se inerte para não ser removido do local.

### Conceitos
- **Resistência**: Ação exercida pelo réu para evitar sua prisão
- **Tutela cautelar**: Medida provisória adotada para proteger os direitos do réu ou de terceiros
- **Prisão em flagrante**: Prisão realizada no momento da captura do réu

### Referências legais
- Art. 292
- Art. 293
- Art. 243, I, do CPP
- Art. 5º, XI, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre resistência ativa e passiva
- Conheça as regras para a realização de prisões em flagrante
- Interprete a proteção à inviolabilidade do domicílio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.425 (1)", "page_number": 425, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 292", "Art. 293", "Art. 243, I, do CPP", "Art. 5º, XI, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:40:37.483358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=425", "doc_key": "2fb8c1699153929025a6e37ae2ed6e9a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c3b7acc5f59cca90f7c4638ae231598c2b14c203a8df50b19543ecf70bef2ba2'),
  ('cpiuris2025::b4509c301c52e3bbfe7728a8b3e43935', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia: Direito Fundamental e Prerrogativa do Estado', '## Audiência de Custódia: Direito Fundamental e Prerrogativa do Estado

A audiência de custódia é direito público subjetivo fundamental, assegurado por convenções internacionais de direitos humanos. Tem dois objetivos: coibir excessos como torturas e maus tratos, e conferir ao juiz ferramenta para adotar medida adequada em prisão em flagrante.

### Conceitos
- **Audiência de Custódia**: direito público subjetivo fundamental
- **Convenção Americana de Direitos Humanos**: convenção internacional que assegura direitos humanos
- **Direito Fundamental**: direito inherente à pessoa humana
- **Prerrogativa do Estado**: direito ou faculdade concedida ao Estado
- **Coibição de Excessos**: medida para evitar torturas e maus tratos
- **Ferramenta Jurisdicional**: instrumento utilizado pelo juiz para tomar decisões
- **Prazão em Flagrante**: condição que permite ao juiz adotar medida adequada

### Referências legais
- ADPF 347 MC
- Lei nº 13.964/2019
- Resolução 213/2015 do CNJ

### Jurisprudência
- STF. HC 188888/MG
- Info 994

### Dicas de prova
- Entenda a importância da audiência de custódia como direito fundamental
- Conheça as convenções internacionais que garantem os direitos humanos
- Identifique os objetivos da audiência de custódia e sua relação com o Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.425 (2)", "page_number": 425, "discipline": "Direito Processual Penal", "legal_refs": ["ADPF 347 MC", "Lei nº 13.964/2019", "Resolução 213/2015 do CNJ"], "jurisprudence": ["STF. HC 188888/MG", "Info 994"], "confidence": 0.8, "extracted_at": "2026-05-29T05:41:17.355123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=425", "doc_key": "b4509c301c52e3bbfe7728a8b3e43935"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e5fea6ff25c77275d85985ebdd69e805016b6ce932c8ef432c77f0dd831b08e7'),
  ('cpiuris2025::b950d0666a05e4803705e94e26003fae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Audiência de custódia é garantia convencional prevista na Convenção Americana sobre Direitos Humanos, que deve ocorrer em qualquer tipo de prisão, com presença do acusado e seus representantes legais, dentro de um prazo razoável.

### Conceitos
- **Audiência de custódia**: Garantia convencional prevista na Convenção Americana sobre Direitos Humanos
- **Prisão em flagrante**: Tipo de prisão que pode ocorrer sem a necessidade de mandado
- **Resolução n.º 213/15 do CNJ**: Regulamentação da audiência de custódia antes da Lei n.º 13.964/19
- **Lei n.º 13.964/19**: Pacote Anticrime que estabeleceu a previsão legal expressa da audiência de custódia no art. 310 do CPP
- **Art. 310 do CPP**: Previsão legal expressa da audiência de custódia

### Referências legais
- Art. 7 da Convenção Americana sobre Direitos Humanos
- Art. 310 do CPP
- Resolução n.º 213/15 do CNJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre audiência de custódia

### Dicas de prova
- Entenda a importância da audiência de custódia como garantia convencional prevista na Convenção Americana sobre Direitos Humanos
- Conheça as alterações feitas pela Lei n.º 13.964/19 e sua regulamentação no art. 310 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.426 (1)", "page_number": 426, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7 da Convenção Americana sobre Direitos Humanos", "Art. 310 do CPP", "Resolução n.º 213/15 do CNJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre audiência de custódia"], "confidence": 0.8, "extracted_at": "2026-05-29T05:41:28.179512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=426", "doc_key": "b950d0666a05e4803705e94e26003fae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a66662e352fb0fe0aa49f7f82504374a97fbed887f4a26067d84fb479f2c5ec0'),
  ('cpiuris2025::db1eeace273cb3dacc328addbb7d747a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia', '## Audiência de Custódia

O prazo da audiência de custódia é objeto de controvérsias. A Convenção não estabelece um prazo específico, mas a Lei determina que deve ocorrer em até 24 horas após a prisão.

### Conceitos
- **Audiência de Custódia**: procedimento judicial para garantir os direitos do preso
- **Prisão em Flagrante**: prisão imediata após o cometimento de um crime
- **Competência do Juiz das Garantias**: competência do juiz para processar e julgar crimes

### Referências legais
- Art. 310, caput, do CPP
- Lei nº 13.964/2019

### Jurisprudência
- RE 123456 (2023)
- Tema repetitivo: Audiência de Custódia

### Dicas de prova
- Entenda a competência do juiz das garantias
- Conheça o prazo da audiência de custódia e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.426 (2)", "page_number": 426, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, caput, do CPP", "Lei nº 13.964/2019"], "jurisprudence": ["RE 123456 (2023)", "Tema repetitivo: Audiência de Custódia"], "confidence": 0.8, "extracted_at": "2026-05-29T05:42:41.808804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=426", "doc_key": "db1eeace273cb3dacc328addbb7d747a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4517b221eff22a2bcd54b484f9d881480de7a308d05ad7439a85986188159426'),
  ('cpiuris2025::712da94b830887cdec1ab2c0c296108e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia por Videoconferência', '## Audiência de Custódia por Videoconferência

É possível realizar audiência de custódia por videoconferência em casos excepcionais e fundamentados, com a aprovação do STF no julgamento das ADI 6.298/6.305.

### Conceitos
- **Audiência de Custódia**: Ato processual que visa garantir os direitos do preso
- **Videoconferência**: Método de comunicação remota para realizar audiências
- **Excepcionalidade**: Condição necessária para a realização de audiência de custódia por videoconferência

### Referências legais
- Art. 310 do CPP
- Súmula 30 da I Jornada de Direito Penal e Processual Penal

### Jurisprudência
- ADI 6.298/6.305
- RE 123456

### Dicas de prova
- Distinção entre audiência presencial e videoconferência
- Condições necessárias para a realização de audiência de custódia por videoconferência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.427 (2)", "page_number": 427, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310 do CPP", "Súmula 30 da I Jornada de Direito Penal e Processual Penal"], "jurisprudence": ["ADI 6.298/6.305", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:43:24.388422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=427", "doc_key": "712da94b830887cdec1ab2c0c296108e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0278b8fd20757cfeab2f415ab6a8bd9264923f0d93c98ccfeaafe53ad7d0cbab'),
  ('cpiuris2025::920c608a8581f5e2b6b15277e7b24143', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Audiência de custódia deve ser realizada em 24 horas para presos em flagrante ou por força de mandado de prisão provisória, com a presença do juiz de garantias, Ministério Público e Defensoria Pública. O prazo não pode ser reduzido e não se admite realização por videoconferência.

### Conceitos
- **Audiência de custódia**: Reunião com o juiz de garantias, Ministério Público e Defensoria Pública para avaliar a situação do preso
- **Prisão preventiva**: Medida cautelar que determina a prisão do acusado antes do julgamento
- **Videoconferência**: Reunião virtual com o juiz de garantias, Ministério Público e Defensoria Pública

### Referências legais
- Art. 3º-B §1º do CPP

### Jurisprudência
- STJ. 3ª Seção. CC 168522-PR
- RE 123456

### Dicas de prova
- Entenda a importância da audiência de custódia e o prazo para sua realização
- Conheça as limitações da videoconferência na realização da audiência de custódia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.427 (1)", "page_number": 427, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B §1º do CPP"], "jurisprudence": ["STJ. 3ª Seção. CC 168522-PR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:43:46.599942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=427", "doc_key": "920c608a8581f5e2b6b15277e7b24143"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eb5cb8c70255deb01dba009d5975fbd1bb35121c0b1e9cc1f0e5e58e9b7cc121'),
  ('cpiuris2025::aa130f95e6d3e16af81361af4c06bb56', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A não realização da audiência de custódia dentro do prazo estabelecido sem motivação idônea pode ensejar a ilegalidade da prisão, que deve ser relaxada pela autoridade competente.

### Conceitos
- **Audiência de custódia**: Reunião entre o juiz e o preso para garantir seus direitos fundamentais
- **Prisão preventiva**: Medida cautelar que determina a detenção do preso antes de julgamento
- **Vestuário e calçado adequados**: Requisito para garantir a dignidade e o bem-estar do preso

### Referências legais
- Art. 310, § 4º, do CPP
- Lei n.º 13.869/19
- Súmula 347 da STF

### Jurisprudência
- ADPF 347 da STF
- Resolução n.º 213/15 do CNJ

### Dicas de prova
- Distinção entre prisão preventiva e tutela cautelar
- Importância da audiência de custódia para garantir os direitos do preso
- Requisitos para a realização da audiência de custódia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.428 (1)", "page_number": 428, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, § 4º, do CPP", "Lei n.º 13.869/19", "Súmula 347 da STF"], "jurisprudence": ["ADPF 347 da STF", "Resolução n.º 213/15 do CNJ"], "confidence": 0.8, "extracted_at": "2026-05-29T05:45:10.340115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=428", "doc_key": "aa130f95e6d3e16af81361af4c06bb56"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '573b33dd2e93560c91adeb170a9c46a31a4571d0089fcc90f5a73787101e5af0'),
  ('cpiuris2025::924b4a0f4cb01282272cc1b54dd83091', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Regras para a entrevista da pessoa presa durante o processo penal, incluindo questões sobre direitos constitucionais e tratamento recebido.

### Conceitos
- **Entrevista cautelar**: Conversa realizada com a pessoa presa para garantir seus direitos constitucionais.
- **Direito à defesa**: O direito do acusado de ser assistido por um advogado ou defensor.
- **Tratamento adequado**: A garantia de que a pessoa presa receba tratamento adequado, incluindo água potável e alimentação.

### Referências legais
- Art. 562, Código de Processo Penal

### Dicas de prova
- Entenda a importância da entrevista cautelar para garantir os direitos do acusado.
