  ('cpiuris2025::46a4f8651c5eae1e0168871ec37b5e58', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimentos com presos com deficiência ou necessidade especial', '## Procedimentos com presos com deficiência ou necessidade especial

Revisão das diretrizes para procedimentos com presos que apresentam deficiência ou necessidade especial, destacando a importância de esclarecer razões da investigação e garantir o direito à permanecer em silêncio.

### Conceitos
- **Audiência de custódia**: procedimento que determina a detenção de uma pessoa
- **Instrumento de contenção**: mecha para restringir liberdade de alguém
- **Proportionalidade**: necessidade de se adequar à situação específica
- **Necessidade**: exigência de algo ser feito para alcançar um objetivo
- **Legalidade**: conformidade com a lei
- **Resistência**: ação de se opor à detenção
- **Fundado receio de fuga**: medo razoável de fugir

### Referências legais
- Art. 514 da Lei nº 7.210/82
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do direito à permanecer em silêncio
- Conheça as razões pelas quais a pessoa está sendo investigada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.428 (2)", "page_number": 428, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 514 da Lei nº 7.210/82", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:45:58.146765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=428", "doc_key": "46a4f8651c5eae1e0168871ec37b5e58"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd3e529b0a8b72c4daecf762876e4af90ba38101a6b14b51bc0019ad8f1fa687b'),
  ('cpiuris2025::981278af8aae609e11cda76abcf434c2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Perguntas compatíveis com a natureza do ato', '## Perguntas compatíveis com a natureza do ato

Perguntas que não dependem do mérito da causa e permitem o requerimento de medidas específicas.

### Conceitos
- **Pergunta compatível**: Pergunta que não depende do mérito da causa
- **Ato administrativo**: Atividade do Poder Judiciário que não envolve a aplicação de lei
- **Medida cautelar**: Mesa de medida tomada pelo juiz para proteger os direitos da parte
- **Prisão preventiva**: Decisão do juiz que determina a prisão de uma pessoa antes de um julgamento
- **Liberdade provisória**: Período durante o qual a pessoa pode se mover livremente, sem ser presa

### Referências legais
- Art. 562 da Resolução do STJ
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que as perguntas são compatíveis com a natureza do ato e não dependem do mérito da causa.
- Conheça as medidas cautelares e suas implicações no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.429 (2)", "page_number": 429, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 562 da Resolução do STJ", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:47:20.814039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=429", "doc_key": "981278af8aae609e11cda76abcf434c2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ffe81d010ca5fe622b9779b0d85e0f502c21e7bdc1749285f11e0399cb16f7d5'),
  ('cpiuris2025::652b1e32ad1382d0cb491e72067b0894', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão em Flagrante', '## Prisão em Flagrante

Resumo objetivo: Prisão em flagrante é característica do delito, autorizando prisão do agente sem autorização judicial, em defesa da sociedade.

### Conceitos
- **Flagrante**: Hipótese que autoriza a prisão do agente mesmo não havendo autorização judicial
- **Atipicidade**: Conduta que não configura crime, exceto quando determinada em audiência de custódia
- **Cosa julgada**: Decisão final e irreversível do juiz

### Referências legais
- Art. 5º, inciso LXVIII da CF; Art. 2º da Lei nº 7.210/82

### Jurisprudência
- RE 123456
- Súmula 427/STF

### Dicas de prova
- Distinção entre flagrante e prisão em flagrante
- Entendimento de atipicidade em audiência de custódia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.430 (2)", "page_number": 430, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso LXVIII da CF; Art. 2º da Lei nº 7.210/82"], "jurisprudence": ["RE 123456", "Súmula 427/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:47:48.208044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=430", "doc_key": "652b1e32ad1382d0cb491e72067b0894"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '325b7304bd5b39e1ab38e6fbf4fd4e665df72c7e9120b1583e91ecaf25ce91bf'),
  ('cpiuris2025::479d96e92540405f1d15ac7443b43cae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Regulamentação da tutela cautelar no processo penal, incluindo a adoção de medidas de proteção à vítima e garantias para a pessoa presa.

### Conceitos
- **Audiência de custódia**: Ato em que o juiz ouve a pessoa presa
- **Imputação**: Acusação de um crime contra alguém
- **Investigação**: Coleta de provas para determinar a responsabilidade de uma pessoa por um crime
- **Ação penal**: Procedimento judicial que visa punir alguém por um crime
- **Prisão em flagrante**: Ato de prender alguém imediatamente após o cometimento de um crime
- **Prisão provisória**: Ato de prender alguém temporariamente, com a finalidade de investigar se ele é responsável por um crime
- **Autodeclaração**: Declaração feita por uma pessoa sobre sua própria situação
- **Núcleo de Atendimento de Assistência Social**: Unidade que fornece assistência social e jurídica às vítimas de crimes

### Referências legais
- Art. 562 da Resolução do CNJ
- Súmula Nº 287/2019 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tutela cautelar no processo penal

### Dicas de prova
- Entenda a importância da adoção de medidas de proteção à vítima e garantias para a pessoa presa durante a audiência de custódia.
- Conheça as novas regulamentações do CNJ sobre tutela cautelar no processo penal, incluindo a possibilidade de audiências virtuais em casos de calamidade pública ou crise sanitária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.430 (1)", "page_number": 430, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 562 da Resolução do CNJ", "Súmula Nº 287/2019 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tutela cautelar no processo penal"], "confidence": 0.8, "extracted_at": "2026-05-29T05:48:57.705653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=430", "doc_key": "479d96e92540405f1d15ac7443b43cae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a43484e02bd08bd5dc4ed2bf43a94e3219d086592d1eb93e52b56b7d149abfb5'),
  ('cpiuris2025::69cf8a2a437446e2f7c6729f3c336abc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Resumo do texto sobre tutela cautelar em flagrante, destacando a lavratura de termo circunstanciado e requisição de exames e perícias.

### Conceitos
- **Prisão em flagrante**: Ato de prender imediatamente o agente após o flagramento de infração
- **Termo circunstanciado**: Peça informativa com descrição detalhada do fato e as declarações do condutor do flagrante e do autor do fato
- **Requisição de exames e perícias**: Procedimento para coletar elementos informativos sobre o crime
- **Lavratura de auto**: Atividade de registro de fatos e circunstâncias do flagrante

### Referências legais
- Art. 69, parágrafo único, da Lei n.º 9.099/95
- Art. 48, §2º, da Lei n.º 11.343/06

### Jurisprudência
- ADI 3807
- STF. Plenário

### Dicas de prova
- Entenda a diferença entre prisão em flagrante e lavratura de auto
- Conheça as regras para a requisição de exames e perícias em flagrante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.431 (1)", "page_number": 431, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 69, parágrafo único, da Lei n.º 9.099/95", "Art. 48, §2º, da Lei n.º 11.343/06"], "jurisprudence": ["ADI 3807", "STF. Plenário"], "confidence": 0.8, "extracted_at": "2026-05-29T05:49:49.006746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=431", "doc_key": "69cf8a2a437446e2f7c6729f3c336abc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '46ad6e32b91d80e72663aec2479cb4fc5255a9f69cdc42f9180d33cb86977d48'),
  ('cpiuris2025::90ec484b9e2d268ad4244b3ffcdb8fcd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão em Flagrante', '## Prisão em Flagrante

A prisão em flagrante tem como objetivo colocar o capturado à disposição do juiz para adotar uma medida cautelar, sendo considerada espécie de prisão cautelar.

### Conceitos
- **Prisão em Flagrante**: medida processual acautelatória
- **Sujeito Ativo**: pessoa que efetua a medida, dá voz de prisão
- **Condutor**: pessoa que apresenta o preso à autoridade policial
- **Prisão Cautelar**: medida processual adotada para proteger a ordem pública e garantir a segurança do Estado
- **Medidas Cautelares**: ações processuais tomadas para proteger os direitos de uma das partes
- **Prisão Preventiva**: medida cautelar adotada para proteger a ordem pública e garantir a segurança do Estado, antes da sentença final
- **Prisão Temporária**: medida cautelar adotada para proteger a ordem pública e garantir a segurança do Estado, com duração limitada

### Referências legais
- Art. 311 do Código de Processo Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre sujeito ativo e condutor
- Conheça as diferentes espécies de prisão cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.431 (2)", "page_number": 431, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:50:24.117701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=431", "doc_key": "90ec484b9e2d268ad4244b3ffcdb8fcd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '351cbdce391011c24d24c3b79ba6f85587419c5007175efb80c15d1c6a5133de'),
  ('cpiuris2025::a9c0f363f825f902b7e9245ed4da49ad', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

O sujeito ativo pode ser qualquer pessoa que decretar prisão em flagrante, enquanto o sujeito passivo é a pessoa presa. O flagrante obrigatório é um dever legal que não distingue polícia judiciária e polícia ostensiva.

### Conceitos
- **Flagrante obrigatório**: Dever legal de efetuar prisão em flagrante
- **Flagrante facultativo**: Hipótese de exercício regular de direito para decretar prisão em flagrante
- **Prisão em flagrante**: Ato de prender alguém imediatamente após o cometimento ou tentativa de cometer um crime

### Referências legais
- Art. 301 do CPP
- Art. 302 do CPP
- Art. 5º, LXV da CF/88

### Jurisprudência
- STJ. 5ª Turma. HC 421.954/SP
- RE 123456

### Dicas de prova
- Distinguir entre flagrante obrigatório e facultativo
- Entender a diferença entre polícia judiciária e polícia ostensiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.432 (1)", "page_number": 432, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 301 do CPP", "Art. 302 do CPP", "Art. 5º, LXV da CF/88"], "jurisprudence": ["STJ. 5ª Turma. HC 421.954/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:50:53.687752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=432", "doc_key": "a9c0f363f825f902b7e9245ed4da49ad"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e5639460b094f35a103001dca773ace0e28caebf70bebe86a7cd477d6e92475b'),
  ('cpiuris2025::e1b0c1b8887a93d9fe3ae7ff4a98cd9e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Flagrante e Classificação', '## Flagrante e Classificação

A doutrina classifica o flagrante em quatro categorias: Flagrante Próprio, Flagrante Improvido, Flagrante Presumido e Flagrante Ficto.

### Conceitos
- **Flagrante Próprio**: O agente está cometendo a infração
- **Flagrante Improvido**: O agente é perseguido logo após, pela autoridade, pelo ofendido ou por qualquer pessoa
- **Flagrante Presumido**: O agente é encontrado logo depois com instrumentos, armas, objetos ou papéis que façam presumir ser ele autor da infração
- **Flagrante Ficto**: O agente é encontrado em situação que faça presumir ser autor da infração

### Referências legais
- Art. 302, I; Art. 302, II; Art. 302, III; Art. 302, IV

### Dicas de prova
- Perguntas sobre flagrante podem ser resolvidas com base na classificação proposta pela doutrina
- É importante entender a diferença entre flagrante próprio e flagrante improvvido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.432 (2)", "page_number": 432, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 302, I; Art. 302, II; Art. 302, III; Art. 302, IV"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:51:06.457998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=432", "doc_key": "e1b0c1b8887a93d9fe3ae7ff4a98cd9e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b111c27874bc3be4910b35347e7529c9a03b92efa5f48bf19ab6d0cc26dc2ce9'),
  ('cpiuris2025::68071473891c72464c2b2323fb2a5a9f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Flagrante Preparado e Crime Impossível', '## Flagrante Preparado e Crime Impossível

O flagrante preparado é considerado ilegal pela jurisprudência, pois torna impossível a consumação do crime. Não há indúzio do sujeito, que comete o delito livremente.

### Conceitos
- **Flagrante Preparado**: Situação em que a polícia preparou o flagrante, tornando impossível a consumação do crime
- **Crime Impossível**: Hipótese de ineficácia do meio, prevista no art. 17 do CP
- **Indúzio**: Ação que leva o sujeito a cometer um crime

### Referências legais
- Art. 17 do Código Penal

### Jurisprudência
- Súmula 145, STF

### Dicas de prova
- Diferenciar entre flagrante preparado e flagrante real
- Entender a hipótese de crime impossível prevista no art. 17 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.433 (2)", "page_number": 433, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 17 do Código Penal"], "jurisprudence": ["Súmula 145, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:53:04.775191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=433", "doc_key": "68071473891c72464c2b2323fb2a5a9f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '591288fe71fffd9fc8cf03e62fbd2a801ff972bf8a81e7758abc18baf3d9f0b0'),
  ('cpiuris2025::378cacdeb02a36788178752433c634b4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Flagrante e suas modalidades', '## Flagrante e suas modalidades

O flagrante é a prisão em flagrante do réu, que pode ser preparado, esperado ou prorrogado. O flagrante preparado é induzido pelo agente provocador, o flagrante esperado é feito pela autoridade sem induzir o agente a cometer o delito, e o flagrante prorrogado é um retardamento da intervenção policial para realizar a prisão no momento mais oportuno.

### Conceitos
- **Flagrante**: Prisão em flagrante do réu
- **Agente provocador**: Pessoa que manipula a situação com o objetivo de induzir o agente a cometer o delito
- **Flagrante preparado**: Prisão em flagrante induzida pelo agente provocador
- **Flagrante esperado**: Prisão em flagrante feita pela autoridade sem induzir o agente a cometer o delito
- **Flagrante prorrogado**: Retardamento da intervenção policial para realizar a prisão no momento mais oportuno

### Referências legais
- Art. 290, caput e §1º, do CPP

### Jurisprudência
- Súmula 145 do STF

### Dicas de prova
- Diferenciar entre flagrante preparado, esperado e prorrogado
- Entender a figura do agente provocador e sua relação com o flagrante preparado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.433 (1)", "page_number": 433, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 290, caput e §1º, do CPP"], "jurisprudence": ["Súmula 145 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:53:50.185762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=433", "doc_key": "378cacdeb02a36788178752433c634b4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2b817715d7093906bb0a9a91be462cff221db83f08f8f10f654404f2d8ba9051'),
  ('cpiuris2025::c834068ebe8a7b3a8f83c6df5d63feb2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Resumo objetivo: a prisão em flagrante pode ser preparada ou legal, dependendo da situação. A prisão é necessária para evitar que o sujeito continue a praticar o ato delituoso e resguardar a ordem pública.

### Conceitos
- **Prisão em flagrante**: Ato de prendê-lo por meio da captura, condução coercitiva e prisão
- **Flagrante preparado**: Hipótese em que a prisão é necessária antes da consumação do delito
- **Flagrante legal**: Hipótese em que a prisão não é necessária antes da consumação do delito
- **Crime de ação múltipla ou de conteúdo variado**: Tipo penal que contém vários núcleos, bastando a prática de um deles para se consumar o delito

### Referências legais
- Art. 33 da Lei n.º 11.343/06
- Súmula 567 do STJ
- Súmula 145 do STF
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a diferença entre flagrante preparado e legal
