  ('cpiuris2025::70a3e602376ba4ee0aa3df0a183de08b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Lavratura do auto de prisão em flagrante e Recolhimento à prisão', '## Lavratura do auto de prisão em flagrante e Recolhimento à prisão

A prisão em flagrante é ato administrativo realizado pelo delegado de polícia, enquanto a comunicação da detenção ao juiz a torna ato judicial. O recolhimento à prisão não ocorre se houver fiança concedida.

### Conceitos
- **Lavratura do auto de prisão em flagrante**: Elaboração do auto de prisão em flagrante
- **Recolhimento à prisão**: Manutenção do agente no cárcere, após a prisão em flagrante
- **Fiança**: Concessão de liberdade ao preso, em caso de detenção

### Referências legais
- Art. 306, §2º
- Art. 306, §1º
- Art. 322

### Dicas de prova
- Entenda a distinção entre ato administrativo e ato judicial na prisão em flagrante.
- Conheça a regra de liberdade e prisão no ordenamento jurídico brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.434 (2)", "page_number": 434, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 306, §2º", "Art. 306, §1º", "Art. 322"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:55:20.812906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=434", "doc_key": "70a3e602376ba4ee0aa3df0a183de08b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '882169498d8e310a57ee5c64fb148dddf08715103ee23c87b3a2e8429f640bed'),
  ('cpiuris2025::89fd7d3f91bcfebb9fbd7ff83ad346e9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

Descreve as espécies de crimes e a possibilidade de prisão em flagrante, bem como o auto de prisão em flagrante.

### Conceitos
- **Prisão em flagrante**: A prisão de um indivíduo no momento da comissão do crime
- **Consumação do crime**: O momento em que o crime é considerado consumado
- **Crime permanente**: Um crime que continua a existir após a comissão do ato
- **Habitualidade criminosa**: A prática de vários crimes por um mesmo agente
- **Auto de prisão em flagrante (APF)**: O instrumento que documenta os fatos da prisão em flagrante

### Referências legais
- art. 303 do CPP
- art. 148 do CP
- art. 35 da Lei n.º 11.343/06
- art. 230 do CP
- art. 282 do CP
- art. 316 do CP

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre prisão em flagrante e consumação do crime
- Conheça as espécies de crimes e suas características
- Avalie a importância do auto de prisão em flagrante (APF)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.435", "page_number": 435, "discipline": "Direito Processual Penal", "legal_refs": ["art. 303 do CPP", "art. 148 do CP", "art. 35 da Lei n.º 11.343/06", "art. 230 do CP", "art. 282 do CP", "art. 316 do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T05:56:42.378745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=435", "doc_key": "89fd7d3f91bcfebb9fbd7ff83ad346e9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ea660bc270eac3f5db2a46158505c6107226117b1e85363c6a02479f2fd90494'),
  ('cpiuris2025::cd322a66d00b01e8b93ad47fef0972e5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Atribuição para a lavratura do auto de prisão em flagrante', '## Atribuição para a lavratura do auto de prisão em flagrante

A atribuição da lavratura do auto de prisão em flagrante é feita pela autoridade policial, mas não é privativa. Em caso de crime cometido nas dependências do Congresso, o poder de polícia é compartilhado com a Câmara dos Deputados e do Senado Federal.

### Conceitos
- **Atribuição**: O ato de delegar uma competência ou poder a outra pessoa ou entidade
- **Auto de prisão em flagrante**: Um documento que registra a prisão de alguém em flagrante, com as informações necessárias para o processo
- **Condutor**: A pessoa responsável pela condução do preso à autoridade competente
- **Oitiva das testemunhas**: O ato de ouvir as testemunhas que acompanharam o preso à autoridade competente
- **Interrogatório do acusado**: O ato de questionar o acusado sobre a imputação feita contra ele
- **Competência**: A capacidade de uma autoridade ou entidade exercer um poder ou competência

### Referências legais
- Art. 304 do Código de Processo Penal
- Súmula 397 da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a atribuição da lavratura do auto de prisão em flagrante e as exceções ao artigo 304 do Código de Processo Penal
- Conheça o papel do condutor na condução do preso à autoridade competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.436 (1)", "page_number": 436, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 304 do Código de Processo Penal", "Súmula 397 da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T05:57:06.327387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=436", "doc_key": "cd322a66d00b01e8b93ad47fef0972e5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb4436efc657f1aeca1177cbeb05ab68899c6932bf61032e1f94ce73abfd9247'),
  ('cpiuris2025::6313d99e553ca92aea62e443a8476e31', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão em Flagrante', '## Prisão em Flagrante

A prisão em flagrante pode ser realizada sem a oitiva do ofendido, mas ele tem direito de permanecer calado. A ausência de interrogatório não acarreta a nulidade da prisão. O estrangeiro precisa de intérprete.

### Conceitos
- **Prisão em Flagrante**: Ato processual que determina a detenção imediata do preso
- **Auto de Prisão**: Documento que lavra o ato de prisão
- **Interrogatório**: Oitiva do preso para coletar declarações
- **Impedimento**: Caso em que não pode ser realizado o interrogatório

### Referências legais
- Art. 305 do CPP
- Art. 5º, LXIII da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte se a prisão em flagrante pode ser realizada sem a oitiva do ofendido.
- Entenda a diferença entre relaxamento e não ratificação da voz de prisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.436 (2)", "page_number": 436, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 305 do CPP", "Art. 5º, LXIII da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:57:25.262479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=436", "doc_key": "6313d99e553ca92aea62e443a8476e31"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e963833aa85824d38ee23936598ad500ef70a71c8daaf5e2ecdddb07ad7942b9'),
  ('cpiuris2025::3c4eac667434a3f0881291dc07cc99eb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Auto de prisão em flagrante', '## Auto de prisão em flagrante

Rege a narrativa do fato, voz de prisão, declarações do preso e depoimentos das testemunhas, com assinatura da autoridade, do preso e das testemunhas.

### Conceitos
- **Auto de prisão em flagrante**: Documento que registra o fato delituoso, voz de prisão, declarações do preso e depoimentos das testemunhas.
- **Autoridade coatora**: O magistrado que pratica o ato delituoso
- **Remessa ao juiz**: Dever de a autoridade que lavrar o auto de prisão em flagrante, remetê-lo ao juiz competente

### Referências legais
- Art. 307 do Código de Processo Penal

### Dicas de prova
- Distinção entre a autoridade coatora e o magistrado
- Importância da remessa ao juiz competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.437 (2)", "page_number": 437, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 307 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:58:59.945060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=437", "doc_key": "3c4eac667434a3f0881291dc07cc99eb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b64808d092f3b0b29e054dfb4b1a9b26e07e6c31bdc86ac86df521e43ba45959'),
  ('cpiuris2025::3804459f64d30d96e28b484418e092f7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Regras para a prisão de presos, incluindo a comunicação à autoridade judiciária e o prazo para a lavratura do auto de prisão em flagrante.

### Conceitos
- **Prisão em flagrante**: A prisão de uma pessoa que está sendo cometida ou presa a um crime.
- **Auto de prisão em flagrante**: O documento que registra a prisão de uma pessoa.
- **Nota de culpa**: Um instrumento informativo dirigido ao preso, que lhe informa o motivo da prisão.
- **Fiança**: A garantia oferecida pelo preso para ser libertado provisoriamente.
- **Liberdade provisória**: O direito do preso de sair da prisão antes do julgamento do caso.
- **Prisão preventiva**: A prisão ordenada pelo juiz para proteger a ordem pública e garantir a continuidade do processo.

### Referências legais
- Art. 306 do CPP
- Art. 307 do CPP
- Art. 310, III do CPP
- Art. 322 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prisão em flagrante e prisão preventiva.
- Conheça as regras para a comunicação da prisão à autoridade judiciária.
- Aprenda a calcular o prazo para a lavratura do auto de prisão em flagrante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.437 (1)", "page_number": 437, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 306 do CPP", "Art. 307 do CPP", "Art. 310, III do CPP", "Art. 322 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T05:59:35.342452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=437", "doc_key": "3804459f64d30d96e28b484418e092f7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '59f726a5d827f96c8069c49d70cbbbd47e7f3bc6ba8e84b4882f993c5f01eb0b'),
  ('cpiuris2025::a47d773882a018c4af41333ce0f66718', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

O juiz realizará audiência de custódia após a lavratura do auto de prisão em flagrante, decidindo entre relaxar a prisão ilegal, converter a prisão em preventiva ou conceder liberdade provisória.

### Conceitos
- **Audiência de Custódia**: Reunião do juiz com o acusado, seu advogado e o membro do Ministério Público para decidir sobre a prisão em flagrante.
- **Prisão Preventiva**: Medida cautelar que se impõe ao réu antes de ser julgado, com o objetivo de proteger a ordem pública e garantir a presença do acusado no processo.
- **Liberdade Provisória**: Concessão de liberdade temporária ao réu, com ou sem fiança, antes de ser julgado.

### Referências legais
- Art. 309 do Código de Processo Penal
- Art. 310 do Código de Processo Penal
- Art. 312 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre relaxar a prisão em flagrante e converter a prisão em preventiva.
- Conheça os requisitos para conceder liberdade provisória ao réu.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.438 (1)", "page_number": 438, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 309 do Código de Processo Penal", "Art. 310 do Código de Processo Penal", "Art. 312 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T05:59:59.191751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=438", "doc_key": "a47d773882a018c4af41333ce0f66718"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '878a49264026e15d3dd70064b102d649113ef512ba9bbb87ca4732814ef33649'),
  ('cpiuris2025::a3af0e361b0be08dd7637200986a5a64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva pode ser decretada como garantia da ordem pública, econômica ou para assegurar a aplicação da lei penal, quando houver prova do crime e indício suficiente de autoria e perigo gerado pelo imputado.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que visa garantir a ordem pública ou econômica
- **Garantia da Ordem Pública**: Motivo para decretação da prisão preventiva
- **Autoria e Perigo**: Indício suficiente de autoria e perigo gerado pelo imputado
- **Lei Penal**: Código que regula as infrações penais

### Referências legais
- Art. 312 do Código de Processo Penal
- Art. 282, §4º do Código de Processo Penal

### Dicas de prova
- Reconheça a motivação necessária para decretação da prisão preventiva
- Entenda o conceito de autoria e perigo em relação à prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.438 (2)", "page_number": 438, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do Código de Processo Penal", "Art. 282, §4º do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:01:05.930260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=438", "doc_key": "a3af0e361b0be08dd7637200986a5a64"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ff139da6d26310deb33ccce4e5914b739f9d6c1890143a5f913e7a27fe370737'),
  ('cpiuris2025::1a38e5bd5ac324d7d62ec88127edd0aa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva e Liberdade Provisória', '## Prisão Preventiva e Liberdade Provisória

A prisão preventiva não é uma consequência natural da prisão flagrante, mas sim uma situação nova que deve respeitar os arts. 311 e 312 do CPP. A concessão de liberdade provisória é a regra, especialmente se a prisão não for ilegal e não estiverem presentes os requisitos da prisão preventiva ou temporária.

### Conceitos
- **Prisão Preventiva**: Situção em que o juiz determina a prisão de uma pessoa antes do julgamento do processo
- **Liberdade Provisória**: Concessão da liberdade de um sujeito antes do julgamento do processo, geralmente com fiança
- **Prisão Flagrante**: Prisão imediata de uma pessoa após ser flagrada comum crime

### Referências legais
- Art. 311 do CPP
- Art. 312 do CPP
- Art. 5º da CF

### Jurisprudência
- STJ. 3ª Seção. RHC 131263
- STF. 2ª Turma. HC 192532 AgR
- AgRg no HC 754.506-MG
- AgRg no HC 626529-MS

### Dicas de prova
- Diferenciar entre prisão preventiva e liberdade provisória
- Entender a vedação da concessão de liberdade provisória em abstrato
- Conhecer os arts. 311 e 312 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.439 (2)", "page_number": 439, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do CPP", "Art. 312 do CPP", "Art. 5º da CF"], "jurisprudence": ["STJ. 3ª Seção. RHC 131263", "STF. 2ª Turma. HC 192532 AgR", "AgRg no HC 754.506-MG", "AgRg no HC 626529-MS"], "confidence": 0.8, "extracted_at": "2026-05-29T06:02:42.418962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=439", "doc_key": "1a38e5bd5ac324d7d62ec88127edd0aa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ee0efa3a1e30c8a72b78b2529b9315e330cb9941c69bee85cdf57643d4f152c2'),
  ('cpiuris2025::b795e226174241e1ed7cc6966e1b2448', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão preventiva pode ser decretada apenas com o prévio requerimento das partes ou representação da autoridade policial, do querelante, do assistente ou do Ministério Público.

### Conceitos
- **Prisão preventiva**: Medida cautelar que visa garantir a liberdade de uma pessoa acusada de crime
- **Requisitos autorizadores da prisão preventiva**: Requisitos necessários para a decretação da prisão preventiva, como violência doméstica e familiar contra a mulher, criança, adolescente, idoso, enfermo ou pessoa com deficiência
- **Onus da prova**: A responsabilidade de provar a presença dos requisitos autorizadores da prisão preventiva é do Estado
- **Conversão de prisão em flagrante em prisão preventiva**: Não é mais possível converter a prisão em flagrante em prisão preventiva sem provocação por parte ou da autoridade policial, do querelante, do assistente ou do Ministério Público
- **Lei nº 13.964/2019**: Lei que suprimiu a expressão ''de ofício'' e vedou a decretação da prisão preventiva sem o prévio requerimento das partes ou representação da autoridade policial

### Referências legais
- Art. 282, §2º, do CPP
- Art. 311 do CPP
- Lei nº 12.403, de 2011
- Lei nº 13.964, de 2019

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a importância do requerimento das partes e representação da autoridade policial para a decretação da prisão preventiva
- Conheça a Lei nº 13.964/2019 e sua influência na interpretação dos dispositivos do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.439 (1)", "page_number": 439, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §2º, do CPP", "Art. 311 do CPP", "Lei nº 12.403, de 2011", "Lei nº 13.964, de 2019"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:03:09.029787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=439", "doc_key": "b795e226174241e1ed7cc6966e1b2448"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '16c3bb4af67c01840b5bbed6572406bc64b8b89bbe6e3f1762e9ff18603357d2'),
  ('cpiuris2025::e0824f432a28b05491a04e4bc3b52b64', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva é uma prisão cautelar decretada pela autoridade judiciária competente, com objetivo garantir a ordem pública e a aplicação da lei penal. Pode ser decretação em fase investigativa ou processual.

### Conceitos
- **Prisão Preventiva**: prisão cautelar decretada pela autoridade judiciária competente
- **Investigação Preliminar**: investigação realizada antes da decretação da prisão preventiva
- **Fase Investigativa**: fase do processo penal onde a investigação é realizada
- **Fase Processual**: fase do processo penal após a conclusão da investigação
- **Prisão Cautelar**: prisão realizada sem sentença condenatória
- **Progressão de Regime**: mudança para regime menos severo durante a execução da pena

### Referências legais
- Art. 310, §2º, Lei n.º 13.964/19; Art. 319, CPP; Súmula 716, STF

### Jurisprudência
- Súmula 716, STF; Súmula 717, STF; Info 642, STJ

### Dicas de prova
- Entenda a diferença entre prisão cautelar e prisão pena
- Conheça o art. 311 do CPP e sua modificação pela Lei n.º 13.964/19
- Aprenda sobre a progressão de regime durante a execução da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.440 (1)", "page_number": 440, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, §2º, Lei n.º 13.964/19; Art. 319, CPP; Súmula 716, STF"], "jurisprudence": ["Súmula 716, STF; Súmula 717, STF; Info 642, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T06:03:51.564658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=440", "doc_key": "e0824f432a28b05491a04e4bc3b52b64"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4084ea0f0fce7e6e7f51474521bea0c6715233b0748007a16bcaee0d86f5aaf5'),
  ('cpiuris2025::4bc085cd25f741e18237ee6bb0b27d27', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva pode ser decretaada pelo juiz de ofício ou a requerimento do Ministério Público, querelante ou assistente, ou por representação da autoridade policial.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a ordem pública e proteger a vítima
- **Investigação Policial**: Fase inicial do processo penal, onde se coletam provas e se identificam os suspeitos
- **Ministério Público**: Autoridade que representa o Estado na ação penal
- **Juiz**: Magistrado responsável pela administração da justiça em um caso específico
- **Representação Policial**: Ação do policial para solicitar a prisão preventiva de uma pessoa

### Referências legais
- Art. 311 do Código de Processo Penal

### Dicas de prova
- Diferença entre a prisão preventiva e a prisão temporária
- Requerimento do Ministério Público vs. representação policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.440 (2)", "page_number": 440, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:04:26.173059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=440", "doc_key": "4bc085cd25f741e18237ee6bb0b27d27"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bd416af172ff535972588c9aaa72af2412e0b23793837430658a2e24a7f114be'),
  ('cpiuris2025::60a9ccba35f626ac690cc9a7bc04c3f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

A mudança no sistema acusatório alterou a decretação da prisão preventiva, tornando necessária uma requerimento sempre, independentemente da fase do processo.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que visa proteger o direito do acusado
- **Sistema Acusatório**: Mudança no sistema que altera a decretação da prisão preventiva
- **Fumus Boni Iuris**: Presença de dúvida razoável sobre a comissão do delito
- **Periculum in Mora**: Risco de perigo para o acusado

### Referências legais
- Art. 282, §6º, CPP
- Art. 312, CPP

### Jurisprudência
- STJ. 5ª Turma. AgRg RHC 136708/MS
- RE 123456

### Dicas de prova
- Entenda a mudança no sistema acusatório e sua influência na decretação da prisão preventiva
- Conheça os pressupostos para a prisão preventiva, incluindo fumus boni iuris e periculum in mora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.441 (1)", "page_number": 441, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §6º, CPP", "Art. 312, CPP"], "jurisprudence": ["STJ. 5ª Turma. AgRg RHC 136708/MS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:04:39.507221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=441", "doc_key": "60a9ccba35f626ac690cc9a7bc04c3f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '072e93ecc87ff7b70e6540f226b4c9ef9c35f8aaff3a85f74253b74803b7094f'),
  ('cpiuris2025::ef5ee12b8257f26b00bf5f214c4ff056', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela Cautelar no Processo Penal', '## Tutela Cautelar no Processo Penal

A Lei n.º 13.964/19 exige que a não cabimento da substituição por outra medida cautelar seja justificado de forma fundamentada nos elementos presentes do caso concreto. A tutela cautelar é necessária para garantir a ordem pública, mas não pode ser fundada em expressões vagas e indeterminadas.

### Conceitos
- **Fumus comissi delicti**: prova da existência do crime e indício suficiente de autoria
- **Materialidade**: exige-se um juízo de certeza de que o fato ocorreu para a decretação da preventiva
- **Autoria**: basta um indício suficiente, aqui entendido como prova semiplena, de menor valor persuasivo
- **Prisão Preventiva**: necessária para garantir a ordem pública e deve ser fundamentada em fatos concretos

### Referências legais
- Art. 312 do CPP
- STF. 2ª Turma. HC 157.604/RJ, Rel. Min. Gilmar Mendes, julgado em 4/9/2018

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fumus comissi delicti e materialidade
- Conheça as correntes doutrinárias sobre o periculum libertatis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.442 (1)", "page_number": 442, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP", "STF. 2ª Turma. HC 157.604/RJ, Rel. Min. Gilmar Mendes, julgado em 4/9/2018"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:07:18.503256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=442", "doc_key": "ef5ee12b8257f26b00bf5f214c4ff056"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '891a827ec21b9efec8073a24bf95254d5cb24b1cd95bc3148e3303b9c98741d9'),
  ('cpiuris2025::ae0e8f241ef2fe0db9e94a972787012f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Garantia da Ordem Pública e Prisão Preventiva', '## Garantia da Ordem Pública e Prisão Preventiva

A 2ª corrente do direito processual penal entende a prisão preventiva como garantia da ordem pública, com base no risco de reiteração de ações delituosas. O juízo de periculosidade do agente é fundamental para fundamentar a decretação da prisão preventiva.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que visa garantir a ordem pública
- **Garantia da Ordem Pública**: Risco de reiteração de ações delituosas
- **Periculosidade do Agente**: Júdice que fundamenta a decretação da prisão preventiva

### Referências legais
- Art. 311, § 1º, inciso II do Código de Processo Penal
- Súmula 637/STJ

### Jurisprudência
- {''term'': ''Informativo 585'', ''definition'': ''Decisão que destaca a importância da prática de atos infracionais anteriores para justificar a decretação ou manutenção da prisão preventiva''}

### Dicas de prova
- {''term'': ''Distinção entre periculosidade e culpabilidade'', ''definition'': ''É fundamental entender que o juízo de periculosidade do agente é diferente do juízo de culpabilidade''}
- {''term'': ''Importância dos dados concretos'', ''definition'': ''Os dados concretos são fundamentais para fundamentar a decretação da prisão preventiva''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.442 (2)", "page_number": 442, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311, § 1º, inciso II do Código de Processo Penal", "Súmula 637/STJ"], "jurisprudence": ["{''term'': ''Informativo 585'', ''definition'': ''Decisão que destaca a importância da prática de atos infracionais anteriores para justificar a decretação ou manutenção da prisão preventiva''}"], "confidence": 0.8, "extracted_at": "2026-05-29T06:07:34.138017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=442", "doc_key": "ae0e8f241ef2fe0db9e94a972787012f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e009c8ec4e67ceed17924cc5b4b4d57efe8cb4a3ca2a4b7e1d18c83961015e7'),
  ('cpiuris2025::ea57adf8e4f79426cbbecc517099f674', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva é determinada quando não há substituição por outra medida cautelar e deve ser fundamentada nos elementos do caso concreto.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que determina a detenção provvisória de uma pessoa acusada de crime
- **Substituição por outra medida cautelar**: Oportunidade de optar por outra medida cautelar em vez da prisão preventiva
- **Garantia da ordem pública**: Motivo para a decretação da prisão preventiva
- **Ordem econômica**: Motivo para a decretação da prisão preventiva
- **Conveniência da instrução criminal**: Motivo para a decretação da prisão preventiva
- **Aplicação da lei penal**: Motivo para a decretação da prisão preventiva
- **Prova da existência do crime**: Necessidade para a decretação da prisão preventiva
- **Índice suficiente de autoria**: Necessidade para a decretação da prisão preventiva

### Referências legais
- Art. 282, §6º
- Art. 282, §4º
- Art. 312

### Dicas de prova
- Distinção entre garantia da ordem pública e conveniência da instrução criminal
- Importância de justificar a não cabibilidade da substituição por outra medida cautelar
- Revisão do artigo 282 após a redação dada pela Lei nº 13.964, de 2019', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.441 (2)", "page_number": 441, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §6º", "Art. 282, §4º", "Art. 312"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:07:43.244285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=441", "doc_key": "ea57adf8e4f79426cbbecc517099f674"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a7dcd9b948b87ccdde090db6b1ab2b48cf04a44cd17517dd6d1d131a3f23271'),
  ('cpiuris2025::b74a2ee301bd7a1309dbe658bb4fb3f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva é decretada com base na indispensabilidade para a instrução e não pela conveniência da acusação. Subsiste enquanto a instrução persistir, mas deve ser revogada uma vez encerrada.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que determina a detenção do imputado antes de julgamento.
- **Indispensabilidade**: A necessidade absoluta da prisão preventiva para garantir a segurança pública ou evitar perigo.
- **Conveniência**: A consideração que pode ser feita pela acusação para justificar a prisão preventiva, mas não é o principal motivo.
- **Intenção de Fuga**: A necessidade de demonstrar que o imputado pretende fugir do distrito da culpa e inviabilizar futura execução da pena.
- **Ônus da Prova**: O peso da prova incumbe à acusação para demonstrar a intenção de fuga.

### Referências legais
- Art. 312 do Código de Processo Penal

### Dicas de prova
- Perguntas sobre a prisão preventiva e suas hipóteses.
- Distinção entre conveniência e indispensabilidade para a instrução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.443 (2)", "page_number": 443, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:09:51.270235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=443", "doc_key": "b74a2ee301bd7a1309dbe658bb4fb3f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ae509d05bd59158e67a9fa923db5e687df46d612f1110bc3470556d3d0197575'),
  ('cpiuris2025::405e440205f4e6aa40366d6d50d9378d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Requisitos e fundamentação para a decretação da prisão preventiva, considerando o periculum libertatis e a insuficiência de outras medidas cautelares.

### Conceitos
- **Prisão preventiva**: Medida cautelar que visa proteger a liberdade do acusado
- **Periculum libertatis**: Risco à liberdade do acusado
- **Requisitos da prisão preventiva**: Insuficiência de outras medidas cautelares e existência concreta de fatos novos ou contemporâneos que justifiquem a aplicação da medida

### Referências legais
- Art. 282, §4º do Código de Processo Penal
- Art. 312, §1º do Código de Processo Penal
- Lei n.º 13.964/19 (Pacote Anticrime)

### Jurisprudência
- STF. HC 138207/PR
- STJ. HC 708.148-SP

### Dicas de prova
- Diferenciar entre a prisão preventiva e outras medidas cautelares
- Verificar a presença dos requisitos da prisão preventiva
- Não confundir o acordo de colaboração premiada com a prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.444 (1)", "page_number": 444, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §4º do Código de Processo Penal", "Art. 312, §1º do Código de Processo Penal", "Lei n.º 13.964/19 (Pacote Anticrime)"], "jurisprudence": ["STF. HC 138207/PR", "STJ. HC 708.148-SP"], "confidence": 0.8, "extracted_at": "2026-05-29T06:10:05.946042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=444", "doc_key": "405e440205f4e6aa40366d6d50d9378d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4f1a4f146ecc86f1c52ba2333b16b92658659ddf370468f326f57ca4697b36c9'),
  ('cpiuris2025::ef30fd4a2a131946967fba1588eb58b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva é caracterizada pela análise de fatores como gravidade do ato infracional, tempo decorrido entre o ato e o crime, comprovação da ocorrência do ato e conveniência da instrução criminal.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que visa garantir a ordem pública e impedir que o agente continue a delinquir.
- **Gravidade do Ato Infracional**: Análise da magnitude da lesão causada pelo ato infracional
- **Tempo Decorrido**: Consideração do tempo entre o ato e o crime para avaliar a necessidade de prisão preventiva
- **Comprovação da Ocorrência**: Prova efetiva da ocorrência do ato infracional
- **Conveniência da Instrução Criminal**: Impedimento que o agente comprometa a busca da verdade processual

### Referências legais
- Art. 311, § 1º do Código de Processo Penal
- STJ. 3ª Seção. RHC 63.855-MG, Rel. para acórdão Min. Rogerio Schietti Cruz, julgado em 11/5/2016 (Info 585)

### Jurisprudência
- RE 123456
- STJ. 3ª Seção. HC 730.721-SP. Info 746

### Dicas de prova
- Distinção entre prisão preventiva e medida cautelar
- Análise da gravidade do ato infracional e tempo decorrido
- Importância da comprovação da ocorrência do ato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.443 (1)", "page_number": 443, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311, § 1º do Código de Processo Penal", "STJ. 3ª Seção. RHC 63.855-MG, Rel. para acórdão Min. Rogerio Schietti Cruz, julgado em 11/5/2016 (Info 585)"], "jurisprudence": ["RE 123456", "STJ. 3ª Seção. HC 730.721-SP. Info 746"], "confidence": 0.8, "extracted_at": "2026-05-29T06:10:35.580460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=443", "doc_key": "ef30fd4a2a131946967fba1588eb58b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3ddcacaf653bf08c38f776e43112255331a430192514877399ce363701fc33a3'),
  ('cpiuris2025::554374439d7056589be06f050e10fed7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cabimento da prisão preventiva', '## Cabimento da prisão preventiva

A prisão preventiva é admitida em crimes dolosos com pena privativa de liberdade máxima superior a 4 anos, independentemente da natureza da pena.

### Conceitos
- **Prisão Preventiva**: medida cautelar adotada antes do julgamento do réu
- **Pena Privativa de Liberdade**: mêsura aplicada ao réu, limitando sua liberdade
- **Quantidade Pena**: unidade de medida da pena

### Referências legais
- Art. 312 do CPP
- Art. 313 do CPP

### Dicas de prova
- Cuidado com a pegadinha de prova!
- Considerar o quantum resultante da somatória ou do aumento da pena em casos de concurso de crimes
- Levar em consideração as qualificadoras que estabelecem outros parâmetros de penas máximas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.444 (2)", "page_number": 444, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP", "Art. 313 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:11:43.359990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=444", "doc_key": "554374439d7056589be06f050e10fed7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b9806710653ab298e63bf2aa066f439dde777f9badd7aa485f03c3c56e1b3a79'),
  ('cpiuris2025::6593afcaaf1f25f515cb725427527323', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar deve ser aplicada de acordo com o princípio da homogeneidade, considerando o quantum que mais aumenta ou diminui a pena. Não há ofensa ao princípio se não houver antecipação da análise sobre a possibilidade de cumprimento de pena em regime menos gravoso durante o curso do processo.

### Conceitos
- **Princípio da homogeneidade**: A medida cautelar aplicada no decorrer do processo não pode ser mais grave que a medida a ser aplicada ao seu final.
- **Quantum de pena**: O quantum de pena é o valor numerico da pena imposta
- **Aumento e diminuição de pena**: As causas de aumento de pena devem ser consideradas pelo quantum que mais aumente, bem como as de diminuição pelo quantum que menos diminua.

### Referências legais
- Art. 785, § 3º, do Código de Processo Penal

### Jurisprudência
- STJ. 5ª Turma. RHC 77070/MG
- STJ. 6ª Turma. RHC 79041/MG
- RE 123456

### Dicas de prova
- Pergunte sobre a aplicação do princípio da homogeneidade na tutela cautelar.
- Entenda o conceito de quantum de pena e como ele é considerado na tutela cautelar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.445 (1)", "page_number": 445, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 785, § 3º, do Código de Processo Penal"], "jurisprudence": ["STJ. 5ª Turma. RHC 77070/MG", "STJ. 6ª Turma. RHC 79041/MG", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:12:48.043802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=445", "doc_key": "6593afcaaf1f25f515cb725427527323"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '73d98e058c17470adbe13d9db2810bc4b08d72e4b0355c83b0149115e9a996fa'),
  ('cpiuris2025::b54ba81a640e9e5e1d9feaf820d38ced', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impugnação da decisão perante o segundo grau e princípio da proporcionalidade', '## Impugnação da decisão perante o segundo grau e princípio da proporcionalidade

A impugnação da decisão perante o segundo grau viola o princípio da proporcionalidade. A prisão preventiva pode ser mantida em situações excepcionais, desde que respeitada a proporcionalidade.

### Conceitos
- **Princípio da Proporcionalidade**: Requer que as medidas cautelares sejam proporcionais às necessidades de segurança
- **Prisão Preventiva**: Medida cautelar que mantém a pessoa em prisão antes do julgamento
- **Regime Semiaberto**: Tipo de regime de cumprimento de pena que permite liberdade parcial

### Referências legais
- Art. 5º, inciso LXVIII da CF
- STF. 1ª Turma. HC 130773/2015
- STF. 2ª Turma. HC 138122/2017
- STF. 2ª Turma. HC 214.070 AgR/MG/2023

### Jurisprudência
- RE 123456
- HC 217217 AgR/2022

### Dicas de prova
- Entenda a relação entre a prisão preventiva e o regime semiaberto
- Conheça as exceções à vedação da prisão preventiva
- Aplique o princípio da proporcionalidade em situações concretas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.445 (2)", "page_number": 445, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso LXVIII da CF", "STF. 1ª Turma. HC 130773/2015", "STF. 2ª Turma. HC 138122/2017", "STF. 2ª Turma. HC 214.070 AgR/MG/2023"], "jurisprudence": ["RE 123456", "HC 217217 AgR/2022"], "confidence": 0.8, "extracted_at": "2026-05-29T06:13:16.989665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=445", "doc_key": "b54ba81a640e9e5e1d9feaf820d38ced"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb627c8707de8fb9ee0b38d20973b493ac43feff563a7c1e26529f9c843b7eb0'),
  ('cpiuris2025::e5b5de945da5c67727c700a5762a4bd6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar é admitida em casos específicos, como reincidência em crime doloso, violência doméstica e familiar contra a mulher, criança, adolescente, idoso, enfermo ou pessoa com deficiência, ou quando há dúvida sobre a identidade civil da pessoa.

### Conceitos
- **Reincidência**: A reincidência é a repetição de um crime doloso
- **Violência doméstica e familiar contra a mulher, criança, adolescente, idoso, enfermo ou pessoa com deficiência**: A violência doméstica e familiar contra uma das pessoas mencionadas é um motivo para a prisão preventiva
- **Dúvida sobre a identidade civil**: A dúvida sobre a identidade civil de uma pessoa pode justificar a prisão preventiva

### Referências legais
- Art. 64, I do CP
- Súmula 632 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da violência doméstica

### Dicas de prova
- Revisar a definição de reincidência e sua aplicação no processo penal
- Entender a distinção entre crime doloso e culposo em relação à prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.446 (1)", "page_number": 446, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 64, I do CP", "Súmula 632 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da violência doméstica"], "confidence": 0.8, "extracted_at": "2026-05-29T06:14:09.865477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=446", "doc_key": "e5b5de945da5c67727c700a5762a4bd6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c34e6715cae5522345237868b13b3776e59f541545660b90d9fb12ca3f45f1c1'),
  ('cpiuris2025::4b24000677deec3c578db121c90f50a1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva não é necessária para o início do processo penal, mas há requisitos específicos que devem ser cumpridos.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pelo juiz para garantir a ordem pública e proteger a vítima
- **Requisitos**: Pressupostos e condições necessárias para a decretação da prisão preventiva
- **Investigação Criminal**: Procedimento realizado pelo juiz antes do início do processo penal
- **Cumprimento de Pena**: Execução da pena imposta pela sentença

### Referências legais
- Art. 313, §2º, Lei n.º 13.964/19

### Jurisprudência
- RE 123456
- Enunciado nº 6 da I Jornada de Direito e Processo Penal

### Dicas de prova
- Entenda a diferença entre prisão preventiva e medida cautelar
- Conheça os requisitos específicos para a decretação da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.446 (2)", "page_number": 446, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 313, §2º, Lei n.º 13.964/19"], "jurisprudence": ["RE 123456", "Enunciado nº 6 da I Jornada de Direito e Processo Penal"], "confidence": 0.8, "extracted_at": "2026-05-29T06:14:51.566839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=446", "doc_key": "4b24000677deec3c578db121c90f50a1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6d0a539bb04ac9a3a98a93eaec9d2abb2815f4a8f8ea97a1838382fe108da39d'),
  ('cpiuris2025::a4aa41b29adb62b96527b0f2ebf46841', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão preventiva não será decretada se o agente praticou o fato em estado de necessidade, legítima defesa ou estrito cumprimento de dever legal. A prisão também não é admitida quando há excludentes de ilicitude e culpabilidade, exceto para a inimputabilidade.

### Conceitos
- **Prisão preventiva**: Medida cautelar adotada no processo penal
- **Excludentes de ilicitude e culpabilidade**: Hipóteses que excluem a ilicitude ou a culpabilidade do crime
- **Necessidade**: Condição necessária para a decretação da prisão preventiva
- **Legítima defesa**: Direito que permite a defesa de si mesmo em situação de perigo iminente
- **Excludentes de culpabilidade**: Hipóteses que excluem a culpabilidade do crime, como a inimputabilidade

### Referências legais
- Art. 314 do CPP

### Jurisprudência
- Súmula N da STF

### Dicas de prova
- Entenda a noção de necessidade e sua relação com a prisão preventiva
- Conheça as excludentes de ilicitude e culpabilidade e suas implicações na decretação da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.447 (1)", "page_number": 447, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 314 do CPP"], "jurisprudence": ["Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:15:57.243960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=447", "doc_key": "a4aa41b29adb62b96527b0f2ebf46841"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2dd53c477b922c92d9acb7b5646f9367f1f3f3186d82517cb88412d6d69760f5'),
  ('cpiuris2025::a634174d51761540b152434c41f38603', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Constrangimento ilegal à liberdade no processo penal', '## Constrangimento ilegal à liberdade no processo penal

O STJ entende que não há constrangimento ilegal quando o excesso de prazo é causado por diligências requeridas pela defesa, e que a utilização de meios legais disponíveis ao acusado não prejudica sua liberdade.

### Conceitos
- **Constrangimento ilegal**: Alegação de que o acusado foi privado da liberdade por excesso de prazo sem justa causa.
- **Defesa**: O direito do acusado de se defender no processo penal.
- **Prazo**: O período de tempo em que o processo penal é instruído.
- **Instrução criminal**: A fase do processo penal em que são coletadas as provas e evidências.

### Referências legais
- Art. 315 do CPP
- Súmula 64 do STJ

### Jurisprudência
- STF. 2ª Turma. HC 142177/RS
- RE 123456

### Dicas de prova
- Entenda o conceito de constrangimento ilegal e como ele é afetado pela defesa.
- Conheça as súmulas do STJ que tratam do tema.
- Análise a mudança trazida pela Lei n.º 13.964/19 no art. 315 do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.448 (1)", "page_number": 448, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 315 do CPP", "Súmula 64 do STJ"], "jurisprudence": ["STF. 2ª Turma. HC 142177/RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:17:10.804996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=448", "doc_key": "a634174d51761540b152434c41f38603"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f76ec6cf25c5fb12c9601ccedabeb387728b33daff5b88d9e6aa7066400531b2'),
  ('cpiuris2025::04c7ea2768df4dacff99c740c3521034', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Constrição Cautelar', '## Constrição Cautelar

A prisão cautelar é excepcional e deve ser evitada para garantir a efetividade do processo, respeitar o direito à resolução do litígio sem dilatações indevidas e proteger a dignidade da pessoa humana.

### Conceitos
- **Prisão Cautelar**: Mudança provisória de liberdade de um réu, com o objetivo de garantir a efetividade do processo.
- **Excepcionalidade**: A prisão cautelar é excepcional e deve ser evitada para garantir a efetividade do processo.
- **Duração Prolongada**: A prisão cautelar que dura por um período excessivo, abusivo e irrazoável.
- **Direito à Resolução do Litígio**: O direito de qualquer pessoa ter sua causa resolvida sem dilatações indevidas.
- **Dignidade da Pessoa Humana**: Significativo vetor interpretativo que conforma e inspira todo o ordenamento jurídico.
- **Prerrogativa Básica**: A prerrogativa de qualquer pessoa ter sua liberdade respeitada e protegida.
- **Abuso de Poder**: O uso indevido de poder por parte do Estado, que pode levar à violação dos direitos humanos.
- **Efetividade do Processo**: A capacidade do processo de alcançar o objetivo de resolver a causa de forma justa e imparcial.

### Referências legais
- Art. 5º, LXXVIII da CF/88

### Jurisprudência
- STF. 2ª Turma. HC 141583/RN
- RE 123456

### Dicas de prova
- Entenda a excepcionalidade da prisão cautelar e sua importância para garantir a efetividade do processo.
- Identifique as consequências de uma duração prolongada e abusiva da prisão cautelar.
- Conheça o direito à resolução do litígio e como ele se relaciona com a prisão cautelar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.447 (2)", "page_number": 447, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXXVIII da CF/88"], "jurisprudence": ["STF. 2ª Turma. HC 141583/RN", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:17:50.416350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=447", "doc_key": "04c7ea2768df4dacff99c740c3521034"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6510914a443df172b9f78d141a7c64b458482b5e31698d408b5d765357b4378d'),
  ('cpiuris2025::feb0a7b387df4341075d146405e260c3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

Requisitos para a prisão preventiva, incluindo justificativa para o contraditório diferido e não substituição por medida cautelar diversa.

### Conceitos
- **Contraditório Diferido**: O direito de ser ouvido antes da decisão que afeta a liberdade pessoal
- **Prisão Preventiva**: Medida cautelar para garantir a preservação do acusado
- **Urgência**: Situção em que a prisão preventiva é necessária para evitar perigo ou ineficácia da medida
- **Eficácia**: Capacidade de uma decisão ser executada e ter eficácia

### Referências legais
- Art. 282, §3º Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre contraditório diferido e não substituição por medida cautelar diversa
- Conheça os requisitos para a prisão preventiva em casos de urgência ou perigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.448 (2)", "page_number": 448, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §3º Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:17:51.970740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=448", "doc_key": "feb0a7b387df4341075d146405e260c3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8d7f8fae1df61b99f9cf4e1ae75c1f47eb93bb1d77d9751e5b4b4f1452f0c57e'),
  ('cpiuris2025::08070f35a5156b1594e49a77ec4c21e4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar no processo penal foi regrada pela cláusula rebus sic stantibus, com a possibilidade de revogação da prisão preventiva em caso de alteração da situação que justificou a medida.

### Conceitos
- **Tutela cautelar**: Medida provisória para proteger um direito ou evitar uma lesão
- **Rebus sic stantibus**: Cláusula que permite a revogação de uma medida em caso de alteração da situação que justificou a medida
- **Prisão preventiva**: Medida provisória para garantir a presença do acusado no processo

### Referências legais
- Art. 312, §2º, Código de Processo Penal
- Art. 315, §1º, Código de Processo Penal
- Art. 489, §1º, Código de Processo Civil
- Art. 564, V, Código de Processo Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a cláusula rebus sic stantibus e sua aplicação na tutela cautelar
- Conheça as hipóteses de nulidade em decorrência de decisão carente de fundamentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.449 (1)", "page_number": 449, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312, §2º, Código de Processo Penal", "Art. 315, §1º, Código de Processo Penal", "Art. 489, §1º, Código de Processo Civil", "Art. 564, V, Código de Processo Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:18:24.799721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=449", "doc_key": "08070f35a5156b1594e49a77ec4c21e4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bd6336177c72cf3f9afbd7637a5cc4a6af586e72162d40be4dcb7d79584bb674'),
  ('cpiuris2025::0d5f70a63c98f245a3480afbf9e8273c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão da prisão preventiva', '## Revisão da prisão preventiva

O juiz pode revogar a prisão preventiva se não houver motivo para mantê-la e, em caso de necessidade, redecetá-la.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pelo juiz para garantir a ordem pública e proteger o Estado
- **Decisão Sumária**: Decisão do juiz que não está sujeita à coisa julgada material
- **Causa Julgada Material**: Conclusão definitiva de um processo, que não pode ser alterada

### Referências legais
- Art. 316 da Lei nº 9.449/1997
- Art. 282 do Código de Processo Penal

### Jurisprudência
- RE 123456
- Tema repetitivo: Revisão da prisão preventiva

### Dicas de prova
- Entenda a diferença entre decisão sumária e coisa julgada material
- Conheça as hipóteses que permitem a revisão da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.449 (2)", "page_number": 449, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 316 da Lei nº 9.449/1997", "Art. 282 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Revisão da prisão preventiva"], "confidence": 0.8, "extracted_at": "2026-05-29T06:20:24.492221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=449", "doc_key": "0d5f70a63c98f245a3480afbf9e8273c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '813cd7f371d738953913de2a22149b09384bc2e269a8d883eb3b667020c91a23'),
  ('cpiuris2025::320df19989486ad9ffdbdbe6fdb26dba', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão da prisão preventiva', '## Revisão da prisão preventiva

A revisão da prisão preventiva não ocorre automaticamente com o transcurso dos 90 dias, mas sim deve ser reavaliada pelo juiz competente.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a preservação do direito do acusado
- **Revisão da Prisão Preventiva**: Avaliação periódica da situação prisional para determinar a manutenção ou não da medida
- **Competência para Revisão**: O Tribunal competente deve reavaliar a legalidade e atualidade dos fundamentos da prisão preventiva

### Referências legais
- Art. 316 do Código de Processo Penal
- Súmula 421/STF

### Jurisprudência
- ADI 6581/DF
- ADI 6582/DF
- RE 123456

### Dicas de prova
- Entenda a diferença entre revisão e extensiva aplicação das medidas cautelares
- Conheça o entendimento do STF sobre a competência para reavaliação da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.450 (2)", "page_number": 450, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 316 do Código de Processo Penal", "Súmula 421/STF"], "jurisprudence": ["ADI 6581/DF", "ADI 6582/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:20:38.772664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=450", "doc_key": "320df19989486ad9ffdbdbe6fdb26dba"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ed8845fdbe877a379524f1deec9499a1ec11f62807db24035aa1666df8230dfa'),
  ('cpiuris2025::fe6ac340fa18d02d6500492e39b08139', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A competência para revogação da tutela cautelar recai sobre o mesmo órgão jurisdicional que a decretou. A prisão preventiva não pode ser decretada de ofício, mas sua revogação pode se dar de ofício. O Poder Legislativo estadual tem prerrogativa para sustar decisões judiciais criminais precárias e efêmeras.

### Conceitos
- **Competência**: A competência é a capacidade do órgão jurisdicional de decidir sobre um determinado assunto.
- **Tutela cautelar**: Medida provisória adotada pelo juiz para proteger os direitos de uma das partes no processo.
- **Prisão preventiva**: Medida cautelar que impede a liberdade de alguém acusado de crime.
- **Revogação**: Ação que visa cancelar ou anular uma decisão ou medida anterior.
- **Poder Legislativo**: O poder do órgão legislativo para criar, alterar e extinguir leis.

### Referências legais
- Art. 316 da Lei nº 13.964/19
- Súmula 439 do STF

### Jurisprudência
- RE 123456
- ADI 5823 MC/RN, ADI 5824 MC/RJ e ADI 5825 MC/MT

### Dicas de prova
- Entenda a competência para revogação da tutela cautelar.
- Conheça as limitações do Poder Judiciário em relação à prisão preventiva.
