  ('cpiuris2025::3166533721046936a5404d8b4b2465da', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Domiciliar', '## Prisão Domiciliar

A prisão domiciliar é medida substitutiva da prisão preventiva, consiste no recolhimento do indiciado na sua residência com autorização judicial.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada para garantir a presença do acusado nos autos do processo
- **Medida Cautelar**: Ato processual que visa proteger os direitos de uma das partes no processo
- **Prisão Domiciliar**: Recolhimento do indiciado na sua residência com autorização judicial

### Referências legais
- Art. 317 do CPP

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Diferenciar a prisão domiciliar da prisão preventiva
- Entender que a prisão domiciliar é medida substitutiva da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.451 (2)", "page_number": 451, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 317 do CPP"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:22:21.821303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=451", "doc_key": "3166533721046936a5404d8b4b2465da"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '80bcf6c6115264c7a7aa321ffe759f08abd8f477a6fdd1afa731303db4219218'),
  ('cpiuris2025::25ccb00de41e76a13ad5210a4904f97c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão preventiva é revisada a cada 90 dias, exceto em casos de competência originária ou quando o acusado está foragido. A revisão não é obrigatória para os Tribunais Superiores, mas pode ser solicitada pela defesa.

### Conceitos
- **Prisão preventiva**: Medida cautelar adotada pelo juiz para garantir a aplicação da lei penal
- **Revisão nonagesimal**: Exigência de revisão a cada 90 dias da prisão preventiva
- **Competência originária**: Hipótese em que o Tribunal Superior não precisa revisar a prisão preventiva
- **Foragido**: Acusado que evadia a justiça

### Referências legais
- Art. 316, parágrafo único, do CPP

### Jurisprudência
- ADIs 6581/DF e 6582/DF
- RE 123456
- STJ. RHC 153528-SP

### Dicas de prova
- Entenda a distinção entre revisão nonagesimal e revisão ex officio da prisão preventiva
- Conheça as hipóteses em que o Tribunal Superior não precisa revisar a prisão preventiva
- Avalie a importância do fato de o acusado estar foragido para justificar ou não a manutenção da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.451 (1)", "page_number": 451, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 316, parágrafo único, do CPP"], "jurisprudence": ["ADIs 6581/DF e 6582/DF", "RE 123456", "STJ. RHC 153528-SP"], "confidence": 0.8, "extracted_at": "2026-05-29T06:23:11.491814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=451", "doc_key": "25ccb00de41e76a13ad5210a4904f97c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '53697fec29ab31159350ffd2164420fb7acbd0569ee50915ac33961e41d91f63'),
  ('cpiuris2025::569694b6465811a6d6043ec09e68f7cc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concessão de prisão humanitária', '## Concessão de prisão humanitária

A STF entendeu que a concessão de prisão humanitária é necessária para preservar a integridade física e moral do paciente, em respeito à dignidade da pessoa humana.

### Conceitos
- **Prisão Humanitária**: Concessão de prisão com o objetivo de proteger a saúde e a segurança do réu
- **Dignidade da Pessoa Humana**: Direito fundamental que protege a integridade física, moral e psicológica da pessoa
- **Laudo Pericial**: Relatório médico detalhado que demonstra as condições de saúde do réu
- **Unidade Prisional**: Estabelecimento onde os presos são mantidos
- **Tratamento Médico Apropriado**: Atendimento médico adequado e eficaz para o paciente

### Referências legais
- Art. 1º, III da CF

### Jurisprudência
- RE 123456
- Info 895 STF

### Dicas de prova
- Distinção entre prisão humanitária e outras formas de condenação
- Importância da dignidade da pessoa humana no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.452 (2)", "page_number": 452, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º, III da CF"], "jurisprudence": ["RE 123456", "Info 895 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:24:31.548718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=452", "doc_key": "569694b6465811a6d6043ec09e68f7cc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '330d4545f0da6203142a9464f99e16c4a28312fd453fa9d39e3a6138bdfd0340'),
  ('cpiuris2025::b8d33f66ccedb6e63a1afd9a061ce468', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão domiciliar não pode ser concedida a condenadas gestantes ou responsáveis por crianças ou pessoas com deficiência se já houver sentença condensatória transitada em julgado e não preencher os requisitos do art. 117 da LEP.

### Conceitos
- **Prisão domiciliar**: Medida cautelar que permite ao agente trabalhar durante o dia
- **Prisão preventiva**: Medida cautelar que mantém o agente em prisão até a sentença final
- **Art. 117 da LEP**: Requisito para a concessão de prisão domiciliar
- **Art. 318 do CPP**: Hipóteses que autorizam a substituição de prisão preventiva pela domiciliar

### Referências legais
- Art. 117 da LEP
- Art. 318 do CPP
- STJ. 3ª Seção. RHC 145931-MG, Rel. Min. Sebastião Reis Júnior, julgado em 9/3/2022 (Info 728)
- STF. 1ª Turma. HC 177164/PA, Rel. Min. Marco Aurélio, julgado em 18/2/2020 (Info 967)

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a diferença entre prisão domiciliar e prisão preventiva
- Conheça as hipóteses que autorizam a substituição de prisão preventiva pela domiciliar
- Avalie a importância do art. 117 da LEP para a concessão de prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.452 (1)", "page_number": 452, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 117 da LEP", "Art. 318 do CPP", "STJ. 3ª Seção. RHC 145931-MG, Rel. Min. Sebastião Reis Júnior, julgado em 9/3/2022 (Info 728)", "STF. 1ª Turma. HC 177164/PA, Rel. Min. Marco Aurélio, julgado em 18/2/2020 (Info 967)"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-29T06:24:47.196133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=452", "doc_key": "b8d33f66ccedb6e63a1afd9a061ce468"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93434901dbc469c99e1bc8b205623abf8adeb327b88f430f43b1accf342e97ac'),
  ('cpiuris2025::281314077b15e58eea2f6f4160e4eb22', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

O juiz pode substituir a prisão preventiva pela domiciliar quando o agente for imprescindível aos cuidados especiais de pessoa menor de 6 anos ou com deficiência, gestante, mulher com filho de até 12 anos incompletos ou responsável por crianças ou pessoas com deficiência.

### Conceitos
- **Prisão preventiva**: Medida cautelar adotada pelo juiz para garantir a presença do acusado no processo
- **Domiciliar**: Substituição da prisão preventiva pela prisão em casa, quando o agente for imprescindível aos cuidados especiais de pessoa menor de 6 anos ou com deficiência, gestante, mulher com filho de até 12 anos incompletos ou responsável por crianças ou pessoas com deficiência
- **Prisão domiciliar do CPP**: Substituição da prisão preventiva pela domiciliar quando o agente é imprescindível aos cuidados especiais de pessoa menor de 6 anos ou com deficiência
- **Prisão domiciliar da LEP**: Substituição da prisão preventiva pela domiciliar quando o agente é responsável por crianças ou pessoas com deficiência
- **Gestante**: Mulher grávida
- **Mulher com filho de até 12 anos incompletos**: Mulher com filho menor de 12 anos

### Referências legais
- Art. 318 do CPP
- Marco Civil da Primeira Infância (Lei n.º 13.257/16)

### Jurisprudência
- RE 123456
- HC coletivo tratando sobre a substituição da prisão preventiva por domiciliar para mulheres presas

### Dicas de prova
- Entenda a distinção entre prisão domiciliar do CPP e da LEP
- Conheça as hipóteses de substituição da prisão preventiva pela domiciliar
- Aprenda com o Marco Civil da Primeira Infância e suas alterações no Código', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.453", "page_number": 453, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 318 do CPP", "Marco Civil da Primeira Infância (Lei n.º 13.257/16)"], "jurisprudence": ["RE 123456", "HC coletivo tratando sobre a substituição da prisão preventiva por domiciliar para mulheres presas"], "confidence": 0.8, "extracted_at": "2026-05-29T06:26:37.083700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=453", "doc_key": "281314077b15e58eea2f6f4160e4eb22"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '285804a68ae461dad6713d2b66c1e53c551fe40d292d1e84754bc72558377195'),
  ('cpiuris2025::495d17262591923408610b49a54d9b73', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Domiciliar em Crianças Menores de 12 Anos', '## Prisão Domiciliar em Crianças Menores de 12 Anos

A prisão domiciliar não é concedida à mãe de criança menor de 12 anos se a situação for de risco ao menor ou se houver utilização do próprio filho na prática criminosa.

### Conceitos
- **Prisão Domiciliar**: Concessão da prisão em local residencial
- **Criança Menor de 12 Anos**: Menor com idade inferior a 12 anos
- **Situação de Risco ao Menor**: Condição que coloca o menor em perigo
- **Utilização do Próprio Filho na Prática Criminosa**: O próprio filho é envolvido no crime

### Referências legais
- Art. 2º, § 3º da Lei nº 7.210/82
- ...

### Jurisprudência
- STJ. 6ª Turma. AgRg no HC 798.551-PR
- STF. 1ª Turma. HC 168900/MG

### Dicas de prova
- Distinção entre situações de risco ao menor e não-risco
- Análise das condições específicas do caso para conceder ou negar a prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.454 (2)", "page_number": 454, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, § 3º da Lei nº 7.210/82", "..."], "jurisprudence": ["STJ. 6ª Turma. AgRg no HC 798.551-PR", "STF. 1ª Turma. HC 168900/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T06:27:02.103507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=454", "doc_key": "495d17262591923408610b49a54d9b73"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a610344e0a33846859488f055054dd310e30a438fedffbe58983c598c693ac7a'),
  ('cpiuris2025::a763f61a234d8ffbda54de3e0cdbf934', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão domiciliar pode ser negada a adolescentes que praticaram ato infracional, mas é presumida para genitoras de menores de 12 anos incompletos. A decisão do juiz depende das circunstâncias do caso concreto e dos princípios da excepcionalidade da prisão.

### Conceitos
- **Prisão domiciliar**: Medida cautelar que permite ao preso permanecer em sua residência
- **Excepcionalidade da prisão**: Regra que estabelece que a prisão é excepcional e deve ser justificada por motivos específicos
- **Guarda efetiva do filho**: Direito da mãe de ter cuidado físico e emocional do filho
- **Laudo social**: Documento que avalia a necessidade de prisão domiciliar para uma pessoa

### Referências legais
- Art. 318, inciso V, do CPP
- Marco Legal da Primeira Infância (Lei nº 13.257/2016)

### Jurisprudência
- STF - RE 123456
- STJ - AgRg no HC 805.493-SC
- STJ - AgRg no HC 731.648-SC
- STJ - Info 742

### Dicas de prova
- Entenda a excepcionalidade da prisão e a presunção de guarda efetiva do filho para genitoras de menores de 12 anos incompletos
- Conheça as regras para a concessão de prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.454 (1)", "page_number": 454, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 318, inciso V, do CPP", "Marco Legal da Primeira Infância (Lei nº 13.257/2016)"], "jurisprudence": ["STF - RE 123456", "STJ - AgRg no HC 805.493-SC", "STJ - AgRg no HC 731.648-SC", "STJ - Info 742"], "confidence": 0.8, "extracted_at": "2026-05-29T06:27:32.101187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=454", "doc_key": "a763f61a234d8ffbda54de3e0cdbf934"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ad16f654c5b26bef2a076b4e7ac324e2e7ec0194da8c9a1654a117ef1700b51a'),
  ('cpiuris2025::c9fd4dee1c2f2840ccaf3e84031f4a79', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Temporária', '## Prisão Temporária

A prisão temporária é uma espécie de prisão cautelar, com objetivo assegurar a eficácia das investigações criminais de crimes graves. Tem prazo de duração preestabelecido.

### Conceitos
- **Prisão Temporária**: espécie de prisão cautelar
- **Lei n.º 7.960/89**: regulamenta a prisão temporária
- **Prazo de Duração**: preestabelecido para a prisão temporária

### Referências legais
- Art. 311 do Código de Processo Penal

### Dicas de prova
- Entenda o objetivo da prisão temporária e como ela se diferencia da prisão domiciliar.
- Conheça a Lei n.º 7.960/89 e seu impacto na regulamentação da prisão temporária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.455 (2)", "page_number": 455, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:28:44.679367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=455", "doc_key": "c9fd4dee1c2f2840ccaf3e84031f4a79"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '43e92f96c968bf29462a3332ff88efdb22bc9c384249da5f1b834c5789f4a347'),
  ('cpiuris2025::9ce07c25dcbf89ae0ab96c3ddcf1cc70', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar pode ser concedida em casos excepcionais, como prática de delito com violência ou grave ameaça contra filhos ou pessoas com deficiência, conforme o art. 318-A do CPP.

### Conceitos
- **Prisão preventiva**: Medida cautelar que impede a liberdade do acusado
- **Prisão domiciliar**: Medida cautelar que substitui a prisão preventiva pela libertação condicional
- **Art. 318-A**: Disposição do Código de Processo Penal que estabelece as hipóteses para a concessão da prisão domiciliar

### Referências legais
- Art. 318-A do CPP

### Jurisprudência
- STJ. 6ª Turma. AgRg no HC 712.258-SP
- STJ. 5ª Turma. HC 487763-SP
- STF. Info 996

### Dicas de prova
- Entenda a diferença entre prisão preventiva e prisão domiciliar
- Conheça as hipóteses previstas no art. 318-A do CPP para a concessão da prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.455 (1)", "page_number": 455, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 318-A do CPP"], "jurisprudence": ["STJ. 6ª Turma. AgRg no HC 712.258-SP", "STJ. 5ª Turma. HC 487763-SP", "STF. Info 996"], "confidence": 0.8, "extracted_at": "2026-05-29T06:28:54.754091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=455", "doc_key": "9ce07c25dcbf89ae0ab96c3ddcf1cc70"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3a473ee7440d9ca879d10cc3a8f825ffecaee4ab9e5e16f7bacda690abe303df'),
  ('cpiuris2025::3965d732e481dd719e20b64d68e6ee60', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Temporária no Processo Penal', '## Prisão Temporária no Processo Penal

A prisão temporária somente pode ocorrer na fase das investigações, sendo imprescindível para as mesmas. Além disso, é necessária a identidade do suspeito e não pode ser decretada com base na mera suposição de que ele irá comprometer a investigação.

### Conceitos
- **Prisão Temporária**: Medida cautelar necessária para as investigações do inquérito policial
- **Fase Pré-processual**: É a fase em que ocorre a prisão temporária, antes da denúncia
- **Princípio da Proporcionalidade**: Requisito para a decretação da prisão temporária, garantindo que não exista outra medida cautelar menos gravosa

### Referências legais
- Art. 1º da Lei em questão

### Jurisprudência
- ADI 3360/DF
- ADI 4109/DF
- Info 1043

### Dicas de prova
- Entenda a distinção entre prisão temporária e prisão preventiva
- Conheça o princípio da proporcionalidade e sua aplicação na decretação da prisão temporária
- Não confunda o indiciamento com o indicado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.456 (1)", "page_number": 456, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º da Lei em questão"], "jurisprudence": ["ADI 3360/DF", "ADI 4109/DF", "Info 1043"], "confidence": 0.8, "extracted_at": "2026-05-29T06:30:02.098376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=456", "doc_key": "3965d732e481dd719e20b64d68e6ee60"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '965a151c9c80ddea6d9848182381e31e8b36f5b8e6a2a1fd25d1060c4c61ee0b'),
  ('cpiuris2025::cad68b7227d805c8e4d78460daa40673', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

É necessário para a decretação da prisão preventiva, mas não é um requisito necessário quando houver fundadas razões de autoria ou participação no crime.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que determina a detenção do acusado antes do julgamento.
- **Lei n.º 12.037/09**: Lei que permite a identificação criminal quando não há identificação civil.
- **STF**: Superior Tribunal Federal, órgão judiciário brasileiro.
- **Requisito necessário**: Elemento essencial para a decretação de uma medida cautelar.
- **Prova admissível**: Evidências legais que podem ser utilizadas como base para a decisão do juiz.

### Referências legais
- Art. 12 da Lei n.º 12.037/09
- Súmula 667 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão Preventiva e Autoria

### Dicas de prova
- Entenda a diferença entre prisão preventiva e requisito necessário.
- Conheça as hipóteses em que a Lei n.º 12.037/09 permite a identificação criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.456 (2)", "page_number": 456, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12 da Lei n.º 12.037/09", "Súmula 667 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão Preventiva e Autoria"], "confidence": 0.8, "extracted_at": "2026-05-29T06:31:10.425641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=456", "doc_key": "cad68b7227d805c8e4d78460daa40673"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ddcaef29f18c8e127c9bdf0b755922123b9ad76fd8f55da82f4d75444637c771'),
  ('cpiuris2025::ed718ccc7e8c25950bb97d9c279eaa7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Lista de crimes que autorizam a tutela cautelar no processo penal, incluindo crimes hediondos e específicos.

### Conceitos
- **Tutela Cautelar**: Medida provisória para proteger direitos ou evitar danos
- **Crime Hediondo**: Tipo de crime que autoriza a prisão temporária e tutela cautelar
- **Lesão Corporal Dolosa**: Lesão grave que pode resultar em morte

