  ('cpiuris2025::6f2e538056012b37b12ac720c09a0a1d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hediondos e crimes contra a saúde', '## Hediondos e crimes contra a saúde

Listagem de crimes hediondos, incluindo suas características específicas e classificação.

### Conceitos
- **Criminoso hediondo**: Pessoa que cometeu um crime hediondo
- **Lesão corporal grave ou morte**: Resultado do crime hediondo
- **Extorsão qualificada**: Restrição da liberdade da vítima, ocorrência de lesão corporal ou morte
- **Sequestro**: Modo de extorsão

