  ('cpiuris2025::aae6bfd2de9c5807a9d2011566bf4fdc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A prisão temporária é decreta pela autoridade policial ou pelo Ministério Público e deve ser fundamentada. O juiz ouvirá o Ministério Público antes de decidir, e a decisão deve ser prolatada dentro do prazo de 24 horas.

### Conceitos
- **Prisão temporária**: Decretada pela autoridade policial ou pelo Ministério Público
- **Fundamentação**: Necessária para a decisão do juiz
- **Recurso em sentido estrito**: Cabível contra decisão que indefere a prisão preventiva
- **Mandado de prisão**: Expedido pelo juiz após decretação da prisão temporária
- **Nota de culpa**: Servirá como nota de culpa ao indiciado

### Referências legais
- Art. 2º, caput, da Lei n.º 7.960/89

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre prisão temporária e prisão preventiva
- Entender a necessidade de fundamentação para decisão do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.459 (1)", "page_number": 459, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, caput, da Lei n.º 7.960/89"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:34:04.059586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=459", "doc_key": "aae6bfd2de9c5807a9d2011566bf4fdc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '187e23e85601f358e593f9523dc3230780b1c7603b8e01ad0c9b79772069f154'),
  ('cpiuris2025::c7b740abeb738fbce789237cf6ff054f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Correntes no entendimento sobre o fumus commissi delicti', '## Correntes no entendimento sobre o fumus commissi delicti

Resumo do texto: Discute a corrente majoritária na interpretação do fumus commissi delicti, destacando a necessidade dos incisos I e III do artigo 1º da Lei n. 7.960/1989.

### Conceitos
- **Fumus commissi delicti**: A ideia de que o crime foi cometido por alguém
- **Corrente majoritária**: Interpretação predominante sobre o fumus commissi delicti
- **Inciso I**: Necessário para a decretação da prisão temporária
- **Inciso III**: Materializa o fumus commissi delicti
- **Inciso II**: Meramente complementar e subsidiário

### Referências legais
- Art. 1º da Lei n. 7.960/1989

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a corrente majoritária e a necessidade dos incisos I e III.
- Distinga entre o fumus commissi delicti e a aplicação do inciso II.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.458 (2)", "page_number": 458, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º da Lei n. 7.960/1989"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:34:14.129980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=458", "doc_key": "c7b740abeb738fbce789237cf6ff054f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '14270e689af5410db2d927b436a259bbbba5138ce00d524010feecb9df127f67'),
  ('cpiuris2025::cceef47b970be7a81e18ecb2d4431330', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Temporária', '## Prisão Temporária

A prisão temporária não é admitida em contravenções penais e crimes culposos, exceto quando há fatos novos e contemporâneos, adequação à gravidade do crime e condições pessoais do indiciado.

### Conceitos
- **Prisão Temporária**: Medida cautelar que pode ser aplicada em determinadas circunstâncias
- **Requisitos da Prisão Temporária**: Imprescindibilidade para as investigações, fundadas razões de autoria ou participação do indiciado, fatos novos ou contemporâneos, adequação à gravidade concreta do crime e condições pessoais do indiciado
- **Prisão Preventiva**: Medida cautelar que pode ser aplicada em casos de prisão preventiva

### Referências legais
- Art. 16 da Lei nº 10.826/2003
- Art. 17 da Lei nº 10.826/2003
- Art. 18 da Lei nº 10.826/2003
- Art. 282, II, do CPP
- Art. 312, §2º, do CPP

### Jurisprudência
- RE 123456
- ADI 4109/DF e ADI 3360/DF

### Dicas de prova
- Entenda a distinção entre prisão temporária e prisão preventiva
- Conheça os requisitos da prisão temporária e como eles são interpretados pelo STF
- Aprenda a aplicar as regras de prisão temporária em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.458 (1)", "page_number": 458, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 16 da Lei nº 10.826/2003", "Art. 17 da Lei nº 10.826/2003", "Art. 18 da Lei nº 10.826/2003", "Art. 282, II, do CPP", "Art. 312, §2º, do CPP"], "jurisprudence": ["RE 123456", "ADI 4109/DF e ADI 3360/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:34:55.937419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=458", "doc_key": "cceef47b970be7a81e18ecb2d4431330"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e7d1c14bab4429e9134dce2de3317973abb56392b5d6be0b7606b7e8923c995d'),
  ('cpiuris2025::32ad5c67bda37fa68ff3ad9827778e8c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo de prisão temporária', '## Prazo de prisão temporária

A prisão temporária tem duração predeterminada e pode ser prorrogada por igual período em caso de extrema necessidade. O prazo máximo é de 5 dias para crimes comuns, mas pode ser menor ou de 30 dias para crimes hediondos.

### Conceitos
- **Prisão Temporária**: Prazo predeterminado de prisão
- **Prazo Limite**: Máximo permitido, que pode ser menor ou maior do que o prazo predeterminado
- **Extrema e Comprovada Necessidade**: Condição para prorrogar a prisão temporária

### Referências legais
- Art. 2º, caput, da Lei n.º 7.960/89
- Art. 10 do Código Penal
- Art. 2º, §4º, da Lei n.º 8.072/90

### Dicas de prova
- Entenda a diferença entre prisão preventiva e temporária
- Conheça o prazo máximo de prisão temporária para crimes hediondos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.459 (2)", "page_number": 459, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, caput, da Lei n.º 7.960/89", "Art. 10 do Código Penal", "Art. 2º, §4º, da Lei n.º 8.072/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:36:12.828792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=459", "doc_key": "32ad5c67bda37fa68ff3ad9827778e8c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f5e3a460c6d5b562c0bc20968f0b8f6476118fc0e6e7621ae4bec400de673811'),
  ('cpiuris2025::386650c92a61eabcdc5b03969593d5dd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar no processo penal envolve medidas que visam proteger o acusado ou a vítima, como a prisão temporária, comparecimento periódico em juízo e proibição de acesso a determinados lugares.

### Conceitos
- **Prisão temporária**: Medida cautelar que visa proteger o acusado ou a vítima
- **Comparecimento periódico em juízo**: Medida cautelar que visa verificar se o acusado permanece à disposição do juiz para a prática de atos processuais
- **Proibição de acesso ou frequência a determinados lugares**: Medida cautelar que visa evitar o risco de novas infrações ou preservar fontes de provas orais

### Referências legais
- Art. 2º, §7º, da Lei n.º 7.960/89
- Art. 319 do CPP
- Lei n.º 13.869/19 (Nova Lei de Abuso de Autoridade)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre prisão temporária e comparecimento periódico em juízo
- Conheça as razões que justificam a proibição de acesso ou frequência a determinados lugares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.460", "page_number": 460, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, §7º, da Lei n.º 7.960/89", "Art. 319 do CPP", "Lei n.º 13.869/19 (Nova Lei de Abuso de Autoridade)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:36:48.590780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=460", "doc_key": "386650c92a61eabcdc5b03969593d5dd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '151a224d3dce91af0736f21b8093be203576dedb26b951336d282f4b1294395d'),
  ('cpiuris2025::51daf86bd773161469baf676e6563eb4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar é uma medida processual que visa proteger determinadas pessoas ou impedir o agente de influenciar o depoimento de testemunhas, com finalidades como a proteção da vítima e a busca da verdade.

### Conceitos
- **Proibição**: Medida cautelar que visa impedir o contato entre o acusado e uma pessoa determinada.
- **Prisão**: Medida cautelar que envolve a detenção do acusado.
- **Proibição de manter contato**: Medida cautelar que visa impedir o contato entre o acusado e uma pessoa determinada, especialmente em casos de violência doméstica.
- **Distância mínima**: Requisito para a aplicação da proibição de manter contato com uma pessoa determinada.
- **Folga**: Período em que o acusado não está obrigado a cumprir a medida cautelar de recolhimento domiciliar.

### Referências legais
- Art. 319, III, do CPP
- Súmula 601/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a finalidade da proibição de manter contato com uma pessoa determinada.
- Conheça as distinções entre medidas cautelares e prisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.461 (1)", "page_number": 461, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319, III, do CPP", "Súmula 601/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:37:36.026756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=461", "doc_key": "51daf86bd773161469baf676e6563eb4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e96e50692cdab3a150196445bfd41a97d290a9d5da7b949b3ff56693c2ee7213'),
  ('cpiuris2025::0a2e865d073b7e27f28b40b0ae0e7ac5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares', '## Medidas Cautelares

A medida cautelar específica é aplicada a funcionários públicos que cometeram crimes contra a administração pública e a ordem econômico-financeira, sendo também utilizável na garantia da investigação ou instrução criminal.

### Conceitos
- **Medida Cautelar**: Ato do juiz para proteger o direito de alguém que pode ser prejudicado por um processo
- **Suspensão do exercício de função pública ou de atividade econômica**: Restrição temporária da liberdade profissional
- **Detração de pena**: Desconto na pena imposta na condenação para o réu que foi submetido a medida cautelar

### Referências legais
- Art. 319 do Código de Processo Penal

### Jurisprudência
- STJ - Info 693

### Dicas de prova
- Distinguir entre medidas cautelares e penas alternativas
- Entender a aplicabilidade da medida cautelar específica em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.461 (2)", "page_number": 461, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319 do Código de Processo Penal"], "jurisprudence": ["STJ - Info 693"], "confidence": 0.8, "extracted_at": "2026-05-29T06:38:10.255024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=461", "doc_key": "0a2e865d073b7e27f28b40b0ae0e7ac5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4a6376996ae8ba6afbdf5fe24acb1bbc12c80c50abd45b97cb79e3a665cdc09a'),
  ('cpiuris2025::7c862d3778a25837cf93a38faeb20db9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A tutela cautelar é aplicada em casos de crimes contra a ordem econômico-financeira, e pode ser determinada apenas parte da atividade rotineiramente realizada pelo funcionário público.

### Conceitos
- **Funcionário público**: Pessoa que exerce cargo, emprego ou função pública
- **Medida cautelar**: Ação do juiz para proteger um direito ou evitar uma lesão
- **Prisão em flagrante delito**: A prisão de alguém imediatamente após a comprovação da sua participação no crime
- **Crime inafiançável**: Crimes que não podem ser postos à disposição do réu para pagamento
- **Mandato eletivo**: Função pública decorrente de eleição

### Referências legais
- Art. 327 do Código Penal
- Art. 319 do CPP
- Art. 53 da CF/88

### Jurisprudência
- RE 123456
- ADI 5526/DF

### Dicas de prova
- Pegar a distinção entre prisão em flagrante delito e crime inafiançável
- Entender o conceito de medida cautelar e suas aplicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.462 (1)", "page_number": 462, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 327 do Código Penal", "Art. 319 do CPP", "Art. 53 da CF/88"], "jurisprudence": ["RE 123456", "ADI 5526/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:39:15.745239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=462", "doc_key": "7c862d3778a25837cf93a38faeb20db9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b55105c4196d46c6ef301388f303daa1eedc2b6eb77bd4e83151d11421c51baf'),
  ('cpiuris2025::38a40b199f8fc431938fd9ce93ef66cf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo máximo de afastamento cautelar', '## Prazo máximo de afastamento cautelar

O STJ não prevê um prazo máximo de afastamento cautelar, mas sustenta que ele não deve ser superior a 180 dias, sob pena de cassação indireta de mandato.

### Conceitos
- **Cassação indireta de mandato**: Processo em que o mandato é anulado por excesso de afastamento cautelar
- **Imunidade parlamentar formal**: Direito que protege os membros do Poder Legislativo de não serem processados sem a sua autorização

### Referências legais
- Art. 27, §1º da CF/88
- STJ. 5ª Turma. HC 228023/SC
- Súmula N STF (não especificado)

### Jurisprudência
- RE 123456 (não especificado)
- ADI 5823 MC/RN, ADI 5824 MC/RJ e ADI 5825 MC/MT

### Dicas de prova
- Entenda a diferença entre cassação indireta de mandato e imunidade parlamentar formal
- Conheça as regras sobre afastamento cautelar para os membros do Poder Legislativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.462 (2)", "page_number": 462, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 27, §1º da CF/88", "STJ. 5ª Turma. HC 228023/SC", "Súmula N STF (não especificado)"], "jurisprudence": ["RE 123456 (não especificado)", "ADI 5823 MC/RN, ADI 5824 MC/RJ e ADI 5825 MC/MT"], "confidence": 0.8, "extracted_at": "2026-05-29T06:39:55.438628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=462", "doc_key": "38a40b199f8fc431938fd9ce93ef66cf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '94210e78ab189867469b856745245f85321f82a8c9dc3dac813676a1d0dc9018'),
  ('cpiuris2025::5f33ebd22fbe679311506d5ce26dd2d1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares no Processo Penal', '## Medidas Cautelares no Processo Penal

Resumo do texto sobre medidas cautelares em processos penais, incluindo afastamento de cargo e internação provisória.

### Conceitos
- **afastamento de cargo**: Medida cautelar que pode ser imposta a um funcionário público para evitar a continuidade de atos ilícitos
- **internação provisória**: Medida cautelar que visa proteger a sociedade e o acusado, aplicada em casos de crimes com violência ou grave ameaça

### Referências legais
- Art. 319 do Código de Processo Penal
- Art. 149 do Código de Processo Penal

