- STJ. Corte Especial. APn 1.041/DF
- STF. Plenário. ADI 4777/BA, ADI 4674/RS, ADI 4362/DF
- STF. Plenário. ADI 5540/MG, Rel. Min. Edson Fachin
- STJ. Corte Especial. APn 1.041/DF

### Dicas de prova
