  ('cpiuris2025::a6dd78973372690ca63cff59c6c94f67', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares Diversas da Prisão', '## Medidas Cautelares Diversas da Prisão

