  ('cpiuris2025::cd0700783a4998bdb4f98ec922266877', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares em Processo de Homicídio', '## Medidas Cautelares em Processo de Homicídio

São descritas medidas cautelares a serem adotadas no processo de homicídio, sendo a medida do inciso V patrimonial e as demais pessoais.

### Conceitos
- **Medida Cautelar**: Ato processual que visa proteger um dos litigantes ou terceiro
- **Natureza Pessoal**: Caracteriza-se como medida que afeta diretamente a pessoa do agressor ou da vítima
- **Medida Cautelar Patrimonial**: Ato processual que visa proteger um dos litigantes ou terceiro, com natureza financeira

### Referências legais
- Art. 319 do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar medidas cautelares de natureza pessoal e patrimonial
- Entender a finalidade das medidas cautelares em processo de homicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.464 (2)", "page_number": 464, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319 do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:42:27.433650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=464", "doc_key": "cd0700783a4998bdb4f98ec922266877"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c364ea98763e0272a7bc496fe9f917593603bcc1a5dc8776ae358ff812a9cf70'),
  ('cpiuris2025::b515a4c805318faf37ac238c1a704e31', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Cautelares Diversas da Prisão', '## Medidas Cautelares Diversas da Prisão

Resumo sobre medidas cautelares não penais, como afastamento do prefeito, suspensão de direção, medidas protetivas de urgência e monitoramento eletrônico.

### Conceitos
- **Medidas Cautelares**: Ações provisórias tomadas pelo juiz para proteger a ordem pública ou garantir a liberdade do réu
- **Monitoramento Eletrônico**: Técnica de vigilância que utiliza dispositivos eletrônicos para rastrear o localização e movimentação de um indivíduo
- **Medidas Protetivas de Urgência**: Ações imediatas tomadas pelo juiz para proteger a vítima de violência doméstica e familiar
- **Afastamento do Prefeito**: Medida cautelar que afasta o prefeito do exercício do cargo durante a instrução criminal
- **Suspensão de Direção**: Medida cautelar que suspende a permissão ou habilitação para dirigir veículo automotor

### Referências legais
- Art. 2º, II, do Decreto-Lei nº 201/67
- Art. 294 do CTB
- Lei Maria da Penha – Lei nº 11.340/06

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre medidas cautelares penais e não penais
- Conheça as finalidades e limites do monitoramento eletrônico
- Identifique as medidas protetivas de urgência aplicáveis às vítimas de violência doméstica e familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.464 (1)", "page_number": 464, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, II, do Decreto-Lei nº 201/67", "Art. 294 do CTB", "Lei Maria da Penha – Lei nº 11.340/06"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:42:51.044515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=464", "doc_key": "b515a4c805318faf37ac238c1a704e31"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b05b5c0dc707e7c645c006120ef634480338989c5c2dcea1d24115cdb0a89276'),
  ('cpiuris2025::3d7ee9d85f4a8c86bbcff60485732d75', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória', '## Liberdade Provisória

A liberdade provisória é um direito subjetivo do cidadão, garantido pelo art. 5º, LXVI da Constituição, e não um poder discricionário do juiz. É concedida com ou sem fiança, e pode ser revogada se as condições resolutórias forem descumpridas.

### Conceitos
- **Liberdade Provisória**: Direito subjetivo do cidadão garantido pela Constituição
- **Fiança**: Medida que pode ser exigida para garantir a presença do acusado nos atos do processo
- **Prisão Preventiva**: Decretada quando presentes requisitos específicos, como a inadmissibilidade das medidas cautelares
- **Medidas Cautelares**: Ações que podem ser tomadas para proteger o direito do acusado

### Referências legais
- Art. 5º, LXVI da Constituição
- Art. 310 e 321 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre liberdade provisória e prisão preventiva
- Conheça as condições resolutórias que podem acarretar a revogação da liberdade provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.465 (1)", "page_number": 465, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXVI da Constituição", "Art. 310 e 321 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:43:10.875679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=465", "doc_key": "3d7ee9d85f4a8c86bbcff60485732d75"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cd87b9053cd8552384de5b0aafd61345c5461386b1dd92f2262f1aefb739a6c5'),
  ('cpiuris2025::521b305a3884a30833e9d3de34dde3bd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória', '## Liberdade Provisória

A liberdade provisória é uma providência cautelar que pode ser autônoma ou cumulada com outras cautelares, podendo ser convertida em prisão caso não seja cumprida. Ela possui classificação em duas espécies: sem fiança e com fiança.

### Conceitos
- **Liberdade Provisória**: providência cautelar que pode ser autônoma ou cumulada
- **Fiança**: obrigação de pagar uma quantia em caso de não cumprimento das obrigações
- **Prisão**: condenação à detenção
- **Cautelares**: providências cautelares que podem ser tomadas antes do julgamento

### Referências legais
- Art. 310, §1º do CPP
- Art. 312, §1º do CPP
- Art. 319 do CPP
- Art. 349 do CPP

### Dicas de prova
- Entenda a diferença entre liberdade provisória sem fiança e com fiança.
- Conheça as consequências de não cumprir as obrigações em caso de liberdade provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.465 (2)", "page_number": 465, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, §1º do CPP", "Art. 312, §1º do CPP", "Art. 319 do CPP", "Art. 349 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:44:06.316196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=465", "doc_key": "521b305a3884a30833e9d3de34dde3bd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2148c2f6d4be98dce3ab04d1aa8488da5d6a38c9fbdc48bd81ef6614f690a127'),
  ('cpiuris2025::6d367fcb347c7328b9315bbe596bd930', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória Sem Fiança', '## Liberdade Provisória Sem Fiança

A liberdade provisória sem fiança pode ser concedida ao acusado se o fato for típico e coberto por excludentes de ilicitude, permitindo-se a interpretação extensiva para abarcar outras excludentes do Código Penal e causas excludentes de culpabilidade.

### Conceitos
- **Liberdade Provisória**: Direito concedido ao acusado antes da sentença, permitindo sua liberdade até o final do processo.
- **Fiança**: Garantia oferecida pelo acusado para garantir seu comparecimento a todos os atos processuais.
- **Excludentes de Ilicitude**: Causas que excluem a ilicitude do fato, como a falta de dolo ou a presença de legítima defesa.
- **Fumus Boni Iuris**: Dúvida razoável sobre a existência da excludente de ilicitude.

### Referências legais
- Art. 310
- Art. 314
- Art. 23 do Decreto-Lei nº 2.848/1940

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre liberdade provisória com e sem fiança.
- Conheça as excludentes de ilicitude e suas interpretações extensivas.
- Aprenda a distinguir entre fumus boni iuris e certeza para conceder liberdade provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.466 (1)", "page_number": 466, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310", "Art. 314", "Art. 23 do Decreto-Lei nº 2.848/1940"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:44:22.887798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=466", "doc_key": "6d367fcb347c7328b9315bbe596bd930"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a81f8213c65cc5dcb9ff45a668f9d9d245915dd149cceaa48854ab73780e007c'),
  ('cpiuris2025::41e93eab591d80b5cc6b62dac08a36f5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fiança e hipóteses de hipoteca', '## Fiança e hipóteses de hipoteca

A fiança pode ser concedida ao delegado de polícia em casos específicos, como infrações com pena máxima inferior a 4 anos. Além disso, há hipóteses em que a hipoteca é instituída, como imóveis, domínio direto, entre outros.

### Conceitos
- **Fiança**: Concessão de garantia para libertar uma pessoa presa
- **Hipótese de hipoteca**: Situações em que a hipoteca é instituída, como imóveis, domínio direto, etc.

### Referências legais
- Art. 322 do CP
- Art. 1.473 do CC

### Dicas de prova
- Entenda a diferença entre fiança e hipótese de hipoteca
- Conheça as hipóteses em que a hipoteca é instituída', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.467 (2)", "page_number": 467, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 322 do CP", "Art. 1.473 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:46:10.291400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=467", "doc_key": "41e93eab591d80b5cc6b62dac08a36f5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '614c9a866824eb55c16b3d351f6cfafff76ca09569175af8e6a7777b09da77f6'),
  ('cpiuris2025::d2ae6ea0918b1691f694de8924e9638d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória com Fiança', '## Liberdade Provisória com Fiança

A fiança é garantia real de cumprimento das obrigações processuais do réu, sendo necessária em casos de hipossuficiência. O objetivo da fiança é assegurar o cumprimento das obrigações processuais e garantir o pagamento das custas processuais.

### Conceitos
- **Fiança**: Garantia real de cumprimento das obrigações processuais do réu
- **Hipossuficiência**: Condição em que o réu não tem recursos suficientes para pagar a fiança
- **Liberdade Provisória**: Período durante o qual o réu é libertado da prisão preventiva, sob condições estabelecidas pela lei
- **Obrigação Processual**: Dever do réu de cumprir as regras e normas processuais

### Referências legais
- Art. 330
- Art. 334
- Art. 336
- Art. 310

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre fiança e caução
- Entender a importância da hipossuficiência na concessão de liberdade provisória com fiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.467 (1)", "page_number": 467, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 330", "Art. 334", "Art. 336", "Art. 310"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:46:50.888131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=467", "doc_key": "d2ae6ea0918b1691f694de8924e9638d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9b1795e81a5434bb1b4a72a6f101b977916205978d71d28988a9c8fde664c190'),
  ('cpiuris2025::2c94ada25e13584281e58d8b2692fdf6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fiança e Liberdade Provisória', '## Fiança e Liberdade Provisória

O juiz pode conceder liberdade provisória a um preso se ele não tiver condições econômicas para pagar fiança, sujeitando-o às medidas constantes dos arts. 327 e 328 do Código.

### Conceitos
- **Fiança**: seguro prestado pelo preso para garantir sua comparecimento ao processo
- **Liberdade Provisória**: condição em que o preso é libertado antes do julgamento, sob certas obrigações
- **Miserabilidade**: impossibilidade de prover às despesas do processo sem prejudicar-se ou à família
- **Fiança não necessária**: direito do preso a não ser obrigado a pagar fiança em determinadas situações
- **Dispensa da Fiança**: direito do preso a não ser obrigado a pagar fiança, que não é decisão discricionária do juiz
- **Obrigações do Preso**: medidas cautelares impostas ao preso em liberdade provisória
- **Processo Penal**: procedimento jurídico que regula a investigação e julgamento de crimes

### Referências legais
- Art. 32, §1º, do CPP; Art. 327; Art. 328; Art. 350

### Dicas de prova
- Entenda o conceito de miserabilidade e como ela afeta a decisão sobre fiança
- Leia atentamente as obrigações do preso em liberdade provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.466 (2)", "page_number": 466, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 32, §1º, do CPP; Art. 327; Art. 328; Art. 350"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:47:22.550659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=466", "doc_key": "2c94ada25e13584281e58d8b2692fdf6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c1df7f96d4fcebfaeca019885a26c2b67329b2cc9585021af0b4b89f6bad871d'),
  ('cpiuris2025::b920080a7f0067454b4b8254f177f68f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fiança e Condenação', '## Fiança e Condenação

Não será concedida fiança a quem quebrou fiança anterior, infringe obrigações previstas nos arts. 327 e 328, está preso civil ou militar, ou tem motivos para prisão preventiva.

### Conceitos
- **Fiança**: Garantia de liberdade do acusado
- **Condenação**: Decisão que condena o acusado
- **Prisão Preventiva**: Medida cautelar para garantir a presença do acusado nos processos judiciais
- **Transgressões Disciplinares**: Infrações cometidas por militares dentro da estrutura militar

### Referências legais
- Art. 324 do Código de Processo Penal

### Dicas de prova
- Distinção entre fiança e prisão preventiva
- Importância dos arts. 327 e 328 no Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.468 (2)", "page_number": 468, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 324 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:48:38.554818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=468", "doc_key": "b920080a7f0067454b4b8254f177f68f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '882c3bb0c2940c84d12c7069486b0a7de4f512be49d712ac56315f37003f1034'),
  ('cpiuris2025::4b00d97260c4bf330b3948065cbf9dd3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

O artigo 335 estabelece que o preso ou alguém por ele pode solicitar a concessão da fiança perante o juiz competente, dentro de 48 horas. A autoridade policial não pode recusar a conceder fiança sem decisão do magistrado.

### Conceitos
- **Fiança**: Garantia pecuniária para o preso durante o processo
- **Autoridade policial**: Ente responsável pela prisão e condução do acusado
- **Juiz competente**: Magistrado responsável por decidir sobre a concessão da fiança
- **Prisão em flagrante**: Prisão realizada durante o ato criminoso
- **Prisão por mandado**: Prisão ordenada pelo juiz para cumprir uma ordem
- **Custo do processo**: Despesas relacionadas ao processo, incluindo custas judiciais e indenização

### Referências legais
- Art. 335
- Art. 332
- Art. 325
- Art. 326
- Art. 323

### Dicas de prova
- Entenda a diferença entre prisão em flagrante e prisão por mandado
- Conheça as condições para conceder fiança, incluindo a natureza da infração e as condições pessoais do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.468 (1)", "page_number": 468, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 335", "Art. 332", "Art. 325", "Art. 326", "Art. 323"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:48:52.504800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=468", "doc_key": "4b00d97260c4bf330b3948065cbf9dd3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '85fe2afcd925cf155659e6c41bb06e64aa3d355098a0b975894323628472c082'),
  ('cpiuris2025::ecb197559987887a00b97fece3db182e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A fiança é um termo obrigatório para o réu afiançado, que deve comparecer perante a autoridade processante em todas as vezes que for intimado. O quebramento da fiança ocorre quando o réu não comparece ou não cumpre com suas obrigações, e pode ser determinado pela autoridade judiciária.

### Conceitos
- **Fiança**: Termo obrigatório para o réu afiançado
- **Quebramento da fiança**: Ocorrência quando o réu não comparece ou não cumpre com suas obrigações
- **Autoridade processante**: Entidade responsável por iniciar e seguir o processo penal
- **Obrigações do afiançado**: Deveres do réu afiançado para cumprir com suas promessas

### Referências legais
- Art. 327 do CPP
- Art. 328 do CPP
- Art. 329 do CPP
- Art. 341 do CPP

### Dicas de prova
- Entenda a importância da fiança no processo penal
- Conheça as hipóteses de quebramento da fiança
- Avalie a responsabilidade do réu afiançado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.469 (1)", "page_number": 469, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 327 do CPP", "Art. 328 do CPP", "Art. 329 do CPP", "Art. 341 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:49:47.076203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=469", "doc_key": "ecb197559987887a00b97fece3db182e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '60f4312785d2612291389ed2e9cf9cceb95c9b42abf064499e21f58224f771ec'),
  ('cpiuris2025::130a5d9663bbeec7aeba56999c25ec4b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Regra para reforço da fiança em casos específicos e consequências para o réu e a fiança.

### Conceitos
- **Fiança**: Garantia oferecida pelo réu para garantir sua participação no processo
- **Reforço da fiança**: Aumento do valor da fiança em casos específicos
- **Prisão**: Medida cautelar que determina a detenção do réu
- **Miserabilidade**: Condição que permite dispensa de reforço da fiança

### Referências legais
- Art. 340 do Código de Processo Penal

### Dicas de prova
- Reforço da fiança é obrigatório em casos específicos
- Prisão não pode ocorrer de forma automática, devendo ser verificados os requisitos dos art. 312 e 313 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.470 (1)", "page_number": 470, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 340 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:50:39.533752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=470", "doc_key": "130a5d9663bbeec7aeba56999c25ec4b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '41ac94951117eab6568f91467550f3c6cedb53cb31465d7268de99a2fa727ea7'),
  ('cpiuris2025::1b2618ce434794603eb00640ecb01939', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fiança e Recursos', '## Fiança e Recursos

Resumo do texto sobre fiança e recursos no processo penal.

### Conceitos
- **Perda da Fiança**: Ocorre quando o condenado não se apresenta para o início do cumprimento da pena definitivamente imposta.
- **Recurso em Sentido Estrito**: Cabível com efeito suspensivo, especialmente após a declaração da fiança pelo juízo da execução.
- **Cassação da Fiança**: Ocorre quando não for cabível ou quando reconhecida a existência de delito inafiançável.
- **Fiança Inidônea**: Quando a fiança é cassada, o valor prestado será totalmente devolvido.
- **Recurso em Apelação**: Cabível quando a decisão de cassação da fiança for tomada em sentença condenatória.
- **Reforço da Fiança**: Determinado pelo juiz, especialmente em casos de inadimplência.

### Referências legais
- Art. 344
- Art. 581, VII
- Art. 584
- Art. 197
- Art. 338
- Art. 339
- Art. 581, V
- Art. 593, §4º

### Dicas de prova
- Entenda a diferença entre perda e reforço da fiança.
- Conheça as hipóteses de cassação da fiança e os recursos cabíveis.
- Aprenda a distinguir entre recurso em sentido estrito e apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.469 (2)", "page_number": 469, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 344", "Art. 581, VII", "Art. 584", "Art. 197", "Art. 338", "Art. 339", "Art. 581, V", "Art. 593, §4º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:51:32.509878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=469", "doc_key": "1b2618ce434794603eb00640ecb01939"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aeb1884b4f9fcd510e4534f2288be6983e7c886cac1138b7446b0cf3851b4087'),
  ('cpiuris2025::6fbda6837c0f6b5abdc08e80964304fd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Quebra de Fiança', '## Quebra de Fiança

O juiz determinará a venda da fiança por leiloeiro ou corretor quando o réu não comparecer perante a autoridade, seja por mudança de residência sem permissão ou ausência superior a 8 dias sem comunicação. Além disso, também se aplica quando o acusado é intimado e não comparece sem motivo justo, pratica ato de obstrução ao processo ou descumprir medida cautelar imposta cumulativamente com a fiança.

### Conceitos
- **Quebra de Fiança**: Fim da fiança do réu
- **Leiloeiro**: Entidade responsável pela venda da fiança
- **Art. 349**: Disposição legal que determina a venda da fiança por leiloeiro ou corretor
- **Intimado**: Pessoa que recebe notificação para comparecer em um ato do processo
- **Motores Justos**: Motivos legítimos para não comparecimento ao ato processual

### Referências legais
- Art. 327
- Art. 328
- Art. 341

### Dicas de prova
- Diferenciar entre os motivos que justificam a quebra de fiança
- Entender o papel do leiloeiro na venda da fiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.470 (2)", "page_number": 470, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 327", "Art. 328", "Art. 341"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:52:12.077552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=470", "doc_key": "6fbda6837c0f6b5abdc08e80964304fd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '39029492d9d502b9726069dc0c05ac9cd3eb1ff95fd6ad5f3177bccf1e2b3961'),
  ('cpiuris2025::8bca23c4d14f02c7a64b51288989e51c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória', '## Liberdade Provisória

A liberdade provisória é um direito do acusado, mas há hipóteses em que é proibida. A lei infraconstitucional pode prever a concessão de liberdade provisória mediante pagamento de fiança, mas não é obrigatória.

### Conceitos
- **Liberdade Provisória**: direito do acusado
- **Prisão Cautelar Obrigatória**: retirada da atribuição de analisar a necessidade da prisão cautelar em cada caso concreto
- **Presunção de Inocência**: princípio que assegura ao acusado o benefício da dúvida
- **Reincidente**: agente que cometeu crime anteriormente

### Referências legais
- Art. 341, IV; Art. 344; Art. 338; Art. 339; Art. 340, parágrafo único; Art. 69, parágrafo único da Lei n.º 9.099/95

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre liberdade provisória obrigatória e proibida.
- Conheça as hipóteses em que a prisão cautelar é obrigatória.
- Aprenda sobre o princípio da presunção de inocência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.471 (1)", "page_number": 471, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 341, IV; Art. 344; Art. 338; Art. 339; Art. 340, parágrafo único; Art. 69, parágrafo único da Lei n.º 9.099/95"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:53:16.430781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=471", "doc_key": "8bca23c4d14f02c7a64b51288989e51c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cb2e58bc5dcf5fbb6177dca3e661cb8eb8db2cf53b07e5b4e217692c2ea0fb0f'),
  ('cpiuris2025::cfe0344684e59bd6f04e1639568472f8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade Provisória e Vinculação', '## Liberdade Provisória e Vinculação

A liberdade provisória pode ser concedida com ou sem medidas cautelares, dependendo da hipótese. A vinculação é menor em casos de comparecimento a todos os atos processuais.

### Conceitos
- **Liberdade Provisória**: Concessão de liberdade antes do julgamento do processo
- **Vinculação**: Restrição à liberdade do agente durante o processo
- **Medidas Cautelares**: Ações processuais tomadas para proteger a ordem pública ou os direitos de terceiros
- **Prisão Preventiva**: Decisão do juiz que determina a prisão do agente antes do julgamento do processo

### Referências legais
- Art. 350, caput; Arts. 322 a 349; Art. 310, §1º; Art. 314; Art. 315
- Súmula 743/2017 STF

### Jurisprudência
- RE 123456
- Súmula 743/2017 STF

### Dicas de prova
- Diferenciar entre liberdade provisória com e sem medidas cautelares
- Entender a importância da vinculação na liberdade provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.471 (2)", "page_number": 471, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 350, caput; Arts. 322 a 349; Art. 310, §1º; Art. 314; Art. 315", "Súmula 743/2017 STF"], "jurisprudence": ["RE 123456", "Súmula 743/2017 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T06:53:49.937262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=471", "doc_key": "cfe0344684e59bd6f04e1639568472f8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e6b487fe7ddbb69c4f4d0c779d3f645d17817f94928baabb509f04574857887b'),
  ('cpiuris2025::138adc4d4324c467d3607462415c2481', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Resumo do texto sobre tutela cautelar no processo penal, incluindo liberdade provisória sem vinculação e prisão preventiva.

### Conceitos
- **Liberdade provisória**: ocorre quando o agente é posto em liberdade sem qualquer dever processual
- **Prisão preventiva**: medida adotada para garantir a segurança do Estado, com base na existência de fatos novos ou contemporâneos que justifiquem a aplicação da medida
- **Flagrante presumido**: hipótese em que o agente é perseguido logo após a prática do fato delituoso, com presunção de ser autor da infração

### Referências legais
- Art. 5º, XI, XLIX, LVIII LXI a LXVII, da CF/88
- Arts. 282 a 350 do CPP
- Lei n.º 7.960/89

### Dicas de prova
- Diferenciar entre liberdade provisória e prisão preventiva
- Entender o conceito de flagrante presumido
- Conhecer as hipóteses em que a prisão preventiva é concedida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.472 (1)", "page_number": 472, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XI, XLIX, LVIII LXI a LXVII, da CF/88", "Arts. 282 a 350 do CPP", "Lei n.º 7.960/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:54:38.346045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=472", "doc_key": "138adc4d4324c467d3607462415c2481"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a9177ef094dc89882f154201f9aed8e8f81f389291c3804a4f3d11ee05f4cc95'),
  ('cpiuris2025::093c0a454cf552066032f7f940d140b7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Temporária e Medidas Cautelares', '## Prisão Temporária e Medidas Cautelares

Resumo sobre a prisão temporária e suas características, incluindo a suspensão de função pública ou atividade econômica.

### Conceitos
- **Prisão Temporária**: Medida cautelar que suspende a liberdade de alguém sem a imposição de pena
- **Lei nº 7.960/1989**: Lei que regulamenta a prisão temporária
- **Suspensão de função pública ou atividade econômica**: Medida cautelar diversa da prisão, cabível independentemente de receio de utilização da função ou atividade para prática de infrações penais

### Referências legais
- Art. 1º da Lei nº 7.960/1989
- Súmula 643 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão Temporária

### Dicas de prova
- Distinção entre prisão temporária e suspensão de função pública ou atividade econômica
- Recebo da medida cautelar e prazo máximo de 5 dias para feminicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.472 (2)", "page_number": 472, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º da Lei nº 7.960/1989", "Súmula 643 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão Temporária"], "confidence": 0.8, "extracted_at": "2026-05-29T06:55:21.282492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=472", "doc_key": "093c0a454cf552066032f7f940d140b7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '604358a716e9a94446bce92818c9822eb0a1dd792b138c08b42ba12140c2d4e6'),
  ('cpiuris2025::8759e701f0edd00ceed0a5e8ae2d94ed', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Resumo sobre as medidas cautelares em processo penal, incluindo prisão preventiva e domiciliar.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que impede o acusado de deixar o país ou de se ausentar
- **Domiciliar**: Medida cautelar que mantém o acusado em sua residência, sob vigilância eletrônica
- **Suspensão do exercício da função pública**: Medida cautelar aplicada a servidores públicos
- **Internação provisória**: Medida cautelar para acusados inimputáveis ou semi-imputáveis

### Referências legais
- Art. 311 do Código de Processo Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferencie entre prisão preventiva e domiciliar
- Entenda a aplicabilidade da suspensão do exercício da função pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.473 (1)", "page_number": 473, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do Código de Processo Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T06:55:47.407462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=473", "doc_key": "8759e701f0edd00ceed0a5e8ae2d94ed"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fb9f59da9c28a7e506613ab165256d1f46d8bdaebf1b24cc2674985acfd34f55'),
  ('cpiuris2025::120718af87ba5e9788226fb01ff49254', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência de Custódia e Fiança', '## Audiência de Custódia e Fiança

O juiz deve evitar formular perguntas que produzam provas sobre os fatos do auto da prisão em flagrante, mas pode indagar sobre o tratamento recebido pelo autuado antes da audiência.

### Conceitos
- **Audiência de Custódia**: procedimento judicial que visa determinar a custódia de uma pessoa
- **Fiança**: garantia oferecida por alguém para garantir o cumprimento das obrigações do autuado
- **Perguntas na Audiência**: formuladas pelo juiz para obter informações sobre os fatos do caso

### Referências legais
- Código de Processo Penal
- ...

### Jurisprudência
- Súmula 343/STF
- ...

### Dicas de prova
- Perguntas na Audiência: distinção entre perguntas que produzem provas e perguntas que buscam informações sobre o tratamento do autuado
- Fiança: garantia oferecida para garantir o cumprimento das obrigações do autuado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.473 (2)", "page_number": 473, "discipline": "Direito Processual Penal", "legal_refs": ["Código de Processo Penal", "..."], "jurisprudence": ["Súmula 343/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T06:56:19.819524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=473", "doc_key": "120718af87ba5e9788226fb01ff49254"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '971658305316cb106d27b9e7afbf5c909696181764763c21d10edeaaede24674'),
  ('cpiuris2025::7e914a0c6a3ce6383b8d3ea417a2709d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A fiança tomada por termo obrigará o afiançado a comparecer perante a autoridade todas as vezes que for intimado para atos do inquérito e da instrução criminal e para o julgamento. A fiança será cassada quando o réu não comparecer, sem motivo justo.

### Conceitos
- **Fiança**: Tomada por termo obrigatório
- **Comparecimento obrigatório**: O afiançado deve comparecer às vezes que for intimado para atos do inquérito e da instrução criminal e para o julgamento
- **Cassação da fiança**: A fiança será cassada quando o réu não comparecer, sem motivo justo

### Referências legais
- Art. 16 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre comparecimento obrigatório e comparecimento voluntário
- Conheça as condições para cassação da fiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.474 (1)", "page_number": 474, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 16 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:56:31.369705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=474", "doc_key": "7e914a0c6a3ce6383b8d3ea417a2709d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f701baad62d3ac876b4f14ec6d4240813d2e5410522a95f6b6dcd84eef9ba40d'),
  ('cpiuris2025::94423543c3b0f8b5fb0504a1cf0d9507', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A questão discute a concessão de fiança em diferentes situações, incluindo crimes tentados e qualificados. A resposta correta é a alternativa D, que afirma que o delito de roubo cometido com restrição de liberdade da vítima é inafiançável.

### Conceitos
- **Fiança**: Condição em que o investigado ou acusado é libertado, sob a responsabilidade de cumprir as penas impostas
- **Crime hediondo**: Delito que, devido à sua natureza grave e prejudicial, é punido com pena especial
- **Prisão preventiva**: Medida cautelar que determina a prisão do acusado antes da sentença final

### Referências legais
- Art. 2º, II, da Lei nº 8.072/90

### Dicas de prova
- Entenda a diferença entre fiança e prisão preventiva
- Conheça as regras para a concessão de fiança em crimes tentados e qualificados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.475", "page_number": 475, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, II, da Lei nº 8.072/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:58:51.302020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=475", "doc_key": "94423543c3b0f8b5fb0504a1cf0d9507"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2fd18de6e5b20ef60e999d1f444f0727cdfed9c6ffd93c7fe5e2c34fee332f94'),
  ('cpiuris2025::016cbbc4fa9b6dc0cab860a41cc18524', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Temporária e Preventiva', '## Prisão Temporária e Preventiva

A prisão temporária é cabível quando imprescindível para as investigações do inquérito policial, especialmente em casos de epidemia. A prisão preventiva é medida subsidiária que pode ser decreta em caso de agressor após frustração de outras medidas cautelares menos gravosas.

### Conceitos
- **Prisão Temporária**: medida cabível quando imprescindível para as investigações do inquérito policial
- **Prisão Preventiva**: medida subsidiária que pode ser decreta em caso de agressor após frustração de outras medidas cautelares menos gravosas
- **Lei nº 11.340/2006**: Lei que estabelece a prisão preventiva como medida subsidiária
- **Art. 267, §1º do Código Penal**: Crime de causar epidemia mediante propagação de germes patogênicos
- **Art. 318 do Código de Processo Penal**: Disposição que permite substituição da prisão preventiva pela domiciliar em certas situações

### Referências legais
- Art. 267, §1º do Código Penal
- Art. 318 do Código de Processo Penal
- Lei nº 11.340/2006

### Dicas de prova
- Distinção entre prisão temporária e preventiva
- Conhecimento da Lei nº 11.340/2006
- Aplicação do Art. 318 do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.474 (2)", "page_number": 474, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 267, §1º do Código Penal", "Art. 318 do Código de Processo Penal", "Lei nº 11.340/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T06:59:29.709666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=474", "doc_key": "016cbbc4fa9b6dc0cab860a41cc18524"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'db3b0713ab2dce197bf0833917bbe79a0c266480c49129540588965568fe2565'),
  ('cpiuris2025::672b6c32ac05da88ceb3797d05554c9f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

A questão discute a aplicabilidade de medidas cautelares em diferentes situações, destacando a importância da previsão legal e da interpretação correta do código processual penal.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que impede o acusado de sair do país ou de deixar o território nacional
- **Flagrante Próprio**: Situação em que o acusado é capturado no ato da comissão do crime
- **Prisão Temporária**: Medida cautelar que impede o acusado de sair do país ou de deixar o território nacional, geralmente aplicada em crimes hediondos
- **Contraditório Prévio**: Procedimento que permite ao acusado expressar sua opinião sobre a medida cautelar antes de sua decisão final
- **Pena**: Sancionamento aplicado ao acusado em caso de condenação

### Referências legais
- Art. 2º, §4º-A, da Lei nº 7.960/89
- Art. 2º, §7º, da Lei nº 7.960/89
- Art. 282, §1º, do CPP
- Art. 282, §3º, do CPP
- Art. 282, §5º, do CPP
- Art. 315, §2º, I, do CPP
- Art. 316, do CPP
- Art. 319, VI, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a previsão legal e a interpretação correta do código processual penal.
- Identifique as hipóteses em que cada medida cautelar é aplicada.
- Aprenda a distinguir entre flagrante próprio, prisão temporária e contraditório prévio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.476", "page_number": 476, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 2º, §4º-A, da Lei nº 7.960/89", "Art. 2º, §7º, da Lei nº 7.960/89", "Art. 282, §1º, do CPP", "Art. 282, §3º, do CPP", "Art. 282, §5º, do CPP", "Art. 315, §2º, I, do CPP", "Art. 316, do CPP", "Art. 319, VI, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:00:08.767019+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=476", "doc_key": "672b6c32ac05da88ceb3797d05554c9f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6b943cd1dc31c344844aacb258f3b7eb42bd11421ecbb690da9217b4b61a3ced'),
  ('cpiuris2025::083d28b8ed3e8109589e3b2c0510b440', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Resumo sobre as hipóteses de tutela cautelar no processo penal, conforme o art. 318 do CPP.

### Conceitos
- **Art. 318 do CPP**: Regula a hipótese de tutela cautelar no processo penal
- **Fiança**: Condição para a libertação da pessoa condenada ou acusada
- **Prisão preventiva**: Medida cautelar que determina a detenção da pessoa condenada ou acusada

### Referências legais
- Art. 318, I, II e IV do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tutela cautelar no processo penal

### Dicas de prova
- Entenda a diferença entre prisão preventiva e fiança
- Conheça as hipóteses de tutela cautelar previstas no art. 318 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.477 (1)", "page_number": 477, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 318, I, II e IV do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tutela cautelar no processo penal"], "confidence": 0.8, "extracted_at": "2026-05-29T07:00:48.250995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=477", "doc_key": "083d28b8ed3e8109589e3b2c0510b440"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '02b7fc3286107caa17a44e426528ff1f2f602d00a9162361c202d4f87bc1462a'),
  ('cpiuris2025::192ca57f0372c5ad2fd3a2c548be9318', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva pode ser concedida se houver causa excludente de ilicitude, conforme art. 310, §1º, do CPP.

### Conceitos
- **causa excludente de ilicitude**: fator que justifica a não imputação da ilicitude ao autor do crime
- **liberdade provisória**: condenação temporária do réu à prisão, sem a imposição de pena definitiva
- **crime hediondo**: tipo de crime que não pode ser julgado em juiz de direito e não é suscetível de fiança
- **prisão preventiva**: condenação temporária do réu à prisão, com o objetivo de garantir a segurança pública

### Referências legais
- Art. 310, §1º, do CPP
- Art. 318, VI, do CPP
- Art. 2º, II, da Lei nº 8.072/90

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre causa excludente de ilicitude e liberdade provisória
- Conhecimento do tipo de crime hediondo e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.477 (2)", "page_number": 477, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, §1º, do CPP", "Art. 318, VI, do CPP", "Art. 2º, II, da Lei nº 8.072/90"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:01:50.382241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=477", "doc_key": "192ca57f0372c5ad2fd3a2c548be9318"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '236b75a216efdaa6d247b6221a7acc11b77c4b3765ff86e8489f3979c18026b3'),
  ('cpiuris2025::164cce76abd753444ef6751403a90598', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Comunicação dos Atos Processuais', '## Comunicação dos Atos Processuais

A comunicação dos atos processuais é necessária para o contraditório e a ampla defesa. Existem três meios de comunicação: citação, intimação e notificação.

### Conceitos
- **Citação**: Dá ciência ao acusado sobre o recebimento de uma denúncia ou queixa contra si
- **Intimação**: Dá ciência à parte sobre um ato já praticado
- **Notificação**: Dá ciência sobre um ato que deve ser praticado no futuro pela parte
- **Circundução**: Ato que julga nula a citação

### Referências legais
- Art. 564 do CPP
- Art. 164 da Lei de Execução Penal

### Dicas de prova
- Diferenciar entre citação, intimação e notificação
- Entender a finalidade da citação e sua importância no processo penal
- Conhecer o conceito de circundução e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.479", "page_number": 479, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564 do CPP", "Art. 164 da Lei de Execução Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:02:28.653209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=479", "doc_key": "164cce76abd753444ef6751403a90598"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ab3c6b2b2cd50c2ef705e955e8b7808a90e45112e3b01db6b7833a552769a550'),
  ('cpiuris2025::ca9d037eaa7185d899a0031daa472740', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação do Acusado no Processo Penal', '## Citação do Acusado no Processo Penal

A citação do acusado é necessária para formar a relação processual e estabelecer o actum trium personarum. Ela pode ser real ou pessoal, e existe uma presunção legal de que o acusado teve ciência do processo.

### Conceitos
- **Citação Real**: Feita pessoalmente ao acusado
- **Citação Pessoal**: Mandado, carta precatória, carta de ordem ou carta rogatória
- **Citação Ficta**: Excepcional, utilizada quando o acusado não foi encontrado
- **Presunção Legal**: O acusado teve ciência do processo

### Referências legais
- Art. 164 da LEP
- Art. 363 do CPP
- Art. 75 do CPP
- Art. 117, I, do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre citação real e pessoal
- Conheça as espécies de citação (real, pessoal e ficta)
- Aprenda sobre a presunção legal que o acusado teve ciência do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.480", "page_number": 480, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 164 da LEP", "Art. 363 do CPP", "Art. 75 do CPP", "Art. 117, I, do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T07:03:08.505020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=480", "doc_key": "ca9d037eaa7185d899a0031daa472740"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4f83d1b1799fe67d200622a5bb00e36a7072d5676543e4fedc9e123b4c113dfd'),
  ('cpiuris2025::36cd604fdce3702954b26ee6685a5a38', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação inicial no processo penal', '## Citação inicial no processo penal

A citação inicial deve ser feita por mandado, assinado por juiz competente, e indicará o nome do juiz, do querelante, do réu e sua residência.

### Conceitos
- **Mandado de citação**: Ordem escrita assinada por juiz competente para cumprir um oficial de justiça
- **Requisitos intrínsecos do mandado de citação**: Nome do juiz, nome do querelante, nome do réu ou sinais característicos, residência do réu e fim da citação

### Referências legais
- Art. 351
- Art. 352

### Dicas de prova
- Reconheça a necessidade de mandado para a citação inicial
- Identifique os requisitos intrínsecos do mandado de citação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.481 (2)", "page_number": 481, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 351", "Art. 352"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T07:04:07.495695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=481", "doc_key": "36cd604fdce3702954b26ee6685a5a38"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a1ddf999cbb058753993c0242db60781aae1081375d3c3ccba988cd684ecae9'),
  ('cpiuris2025::540f235deb72a19cf921c3978ac6e9ab', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Citação Pessoal no Processo Penal', '## Citação Pessoal no Processo Penal

A citação pessoal é obrigatória na pessoa do acusado, não de seu representante legal ou procurador autorizado. A citação somente ocorre na pessoa do próprio acusado e não pode ser feita por meio de correio, eletrônica, telefone ou whatsapp.

### Conceitos
- **Citação Pessoal**: Obrigatória na pessoa do acusado
- **Representante Legal**: Não pode ser citado em nome de seu representante legal
- **Procurador Autorizado**: Não pode ser citado em nome de procurador autorizado
- **Citação por Correio**: Não é permitida no processo penal
- **Citação por Eletrônica**: Não é permitida no processo penal
- **Citação por Telefone**: Não é permitida no processo penal
- **Citação por Whatsapp**: Pode ser admitida, desde que medidas suficientes sejam adotadas para atestar a autenticidade do número telefônico e identidade do indivíduo destinatário
- **Mandado de Citação**: O meio pelo qual a citação pessoal ocorre

### Referências legais
- Art. 17 da Lei nº 9.039/96
- STJ. 6ª Turma. REsp 1580435-GO

### Jurisprudência
- RE 123456
- Info 688

### Dicas de prova
- Distinção entre citação pessoal e representante legal
- Importância da autenticidade do número telefônico e identidade do indivíduo destinatário na citação por whatsapp', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.481 (1)", "page_number": 481, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 17 da Lei nº 9.039/96", "STJ. 6ª Turma. REsp 1580435-GO"], "jurisprudence": ["RE 123456", "Info 688"], "confidence": 0.8, "extracted_at": "2026-05-29T07:04:52.039047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=481", "doc_key": "540f235deb72a19cf921c3978ac6e9ab"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2c5ce7405fa94364dd059aa94cc158e399e2cfeb72dbf6c3c0b43a5698d4aebc')
